quests[13927] = { id = 13927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Waisenkind Kekek von den Wolvar", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, {name}. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, {name}, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", sourceObjective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Wolvarwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", progress = "Waisenfrau sagen, Kekek mit dir gehen.", completion = "Du bringst Kekek zum Jagen? Ist gut von alter Waisendame wegzukommen, die Kekek nicht jagen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13928] = { id = 13928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Gefallenen", description = "Meine Schildwachen und ich haben von Bewahrer Ordanus den Befehl erhalten, hier zu bleiben und den Turm zu verteidigen. Bisher konnten wir die Horde erfolgreich zurückschlagen, aber jetzt schlagen sie einen Bogen um uns und greifen unseren Zufluchtsort im Norden direkt an.\n\nDer Bewahrer schickt seine Dryaden aus, um die Bäume zu verteidigen, aber sie scheinen der Vorhut der Kriegshymnenorcs nicht gewachsen.\n\nIhr müsst dorthin und so viele Leichen der Lachenden Schwestern einsammeln, wie Ihr könnt. Bringt sie zu Halannia im Baum am Zufluchtsort. Sie wird wissen, was zu tun ist.", sourceObjective = "Sammelt 10 Leichen der Lachenden Schwestern.", progress = "Ich bin erstaunt, dass Ihr die Reihen der Horde durchbrechen konntet und es geschafft habt, hier hereinzukommen, {race}.", completion = "Habt Dank, {class}. Wir haben alle Hände voll damit zu tun, diesen Zufluchtsort zu verteidigen, aber wenn ich wieder zu Atem komme, werde ich dafür sorgen, dass diese Schwestern ins Leben zurückkehren, wenn es der Göttin gefällt.\n\nIhr habt Euren Heldenmut bewiesen... Wir könnten Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13929] = { id = 13929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der grööößte Baum überhaupt!", description = "Bevor der große Krieg passiert war und wir das Dorf verlassen haben, wir erinnern uns dran, wie Soo-say uns vom größten von allen Bäumen erzählt hat!\n\nSoo-say es nennen Grauschlund oder so. Soo-say uns erzählen, es ist in der Mitte von den Kritzlihügeln. Nein, warte. Das nicht was Soo-say gesagt hat. Soo-say sagt Grizzlyhügel. Jetzt wir uns erinnern! Großer Baum und in der Mitte von Grizzlyhügeln. Kann gar nicht übersehen!\n\nDu uns bringen dahin, oki? Wir uns anschauen den großen Baum von innen? Soo-say sagen, große Bärenleute leben auch im Baum. Vielleicht wir sie auch sehen.", sourceObjective = "Besucht mit Eurem Waisenkind Roo den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", completion = "Wir haben nicht gewusst, dass Bäume sooo groß werden können. Nee. Vielleicht die Großen hatten besonderen Plan für sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[13930] = { id = 13930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimat der Bärenleute", description = "Hochschamane Rakjak uns immer Geschichten von mächtigen Kriegern erzählt, auch von weit weit weg. Manchmal er hat erzählt über riesige Bärenleute, wo einen großen Krieg um eine große Baumstadt kämpfen.\n\nVielleicht du bringt Kekek dort hin, Baum anschauen, Kampf anschauen! Hochschamane Rakjak erzählt Kekek, die große Baumstadt Grauschlund steht in der Mitte von den Grizzlyhügeln.\n\nKekek hat nie eine Stadt gesehen, bevor er kennengelernt hat die Waisendame, aber die Stadt hier hat keine Krieger, nur Männer in lila Kleidern. Kekek will richtige Krieger sehen, die um eine richtige Stadt kämpfen.", sourceObjective = "Besucht mit Eurem Waisenkind Kekek den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", completion = "Das sein Kekeks Art von Stadt. Bärenleute kämpfen genauso um ihr Zuhaus, wie Wildherzen es tun. Waisendame sagt Kekek, er soll nicht mit anderen Welpen kämpfen. Kekek kämpft trotzdem.", sourceObjectiveStatus = "unverified-source-field" }
quests[13931] = { id = 13931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Jahr, ein neues Souvernir", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13932] = { id = 13932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Jahr, ein neues Souvernir", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Gutscheine einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...\n\nooohhh.... oder seins...", sourceObjectiveStatus = "unverified-source-field" }
quests[13933] = { id = 13933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bronzedrachenschrein", description = "Manchmal Hochorakel Soo-say erzählt Geschichten über Schreine für Drachendinger, nicht wie großer Regenstein, aber anders. Soo-say sagt uns, vielleicht wir uns dort selbst sehen, aber nicht wie in Glitzer-Glitzer. Soo-say meint, wir uns dort sehen, wie wenn in vielen Jahren später.\n\nBringst du uns dorthin? Wir uns erinnern, Schrein für Bronzedrachendinger ist in einem Ort, der Drachenöde heißt. Soo-say sagt, großer Regenstein zeigt ihm Schrein im Nordosten vom Wyrmruhtempel, oder nordwestlich von einem Ort, den die Trockenhäute Feste Wintergarde nennen. Wir gehen?", sourceObjective = "Besucht mit Eurem Waisenkind Roo den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Wir sind sehr glücklich, dass du uns hierhergebracht hast, {name}. Wir haben uns immer Sorgen gemacht, was mit uns passieren würde, als Waisenmatrone uns in Sholazar gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13934] = { id = 13934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bronzedrachenschrein", description = "Als Kekek noch ein Welpe war, er hat die Ältesten oft von einem Schrein reden hören, weit weg. Manchmal sie sagen, dass die Bronzedrachendinger dort alles über die Zukunft wissen.\n\nKekek dir sagt, er wird großer Krieger sein, wir jetzt gehen nachsehen. Bronzedrachendingschrein ist irgendwo in Drachenöde, nordöstlich von Drachendingtempel, was Wyrmruh genannt wird und nordwestlich von Menschenstadt, was Wintergarde heißt.\n\nWir dort hingehen und Zukunft anschauen. Beweisen, dass Waisendame unrecht hat. Kekek sein Krieger, kein Lümmel.", sourceObjective = "Besucht mit Eurem Waisenkind Kekek den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Du siehst? Kekek nie genug davon bekommt zu sagen, \"Kekek dir das gesagt.\"\n\nVielleicht du jetzt auch andere Sachen glauben, die Kekek sagt, wie, dass Himmel grün ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13935] = { id = 13935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Baum!", description = "Wir haben die Kraft des Herzens des Waldes dazu verwendet, um den Baum gegen die Horde zu verteidigen, aber seine Kraft ist nicht grenzenlos. Wir müssen sie dazu einsetzen, die Schlacht zu ihnen zu tragen!\n\nSchattumbra, die große Katze des Waldes, streift in der Nähe umher. Von ihr sollen wir unsere Hilfe beziehen. Ihr werdet eins mit dem Schatten von Schattumbra. Ihr werdet die Essenz des Panthers in Euch aufnehmen und diejenigen vernichten, die es wagen, die Macht des Eschentals herauszufordern.", sourceObjective = "Sprecht mit Halannia, um den Schatten von Schattumbra zu beschwören und verwendet dessen Kraft, um 50 Feinde des Kriegshymnenklans am Rajenbaum zu vernichten.", completion = "Eine grausamer Anblick, aber die Feinde des Eschentals haben es verdient. Die Horde maßt es sich an, zu glauben, dass sie uns unseren geliebten Wald nehmen kann.\n\nSie begehen einen tödlichen Fehler!\n\nIhr habt den Rajenbaum vor der Zerstörung bewahrt, {name}. Sicherlich finden wir eine Belohnung, die unseres Champions würdig ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[13936] = { id = 13936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twidels Narretei", description = "Verspätungen, Verspätungen, Verspätungen! Ich bin mit meiner Weisheit am Ende!\n\nMir wurde gesagt, dieser Goblin sei brillant... dass er ein Gerät entwickeln würde, das die Feinde zur Unterwerfung zwingt. Bisher hat er nichts als leere Versprechen gemacht. Wenn er noch einmal mit leeren Händen zu mir kommt, werfe ich ihn persönlich von dieser Klippe!\n\nGeht zu ihm und sprecht mit ihm, {class}. Lasst ihn wissen, dass mein Geduldsfaden bald reißt!", sourceObjective = "Hauptmann Goggath will, dass Ihr mit Twidel in Höllschreis Wacht sprecht.", completion = "Hör mir mal zu, {class}!\n\nDer Boss weiß die Kunst und das Handwerk, die zur Herstellung besten Sprengstoffs gehört einfach nicht zu würdigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13937] = { id = 13937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Wunderwerken", description = "Haben wir Zeit für noch einen Halt? Wir haben gehört, dass Dalaran hat einen Spielzeugladen, aber wir dürfen nie hingehen. Waisendame sagt, zu viele Waisen würden sich in Laden drängen. Vielleicht können wir gehen, nur wir?\n\nKönnen wir ein kleines Papierzeppelin haben? Wir denken, sie haben so was bei Wunderwerke in Dalaran. Wir wollten schon immer mit so was spielen. Vielleicht du uns eins zuwerfen?", sourceObjective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Roo, zu.", completion = "Das hat Spaß gemacht! Wir mögen Spielzeugladen. Vielleicht Waisenmatrone uns irgendwann mitnehmen. Wir fragen. Vielleicht fragst du sie auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[13938] = { id = 13938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Wunderwerken", description = "Du bringen Kekek zu noch einen Ort? Waisenfrau sagt, dass Dalaran Spielzeugladen hat, der Wunderwerke heißt, aber Kekek den noch nie gesehen. Sie sagt, dass, wenn ein Waisenkind hingeht, sie jeden hinbringen muss. Vielleicht du bringen Kekek dorthin?\n\nKekek hat andere Kinder gesehen, die mit kleinen Papierzeppelin spielen? Kekek gehört, dass die von Wunderwerken kommen. Vielleicht du einen besorgen und ihn gemeinsam mit Kekek herumwerfen?", sourceObjective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Kekek, zu.", completion = "Kekek mag mit Papierzeppelin spielen. Nicht so gut wie jagen, aber damit gibt's was zu tun, wenn es langweilig sein im Waisenhaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13940] = { id = 13940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Traum verlassen", description = "Gut festhalten, {name}. Die Reise zurück in die wirkliche Welt kann Geist und Körper von Unvorbereiteten etwas mitnehmen.", sourceObjective = "Sprecht mit Malfurion beim Auge des Vortex in Dunkelküste.", completion = "Ihr kommt gerade rechtzeitig zurück, {name}. Ich weiß nicht, wie viel länger wir noch aushalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13942] = { id = 13942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenbasteln", description = "Ich bin hier zweifellos einer Sache auf der Spur!\n\nIch habe genug flüchtige Stoffe aus unserem Arsenal, um den Sprengstoff herzustellen, den Goggath haben will, aber ich muss ihn stabilisieren und in die Bomben füllen.\n\nIch brauche Ton – und nicht einfach irgendeinen Ton... mondberührten Ton.\n\nIhn findet man nur an den nördlichen Ufern von Astranaars Seen, und er besitzt die Eigenschaften, die ich brauche um meiner Entdeckung zur größtmöglichen Wirkung zu verhelfen!", sourceObjective = "Twidel in Höllschreis Wacht will, dass Ihr ihm 10 Proben mondberührten Ton bringt.", progress = "Zeigt her, was Ihr mir gebracht habt, {race}.", completion = "Das ist PERFEKT!\n\nOh, wartet, bis Ihr seht, was ich damit anstellen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[13943] = { id = 13943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Deckel für die Scharmützler", description = "Unsere Kräfte sind noch nicht bereit, Astranaar anzugreifen, {class}. Sie wissen trotzdem, dass wir kommen und sie werden sich nicht damit zufrieden geben, stillzusitzen und auf uns zu warten. Am Fuße dieser Klippen haben sie ein Lager aufgeschlagen, von wo aus sie nachts ihre lästigen Angriffe starten.\n\nBevor diese Geplänkel ihre Kühnheit weiter steigern, will ich, dass Ihr ihnen einen Besuch mit dem Zorn der Horde abstattet! Kehrt zu mir zurück, wenn Ihr den Elfen ihr Mütchen ein wenig gekühlt habt.", sourceObjective = "Hauptmann Goggath will, dass Ihr 10 Scharmützler von Astranaar und 3 Offiziere von Astranaar tötet.", completion = "Gut gemacht, {race}. Aber es gibt hier noch reichlich zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13944] = { id = 13944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Gestalt, kurze Lunte", description = "<Twidel gestikuliert wild.>\n\nIch habs geschafft! Das sollte selbst Goggath zufriedenstellen!\n\nWir brauchen nur einen Test, der unsere Mühen eindrucksvoll beweist... ah, der Wagen!\n\nCheffe mäkelt doch schon seit Tagen, dass wir den verrotteten Schrotthaufen endlich wegschaffen sollen. Nutzt meinen Sprengstoff, um ihn in die Luft zu jagen. Wollen wir doch mal sehen, was der Hauptmann dann zu sagen hat!", sourceObjective = "Probiert die improvisierte Sprengstoffstange an dem liegengebliebenen Wagen in Höllschreis Wacht aus.", completion = "Twidel hat also eine Möglichkeit gefunden, diesen Sprengstoff zum Funktionieren zu bringen, wie?\n\nDas war aber auch Zeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[13945] = { id = 13945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr vor Ort", description = "Die Aggression der Knarzklauen begrenzt unsere Möglichkeiten. Niemand von uns ist davon begeistert, mit Klingen und Pfeilen gegen Kreaturen vorzugehen, mit denen wir einst befreundet waren, aber ich befürchte, dass sie sich bald gegen Dolanaar wenden werden.\n\nDie größere Sorge sind für mich die Furbolgs auf der Lichtung von Ban'ethil und im Grabhügel von Ban'ethil. Ihr müsst nach Westen reisen, in den Grabhügel vordringen und so viele der Knarzklauen töten, wie Ihr nur könnt. Wir bekommen wahrscheinlich nicht mehr viele Gelegenheiten, ihrer Stärke Einhalt zu bieten - beeilt Euch.", sourceObjective = "Tötet 20 Knarzklauenfurbolgs auf dem Grabhügel von Ban'ethil und in der Umgebung.", completion = "Beeindruckend. Ich hoffe, meine Jägerin hat ihren Teil getan.\n\nWenn wir mit diesem Eifer weitermachen, können wir Teldrassil vielleicht doch noch von der Korruption befreien, die Alexstrasza selbst nicht ausbrennen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13946] = { id = 13946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung der Natur", description = "Ich bin froh, dass Ihr bereit wart, Eure Fehler wieder gutzumachen - das sagt viel über Euren Charakter aus.\n\nIch habe noch eine Aufgabe für Euch. Ich habe einige Zornwurzelsamen gesammelt. Sie sind Teufelszapfen ähnlich, aber viel stärker. Die Natur reagiert oft sehr negativ auf Dämonen und diese Zornwurzelsamen beinhalten hochkonzentrierte Abwehrstoffe.\n\nNördlich von hier, am Teufelsfels, sind Grellkin, die nicht mehr zu läutern sind. Benutzt die Zornwurzelsamen, um sie auszulöschen, bevor sie zu einer größeren Bedrohung werden.", sourceObjective = "Verwendet Zornwurzelsamen, um 12 Teufelsfelsgrellkin zu töten.", completion = "Gut. Ich weiß, dass das wahrscheinlich nicht gerade angenehme Arbeit war, aber wir sind Euch sehr dankbar.\n\nIch fürchte um unseren geliebten Teldrassil... es sieht aus, als werde er von Tag zu Tag verderbter, und unsere Unkenntnis der Ursache quält mich sehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13947] = { id = 13947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenstimmung in Astranaar!", description = "Twidel hat also endlich einen geeigneten Sprengstoff erfunden, wie?\n\nEr hätte keinen besseren Augenblick wählen können. Während wir sprechen, bereiten die Elfen von Astranaar einen vernichtenden Angriff auf unserer Lager vor.\n\nLasst unsere neue Waffe aus dem Himmel auf sie niederregnen! Die Zerstörung von Astranaar wird ein Stich ins Herz aller Nachtelfen sein!\n\nSprecht mit Thraka, wenn Ihr bereit seid, mit dem Angriff zu beginnen.\n\nZielt gut, {class}.", sourceObjective = "Hauptmann Goggath will, dass Ihr Twidels improvisierten Sprengstoff verwendet, um 20 Schildwachen von Astranaar zu töten und 10 Schleudern von Astranaar zu zerstören.", progress = "Astranaar brennt!\n\nFür die Horde!", completion = "Die glorreichen Geschichten der Horde sollen noch lange von Euren Taten berichten.\n\nEure Bemühungen haben dem Feind einen vernichtenden Schlag zugefügt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13948] = { id = 13948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserte Beobachtungen", description = "Die Kultisten sind anscheinend dabei, die Überreste eines Wesens auszugraben, das als Soggoth der Glitschige bekannt ist.\n\nVielleicht haben die höherrangigen Kultisten mehr Informationen für uns.", sourceObjective = "Schleicht mit Hilfe der Pantherfigur in die Meistergleve und beobachtet die Anführer der Schattenhammerkultisten auf der höheren Ebene.", completion = "Das sind schreckliche Neuigkeiten, {name}. Wenn Ihr recht habt, so müssen wir schnell und entschieden handeln.\n\nWir können nicht zulassen, dass \"Soggoth\" wieder zum Leben erweckt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13949] = { id = 13949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karawane am Wegekreuz", description = "<Halga grinst entwaffnend und hält eine enorme Feuerwaffe in die Höhe.>\n\nHabt Ihr jemals eine von diesen verwendet, {name}? Es ist ein Monster! Höllenfeuer mit Fadenkreuz. Zu schwer, um sie zu Fuß zu verwenden, aber perfekt, wenn man einer Karawane vorausreitet. Ich nenne sie den 'Straßenfeger'.\n\nWir müssen den Nachschub, den Ihr gesammelt habt, zum Wegekreuz bringen. Und ich rechne mit Schwierigkeiten. Ich hätte Euch gerne als Begleiter. Und als Feuerschutz. Sagt einfach, wenn Ihr bereit seid, und ich setze Euch an die Spitze der nächsten Karawane.", sourceObjective = "Sprecht mit Halga Blutauge in der Fernwacht, um die nächste Wegekreuz-Karawane zu Grol'doms Hof zu begleiten.", progress = "Mok'ra, Fremdling. Seid Ihr hier aus der Fernwacht?", completion = "Ihr seid ein unverhoffter Anblick, {race}. Das ist die erste Karawane, die es in dieser Woche geschafft hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[13950] = { id = 13950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielgefährten!", description = "Im Waisenhaus kann es schon sehr einsam werden, weißt du? Manchmal wollen wir mal rauskommen, neue Freunde finden.\n\nVielleicht kannst du uns irgendwohin mitnehmen, wo andere Junge sind? Wir haben von einem Ort gehört, der Zuflucht der Winterflossen genannt wird, in der großen Boreanischen Tundra. Wir glauben, dass es ganz weit drüben sein, im Nordwesten, in der Nähe der Kante der Kaltarrainsel.\n\nDie Waisendame sagen, dass jemand Tapferes dort ein paar Junge gerettet hat. Wir glauben, sie sind auch einsam. Wir glauben, sie brauchen Freunde. Bringst du uns hin?", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht die Zuflucht der Winterflossen. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Das hat Spaß gemacht! Können wir irgendwann noch mal hingehen? Wir können es gar nicht abwarten, unseren neuen Freund wiederzusehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13951] = { id = 13951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielgefährten!", description = "Kekek ist der Meinung, es gibt nicht genügend andere Welpen, die auch bei der Waisendame leben. Vielleicht gehen wir und besuchen ein paar?\n\nKekek kennt einen Stamm, der in der Drachenöde lebt, an einem Ort, der Schneewehenlichtung heißt. Du kennst? Schneewehenlichtung ist im Norden von einer Walrossstadt, die heißt Hafen Mo'aki, und im Süden von Rubindrachenschrein.\n\n<Kekek knurrt bei der Erwähnung der Tuskarr.>\n\nDu bringst Kekek da hin, zu ein paar von den Dörfern dort. Vielleicht treffen wir neue Wolvar und zeigen ihnen, wie stark die Wildherzen sind!", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht die Schneewehenlichtung. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Kekek mag neue Schneewehenfreunde, vielleicht kann irgendwann zurückkommen und zusammen jagen gehen. Vielleicht können wir Walrus-Leute umwerfen, wenn sie schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13952] = { id = 13952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Menschengeist auf dem Friedhof von Sturmwind.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13953] = { id = 13953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga unter uns", description = "Der Schädel dieser Kreatur wurde wohl im Kampf mit Aros gebrochen. Es handelt sich anscheinend um eine Kreatur, die Euch bislang als Naga ein Begriff war.\n\nTrotz ihrer monströsen Gestalt sind die Naga Nachtelfen, die von der arkanen Magie von Königin Azshara verformt wurden.\n\nSie haben sich wohl dazu entschlossen zu verhindern, dass Ihr das Horn der Urtume erhaltet.", sourceObjective = "Kehrt zu Balren von der Klaue beim Hain der Uralten in Dunkelküste zurück.", completion = "Die Naga haben sich mit den Schattenhammerkultisten verbündet? Das hat uns gerade noch gefehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13954] = { id = 13954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenkönigin", description = "In einer von Hochorakels Soo-says Geschichten es heißt, die Großen haben die Drachen gemacht und auch die Königin für die Drachen. Wir wollen sie sehen! Würdest du uns mitnehmen zur Spitze des Wyrmruhtempels? Wir erinnern uns, dass Soo-say uns erzählt hat, dass das Tempeldings in der Mitte der Drachenöde war.\n\nWir wollen wirklich so gerne die Drachenkönigin treffen. Sie muss so groß und schön sein. Vielleicht hilft sie uns, neue Eltern zu finden.\n\nDu uns nehmen mit?", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Glaubst du, sie hat schon mal ein Orakel gesehen? Wir vielleicht das erste, das sie jemals getroffen hat! Wir glauben, sie hat uns gemocht, aber wir nicht sicher. Sie nicht redet viel. Nee. Aber hat Spaß gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[13955] = { id = 13955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenkönigin", description = "Kekek hat Drachen immer gemocht. Wollte immer einer sein, aber Waisendame hat nein gesagt. Aber sie hat gesagt, dass vielleicht du Kekek zur Drachenkönigin bringen kannst.\n\nKekek glaubt, Waisendame hat einmal eine gute Idee. Du bringst Kekek zum Wyrmruhtempel in der Drachenöde? Fliegen ganz hoch bis zur Spitze, um Drachenkönigin zu sehen. Sie muss riesig groß sein, damit sie Königin von allen Drachen ist. Kekek kann es gar nicht erwarten, sie zu sehen!", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Die Königin war nicht, was Kekek erwartet hat, aber Kekek versteht warum. Die Besucher von Königin werden zerquetscht, wenn sie immer großer Drache ist! Trotzdem, will das irgendwann mal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13956] = { id = 13956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Großen treffen", description = "Hochorakel Soo-say erzählt uns immer, wie die Großen Schreine gebaut haben und wir ihnen Glitzer-Glitzer geben, aber er hat Große nie gesehen. Niemand hat Große gesehen, vielleicht weißt du, wo wir einen finden?\n\nSoo-say erzählt uns, die Großen haben ein Tor gebaut und es in die Mitte vom Süden von Sholazar gestellt. Soo-say sagt nicht, wo es hinführt, aber vielleicht er führt zu einem Großen! Bringt uns durch das Tor, damit wir es rausfinden können, {name}.", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht den Etymidian auf der Terrasse des Formers. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Wir haben einen Großen getroffen! Nur schade, dass er geschlafen hat, aber wir verstehen. Wir schlafen auch gerne! Vielleicht haben wir von Großen das Schlafen gelernt, so wie wir auch von ihnen von Schreinen und Glitzer-Glitzer erfahren haben!\n\nKönnen wir zurückkommen und den Großen noch mal besuchen, wenn er nicht schläft?", sourceObjectiveStatus = "unverified-source-field" }
quests[13957] = { id = 13957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mächtige Hemet Nesingwary", description = "Weißt du, wen Kekek immer schon mal treffen wollte? Hemet Nesingwary.\n\nVielleicht kannst du Kekek mitnehmen, um ihn zu sehen? Der Älteste Harkek hat uns alles von ihm erzählt. Er kommt nach Sholazar, um die größten Tiere weit und breit zu jagen! Sogar Älteste der Wildherzen respektieren Hemet Nesingwary als großen Jäger.\n\nDer Älteste Harkek hat Kekek erzählt, dass Nesingwarys Basislager in der Mitte der Westseite von Sholazar, beim Fluss, der Meeresklammstrom genannt wird. Können wir ihn besuchen und lernen, wie man wie Hemet jagt?", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht Hemet Nesingwary in Nesingwarys Basislager. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", completion = "Hilfst du Kekek, ein Buch zu lernen? Dann kann Kekek jagen mit Hemet Nesingwary!", sourceObjectiveStatus = "unverified-source-field" }
quests[13958] = { id = 13958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kritischer Zustand!", description = "Wir halten den Feind gut auf Trab. Der Sieg rückt immer näher!\n\nAber es ist noch nicht Zeit zum Feiern, {class}. Es bleibt noch viel zu tun, bevor die Horde das Eschental für sich beanspruchen kann.\n\nBeim Rajenbaum im Osten hat eine Schlacht begonnen. Berichten zufolge sind viele Mitglieder der Horde verwundet.\n\nBringt diese Heilvorräte dorthin und übergebt sie an Thagg. Erzählt ihm von unserem Angriff auf Astranaar. Vielleicht fördert es den dortigen Kampfgeist.", sourceObjective = "Goggath will, dass Ihr das Schlachttriagenverbandsset zu Thagg beim Rajenbaum bringt.\n\nBereitgestellter Gegenstand:", completion = "<Thagg hört aufmerksam zu, während Ihr ihm von Eurem Angriff auf Astranaar berichtet.>\n\nDas sind in der Tat gute Nachrichten, {race}. Aber im Moment brauchen wir hier etwas mehr als nur gute Nachrichten.\n\nDieses Schlachttriagenverbandsset können wir hier gut gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13959] = { id = 13959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Wir viel Spaß mit dir hatten, {name}. Wir uns wünschen so sehr, du könntest <unser Papa/unsere Mama> sein, aber du uns jetzt zur Waisenmatrone Aria in Dalaran zurückbringen musst.\n\nDu uns vielleicht irgendwann wieder besuchen kommen? Es toll war, Winterflossenjungen zu treffen und Drachenkönigin zu sehen. Es uns wird keiner glauben, dass wir einen Großen getroffen haben!\n\nWir dich werden vermissen, {name}. Wir versprechen, dir mal einen Brief zu schreiben, oki?", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Orakelwaisenkindes überreicht.", completion = "Hört sich an, als hätte der kleine Roo diese Woche viel Spaß gehabt. Ich weiß, dass er sehr einsam war im Waisenhaus und unbedingt ein paar neue Freunde finden wollte. Vielen, vielen Dank, dass Ihr Euch um ihn gekümmert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13960] = { id = 13960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Weißt du was? So schlecht bist du gar nicht, {name}. Du nimmst Kekek mit zu Orten, an denen was los ist. Kekek trifft viele neue Freunde und macht Dinge, die kein anderer Welpe macht.\n\nDu und Hemet Nesingwary und Schneewehenwelpen alle neue beste Freunde. Vielleicht du irgendwann das Grünehügelbuch bringen? Kekek verspricht, dir auch ab und zu zu schreiben, um zu sagen, wie die Dinge stehen. Vielleicht sogar nett sein zu Großzungenkindern.\n\nKekek muss jetzt zur Waisenmatrone Aria zurückkehren, zurück in Lilaleutestadt.", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Wolvarwaisenkindes überreicht.", completion = "Habt Dank dafür, dass Ihr Euch bereit erklärt habt, diese Woche auf Kekek achtzugeben. Ich weiß, er kann etwas anstrengend sein, aber ich glaube, dass er durch etwas mehr individuelle Zuwendung und einen etwas größeren Freundeskreis große Fortschritte machen könnte. Ohne Zweifel wird er noch wochenlang von seinen Abenteuern mit Euch erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13961] = { id = 13961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quetscht sie aus", description = "Es entspricht unserem Instinkt, einfach auf unsere Angreifer wie wild einzudreschen, aber die Weisheit gebietet einen anderen Weg. Wir sollten einen dieser Eindringlinge der Stacheleber befragen und so viel wie möglich herausfinden. Nehmt dieses Netz, {name}, und fesselt einen Plünderer der Stacheleber, der unseren Hof westlich von hier angreift. Schlagt die Bestie bewusstlos und bringt sie zu mir.", sourceObjective = "Verwendet Grol'doms Netz, um einen Plünderer der Klingenmähnen zu fesseln und schleppt ihn zurück zu Togrik auf Grol'doms Hof.", progress = "Springt mit unserem Gefangenen nicht all zu wild um. Um die Fragen beantworten zu können, muss er seinen Kopf auf dem Rumpf behalten.", completion = "Oje. Dieser Stacheleber sollte verhört werden, nicht weichgeklopft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13962] = { id = 13962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pattsituation", description = "Die Triagenverbandssets werden uns helfen, den Kampf weiterzuführen, aber wir befinden uns in einer Pattsituation.\n\nDie Dryaden sterben relativ schnell, aber ihr Anführer lässt sie kurz nach ihrem Fall immer wieder auferstehen. Wir stehen einem endlosen Strom dieses Ungeziefers gegenüber!\n\nBewahrer Ordanus versteckt sich in diesem mutierten Baum. Unsere Bemühungen, uns bis zu ihm durchzukämpfen, waren bisher vergeblich. Vielleicht könntet Ihr zu ihm gelangen, während wir mit seinen Dryaden kämpfen...\n\nDas ist sicherlich ein Kinderspiel für jemanden, der Astranaar erobert hat. Nein?", sourceObjective = "Thagg im Rajenbaum will, dass Ihr Bewahrer Ordanus tötet.", completion = "Sehr gut, {name}.\n\nIhr habt vollbracht, was mir nicht gelungen ist. Ihr habt meine Achtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[13963] = { id = 13963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jedes Mittel ist recht", description = "Ich schätze, ein Schwung kaltes Wasser wird ihn wieder zu Bewusstsein kommen lassen. Was glaubt Ihr, wird er uns mitzuteilen haben?\n\nIch nehme ihn in dem Viehstall hinter mir in Gewahrsam. Ich glaube nicht, dass er lange bewusstlos bleiben wird. Findet so viel heraus, wie Ihr könnt bezüglich der Frage, warum die Stacheleber unsere Höfe angreifen! Die Befragungsmethoden überlasse ich Euch.", sourceObjective = "Verhört den Gefangenen der Klingenmähnen. Falls er nicht dort oder bewusstlos ist, kann Togrik ihn für Euch wiederbeleben.", completion = "Sehr interessant – diese Biester scheinen jemanden zu kennen, der 'Tortusk' heißt und der sie bezaubert und verängstigt. Er ist ein mächtiger Anführer, der sein Volk sowohl zu Heldentaten als auch zu Gräueltaten zu bewegen vermag... Aber wir Orcs können das besser nachvollziehen als alle anderen.\n\nWir sollten unsere Aufmerksamkeit auf diesen Tortusk richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13964] = { id = 13964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Turm", description = "Wir haben die Silberwindzuflucht verloren! Alles, was ich weiß, ist, dass es einen Überraschungsangriff der Horde gab und dass sie irgendwie die Elementarwächter des Mystralsees gegen uns aufgebracht haben.\n\nDie Überlebenden sind bis zur Sternenstaubspitze zurückgefallen. {name}, sie benötigen Eure Hilfe.\n\nBegebt Euch nach Südsüdost. Dort findet ihr den Turm am Eingang des Steinkrallenpasses, der Euch in das Steinkrallengebirge führt. Ich bin mir sicher, dass Ihr dort Schildwache Velene Sternenschlag findet, die dort den Gegenschlag unterstützt.", sourceObjective = "Sprecht mit Schildwache Velene Sternenschlag auf der Sternenstaubspitze.", completion = "Freut mich, Euch endlich kennenzulernen, {name}. Ich kenne alle Eure Heldentaten und lasst mich Euch sagen, dass ich beeindruckt bin!\n\nGlaubt Ihr, dass Ihr uns Eure Kundigkeit zur Verfügung stellen könntet?", sourceObjectiveStatus = "unverified-source-field" }
quests[13965] = { id = 13965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaut nach den Edunes", description = "{name}, falls Ihr einen Augenblick erübrigen könnt, würde ich gerne Eure Hilfe in einer kleinen Angelegenheit in Anspruch nehmen.\n\nIch habe schon längere Zeit nichts mehr von meinen Freunden den Edunes gehört. Ich frage mich, ob Ihr auf einen Sprung nach Westen bei ihnen vorbeischauen könnt?\n\nIch danke Euch. Ihr Landhaus liegt auf einem kleinen Grundstück westlich des Schreins von Aessina.", sourceObjective = "Sprecht mit Benjari Edune im Haus von Edune im Eschental.", completion = "Ihr sagt, Faldreas schickt Euch? Guter Mann.\n\nWie es der Zufall will, könnten wir Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13966] = { id = 13966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13967] = { id = 13967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beim Ausdünnen der... Rotte?", description = "Die Furbolgs sind zahlreicher, als wir es in diesen südlichen Gefilden erwartet hatten. Sie sind hier auch viel aggressiver, als wir es gerne hätten.\n\nWir müssen unsere Kräfte aufteilen, denn wir müssen Elfen jagen und gleichzeitig das dringend benötigte Holz schlagen. Das bedeutet, dass Ihr mir helfen müsst, die Belästigung durch die Furbolgs zu beenden.\n\nIch muss hier Forschungen durchführen. In der Zwischenzeit brauche ich Euch für eine etwas tatkräftigere Aufgabe. Bringt mir die Ohren der Furbolgs in der Nähe. Sie sollen Tarkan beweisen, dass wir das Problem in Angriff nehmen.", sourceObjective = "Senani Donnerherz in der Silberwindzuflucht will, dass Ihr Euch 15 Furbolgohren von Totemikern der Fäulnisklauen und Ursa der Fäulnisklauen holt.", progress = "Und, {name}.\n\nIst es vollbracht?", completion = "Gute Arbeit, {race}!\n\nJetzt sollten sie eine Zeitlang ihre Wunden lecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13968] = { id = 13968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortusks Untergang", description = "Im Windschatten des Chaos' im Süden scheint dieser Schläger 'Tortusk' alle Flüchtlinge der Klingenmähnen unter seinem Banner versammelt zu haben. Unter seiner Führung verwandeln sie sich in dreckige, kleine Briganten. Mit dieser Sorte lässt sich nicht verhandeln. Tortusk muss vernichtet werden.\n\nWenn man unserem Gefangenen Glauben schenken kann, findet Ihr Tortusk südöstlich von hier an einem Ort namens Dornenhügel. Durchsucht die Felsen nach einer Stelle, von wo aus er einen guten Überblick über die Straße hat. Tötet ihn, {name}, und die unmittelbare Gefahr wird weichen.", sourceObjective = "Tötet den Anführer der Klingenmähnen Tortusk.", completion = "Ah, Tortusk hat sich also genauso verhalten, wie ich es vorhergesagt habe? Er sprang Euch direkt an die Gurgel? Es ist gut, dass er tot ist.\n\nDie Stacheleber der Klingenmähnen wurden von ihrer Führung im Südlichen Brachland getrennt. So ein Tier wie er sollte solche Macht zweifellos nicht besitzen. Vielleicht können wir ohne seinen Einfluss in einen Dialog mit den Überlebenden treten... Obwohl dort vielleicht auch hitzige Gemüter vorherrschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13969] = { id = 13969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind Grol'dom Kodos?", description = "Wenn Ihr nach Süden zum Dornenhügel reist, frage ich mich, ob Ihr unsere fehlenden Kodos ausfindig machen könntet? Nicht jede Karawane hat es über den Pass der Fernwacht geschafft. Diese Schläger der Klingenmähnen haben gestern Morgen ein Packtier entführt. Vielleicht ist es nicht mehr am Leben, aber falls es noch nicht tot ist, können wir es uns nicht leisten noch mehr Vieh zu verlieren.", sourceObjective = "Findet den vermissten Kodo von Grol'dom irgendwo auf dem Dornenhügel im Nördlichen Brachland.", completion = "Dieser mitgenommene Kodo steht mit drei Beinen im Grab, aber er atmet noch. Die Klingenmähnen haben seine Fracht noch nicht ausgeplündert. Falls er wiederbelebt werden kann, könntet Ihr vielleicht die gesamte Ladung retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13970] = { id = 13970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tierpflege", description = "Kodos sind zähe Kreaturen. Mit ein wenig Nahrung bekommen wir den Dicken vielleicht wieder auf die Beine.\n\nDie Klingenmähnen haben reichlich Getreide von früheren Karawanen geraubt. Ihr könnt das gestohlene Getreide in den nahegelegenen Lagern einsammeln.", sourceObjective = "Sammelt 5 Säcke gestohlenes Getreide aus den Lagern der Klingenmähnen auf dem Dornenhügel.", progress = "Die Kreatur hebt ihren Kopf nicht, aber sie sieht Euch mit großen und flehenden Augen an, in denen sich das Wasser sammelt.", completion = "Der Kodo ist unersättlich! Ihr hättet die Säcke genauso gut in ein großes Loch schütten können!\n\nDas Tier wird bereits wieder munter.", sourceObjectiveStatus = "unverified-source-field" }
quests[13971] = { id = 13971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Kodos", description = "Das riesenhafte Reptil erhebt sich langsam, stellt sich auf die Beine, die lose Erde des Brachlandes rieselt von seinen Gliedmaßen, in die das Leben zurückgekehrt ist. Instinktiv stapft das Tier zurück zu seinem Zuhause auf Grol'doms Hof.\n\nIhr wollt sicher mit Kranal Fiss sprechen, um sicherzugehen, dass es der Kodo geschafft hat.", sourceObjective = "Sprecht mit Kranal Fiss auf Grol'doms Hof, um Euch zu versichern, dass sein vermisster Kodo heil angekommen ist.", completion = "Das war Euer Werk, {race}? Ja, der vermisste Kodo ist vor ein paar Minuten eingetroffen. Es wird vieler Nächte bedürfen, die Wunden der bemitleidenswerten Bestie zu versorgen, aber dank Euch ist sie noch am Leben. Und Ihr habt die gesamte Fracht gerettet!\n\nBitte sucht Euch etwas von der Ausrüstung aus, die der Kodo transportiert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13973] = { id = 13973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grol'doms Miliz", description = "Sie sind aus dem Nichts gekommen, {class}! Stacheleber wo man auch hinsieht. Borsten, Schnauzen und Hauer. Wir haben uns auf den Hof zurückgezogen, aber es kamen immer mehr.\n\nUnsere besten Verteidiger sind auf dem Schlachtfeld gefallen und wir haben kein Lebenszeichen von Bauer Ralton. Ihr müsst sie für mich angreifen! Haltet mir diese Schweine vom Leib, während ich die Verwundeten verteidige, bis Hilfe eintrifft.", sourceObjective = "Tötet 6 Plünderer der Klingenmähnen.", progress = "Ich sehe Rauch aus dem benachbarten Gebäude aufsteigen – was geht da draußen vor sich?", completion = "Ich sehe, Ihr habt Euren Weg mit Leichen gepflastert, {race}. Ich hätte es nicht besser machen können. Das Vieh ist vielleicht verloren, aber das Land bleibt das unsrige – dank Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[13974] = { id = 13974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twidels winziges Paket", description = "Woohoo!!\n\nSchaut nur, wie das brennt! Es ist revolutionär! Ein echter Durchbruch in der Explosionstechnik! Und das ist natürlich die einzige Technik, die zählt.\n\nAlle Goblins südlich von Nordend werden mich bewundern und beneiden!\n\nUnd ob Ihr es glaubt oder nicht, ich habe noch ein wenig an der Zusammensetzung gedreht, um sogar noch mehr Leistung herauszuholen!\n\nHier. Nehmt eine Probe dieses Zeugs und bringt sie nach Südosten in die Silberwindzuflucht. Mein Vetter Flooz kann es vielleicht brauchen, um die Horde bei der Eroberung dieses Ortes zu unterstützen.", sourceObjective = "Twidel möchte, dass Ihr Twidels winziges Paket zu Flooz in der Silberwindzuflucht bringt.\n\nBereitgestellter Gegenstand:", completion = "Na sieh mal einer an! Der kleine Twidel hat es diesmal echt geschafft. Das Zeug hat Astranaar in die Luft gejagt, sagt Ihr?\n\nWie Ihr seht, brauchen wir keine Hilfe, die Silberwindzuflucht zu erobern, aber Twidel war immer ein bisschen kleingeistig.\n\nWenn das Zeug wirklich so gut ist, wie Ihr behauptet, sind die Möglichkeiten endlos...", sourceObjectiveStatus = "unverified-source-field" }
quests[13975] = { id = 13975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawane zum Wegekreuz", description = "<Rocco überreicht Euch eine Schrotflinte, die Euch bekannt vorkommt.>\n\nIch habe mir erlaubt, Halgas Artillerie für Euch zu reinigen. Ich bin mir sicher, dass ich Euch nicht vor dem Rückstoß zu warnen brauche. Fragt mich einfach, wenn Ihr bereit seid, zum Wegekreuz aufzubrechen! Thork wartet dort auf Euch. Achtet darauf, dass Ihr ihm nicht pampig kommt.\n\nLasst Euch von nichts aufhalten, {name}, und wenn Euch jemand zu nahe kommt, versetzt ihm einfach einen Stoß mit dem Kolbenende Eurer Schrotflinte. Macht uns stolz!", sourceObjective = "Sprecht mit Rocco Peitschschwinger in Grol'doms Hof und begleitet seine Karawane den gesamten Weg zum Wegekreuz.", progress = "Wart Ihr der Jemand, den ich mit einer Schrotflinte am Ende meiner Karawane herumfuchteln sah?", completion = "Es wurde aber auch Zeit, dass ein paar Vorräte bis hierher durchkommen. Es ist schlimm genug, von Mulgore abgeschnitten zu sein, aber diese Stadt würde in die Binsen gehen, wenn wir unseren Handel mit Orgrimmar verlören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13976] = { id = 13976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Männlein steh'n im Walde", description = "Habt Ihr Lust auf einen kurzen Abstecher in den Süden? Ich habe drei Freunde, von denen ich schon länger nichts gehört habe. Diese seltsamen Tentakel treten im Norden aus dem Boden hervor und bei all der dämonischen Aktivität wage ich es nicht, meine Familie alleinzulassen.\n\nBolyun hat sein Lager in der südwestlichen Ecke dieses Waldes aufgeschlagen - genau im Nordwesten dieses verdammten Schreins des Sengenden Feuers. Alenndaar und Harlown haben sich ihm angeschlossen, also müsste es ihnen eigentlich gut gehen, aber man kann nie wissen.\n\nHabt Dank, {name}.", sourceObjective = "Sprecht mit Bolyun in Bolyuns Lager im Eschental.", completion = "{class}, Ihr müsst achtsam sein! Kaliva die üble Dämonin, die uns angekettet hat, ist in der Nähe!", sourceObjectiveStatus = "unverified-source-field" }
quests[13977] = { id = 13977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenproduktion", description = "Woohoo!! Habt Ihr das GESEHEN?!\n\nDamit müssen wir sofort in Produktion gehen.\n\nHier, bringt den Rest von diesem Zeug zu Jinx. Er richtet gerade unseren neuen Standort westlich von hier ein.", sourceObjective = "Flooz möchte, dass Ihr Twidels Bumm-Bumm-Pulver zu Jinx in den Stinkwerken bringt.", progress = "Was habt Ihr da, Boss?", completion = "<Jinx untersucht das Pulver einen Augenblick lang sorgfältig.>\n\nHmmm.\n\nIch brauche ein wenig Zeit. Aber ja, wir können das in eine Bombe packen…", sourceObjectiveStatus = "unverified-source-field" }
quests[13979] = { id = 13979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Expertengremium der Goblins", description = "Wenn wir die verdammten Bombenangriffe durch diese Goblinmachwerke stoppen könnten, wären wir in der Lage, einen Gegenangriff zu starten und die Silberwindzuflucht zurückzuerobern!\n\nMeiner Erfahrung nach sind Goblins entweder faul oder unproduktiv, oder so eifrig, dass sie sich mit ihrem Sprengstoff schließlich selbst in die Luft jagen. Zu unserem Unglück werden sie von dem genialen, leitenden Bombentechniker Splodier angeführt.\n\nBegebt Euch in die Stinkwerke an der Westseite der Zuflucht und kehrt nicht zurück, bis Ihr den Kopf des leitenden Bombentechnikers in Händen haltet.", sourceObjective = "Holt Euch Splodiers Kopf.", progress = "Habt Ihr den widerwärtigen, verwarzten Goblin zum Schweigen gebracht?", completion = "Das ist gut. Ohne ihn fallen ihre Techniker sicher wieder zurück in ihre alten Gewohnheiten, was zu weniger Bomben und mehr Unfällen führen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13980] = { id = 13980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie sind da draußen!", description = "Sie sind da draußen, {class}. Und sie sind uns auf den Fersen.\n\nEinige meiner Männer wurden tot aufgefunden. Elfenangriffe, ohne Zweifel.\n\nIch glaube, dass sie wegen Eurer Arbeit in Astranaar versessen darauf sind, unserem Fortschritt hier Einhalt zu gebieten. Ein letztes Aufbäumen vor der Niederlage!\n\nNehmt diese Brille. Sie hilft Euch dabei, auch den am besten getarnten Elf zu erkennen. Haltet sie mir vom Leib, während wir unsere Waffe für Euch vorbereiten.", sourceObjective = "Jinx in den Stinkwerken möchte, dass Ihr 12 Assassinen des Eschentals tötet.", completion = "Gute Arbeit, Freund.\n\nEure Fähigkeiten haben uns die nötige Zeit verschafft, um die Bombe vorzubereiten. Sie ist fast fertig!", sourceObjectiveStatus = "unverified-source-field" }
quests[13981] = { id = 13981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenlieferung gefällig?", description = "Das ist sicherlich die größte Sprengstoffladung, die Ihr je zu Gesicht bekommen habt. Was in aller Welt würden die Goblins mit so einem Monstrum bombardieren wollen?\n\nSoweit Ihr das beurteilen könnt, ist das Werk fast vollendet. Die Goblins scheinen den Sprengsatz gut konstruiert zu haben. Es sieht so aus, als ob er gut geschützt ist gegen jeden Schaden, den Ihr ihm zufügen könntet. Und die Bombe ist sicherlich zu groß, als dass Ihr sie von hier forttragen könntet.\n\nIhr solltet die Bombe besser Jägerin Jalin auf der Sternenstaubspitze im Südwesten melden!", sourceObjective = "Berichtet Jägerin Jalin auf der Sternenstaubspitze im Südwesten des Eschentals von der Existenz der Bombe.", completion = "Sie haben was? SIE IST WIE GROSS?!!!\n\nDas hört sich gar nicht gut an, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13982] = { id = 13982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Ketten gelegt", description = "{name}, Ihr müsst vorsichtig sein. Kaliva ist noch immer in der Nähe und als sie uns gefangen nahm, erwähnte sie ganz besonders Euren Namen.\n\nNur ihr Herz kann uns von diesen Ketten befreien, aber ich glaube, dies alles ist eine Falle nur für Euch!", sourceObjective = "Beschafft Kalivas Herz.", progress = "Um freizukommen, brauchen wir Kalivas Herz.", completion = "Es ist ekelerregend, ich weiß, aber wenn wir drei diese Ketten von Kaliva loswerden wollen, reicht es nicht, dass sie tot ist.\n\nWir müssen von ihrem teuflischen Herzen essen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13983] = { id = 13983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baut Euren eigenen Sarg", description = "Sobald sie fertig ist, müssen wir die Bombe zu Saurboz schaffen.\n\nUnd mit 'wir' meine ich 'Ihr'.\n\nBei all den Feinden, die sich hier herumtreiben, muss ich etwas ganz Besonderes bauen, wenn Ihr mit dieser Aufgabe Erfolg haben wollt.\n\nIch könnte einen dieser kaputten Schredder umbauen, aber dazu brauche ich ein paar Teile. In den Wäldern im Westen solltet Ihr eigentlich alles problemlos finden.\n\nBeschafft mir die Teile, während ich die Bombe fertig baue.", sourceObjective = "Vorarbeiter Jinx möchte, dass Ihr 3 Bronzeräder, 3 Stück Kupferbeschlag und 5 Klemmbolzen sammelt.", progress = "Habt Ihr die Teile, die ich brauche, Freund?", completion = "Das sieht gut aus, {class}.\n\nEuer Schredder sollte im Handumdrehen bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13985] = { id = 13985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leert den Schrein", description = "Dem Bösen dieser Brennenden Legion muss ein Ende gesetzt werden!\n\n{name}, Ihr habt einen ihrer Mächtigsten besiegt, aber es gibt noch immer zahlreiche Dämonen, die die Wälder im Osten im Schrein des Sengenden Feuers verseuchen.\n\nWerdet Ihr als ein Freund des Waldes diese Kreaturen vernichten und dann den Großen Baobob, das große Urtum des Krieges am Schrein von Aessina im Nordosten warnen?", sourceObjective = "Vernichtet 12 beliebige Dämonen am Schrein des Sengenden Feuers.", completion = "Das war gute Arbeit, {race}. Aber Ihr seht, dass ich hier ein wenig beschäftigt bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13986] = { id = 13986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verletzter Kollege", description = "Es war ein harter Kampf hier oben, {class}, wie Ihr sicher wisst. Wir harren aus, doch ist nicht jeder unversehrt geblieben.\n\nEine der Kriegerinnen unserer Gruppe, Aponi Lichtmähne, leidet an einer infizierten Wunde an ihrem Arm. Sie wurde zur Erholung nach Donnerfels zurückgebracht. Es scheint jedoch, als hätte sie in der ganzen Aufregung ihren Schild hier an der Front vergessen - könntet Ihr es ihr bringen, zusammen mit unseren Genesungswünschen? Uns fehlt ihr Lächeln hier sehr.\n\nIhr könnt sie auf der Anhöhe der Ältesten finden.", sourceObjective = "Bringt Aponi Lichtmähne auf der Anhöhe der Ältesten in Donnerfels den ramponierten Stammesschild.", progress = "Oh! Hallo. Ich glaube nicht, dass wir uns schon kennengelernt haben. Gibt es etwas, was ich für Euch tun kann?", completion = "Oh, mein Schild! Ich werde ihn in naher Zukunft wohl nicht brauchen, aber ich danke Euch. Ich verabscheue es, hier nutzlos herumzusitzen, wenn ich an der Front helfen könnte, doch würde es niemandem helfen, wenn ich mich in den Kampf werfe, solange mein Arm in diesem Zustand ist.\n\nGebt gut auf Euch acht da draußen, in Ordnung?", sourceObjectiveStatus = "unverified-source-field" }
quests[13987] = { id = 13987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht", description = "{name}, ich brauche unbedingt Eure Hilfe! Ich kann gegen diesen Ansturm der Dämonen nicht ewig standhalten. Wenn ich falle, ist Astranaar als Nächstes dran!\n\nBitte helft mir!", sourceObjective = "Tötet 30 dämonische Eindringlinge.", progress = "Nur noch ein paar und wir werden es schaffen.", completion = "Ihr habt uns alle gerettet, {name}! Ich habe genug Kräfte, um diesen letzten Rest zu erledigen.\n\nDieser Wald wird die Brennende Legion nicht mehr länger fürchten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13988] = { id = 13988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit eigenen Augen", description = "Das Leben explodiert förmlich auf diesem kargen Boden... Mein Gefährte Jerrik hat erzählt, dass sich ähnliche Dinge überall im Brachland ereignen. Ich muss es mit eigenen Augen sehen, aber ich darf meinen Posten nicht verlassen.\n\nHier, {name}, ich werde Euch meine 'Augen' leihen. Seit dem Tag, an dem ich meinen Namen erhalten habe, hat mein Adlergefährte hier mir gut gedient. Bitte begleitet ihn zum Donnerkopfgipfel, wo Jerrik Euch erwartet und wir werden uns umsehen.\n\nUm auf die Spitze zu gelangen, folgt der Straße Richtung Osten am Wegekreuz. Wendet Euch nach Süden, sobald Ihr einen großen Stein erreicht, der mit Malereien übersät ist.", sourceObjective = "Bringt Tongas Augen zum Donnerkopfgipfel südwestlich von Ratschet.", progress = "Tonga kennt dieses Land besser als wir alle, und ich glaube, es hat ihm große Schmerzen bereitet, zu sehen, wie es auseinandergerissen wurde.", completion = "Ich bin froh, dass Tonga in der Lage war, die Überwucherung aus erster Hand mitzuerleben – Wörter können das Ausmaß der Zerstörung nicht angemessen beschreiben. Habt Ihr sein Totem dabei? Ich werde es ihm wiederbringen, wenn ich hier fertig bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13989] = { id = 13989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Fäulnisklauen", description = "Es interessiert mich herzlich wenig, wer Ihr seid, {race}. Worauf es mir ankommt ist die Rettung der Furbolgs.\n\nBringt dieses Blutreißerbanner das kurze Stück in Richtung Nordosten zur Laubtatzenlichtung und platziert es auf ihrem Totemhügel. Sie werden es als einen Angriff ansehen und versuchen, das Banner zu zerstören. Haltet die Stellung. Häuptling Murgut wird auftauchen, um das Gesicht des Stammes zu wahren. Wartet auf ihn und dann tötet den Verräter!\n\nTeilt Eure Kräfte gut ein. Euch steht ein langer Kampf bevor.", sourceObjective = "Platziert das Blutreißerbanner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören, bevor ihr Häuptling kommt. Besiegt Häuptling Murgut.", completion = "Gut. Murgut hat seinen Stamm an die Horde verkauft und sich mit ihr verbündet, als sie Eure kostbare Silberwindzuflucht eingenommen hat, um sein Volk zu 'retten'.\n\nEr hat sie in die Sklaverei verkauft – oder Schlimmeres. Und jetzt hat er bekommen, was er verdient!\n\nLasst uns nun über einen anderen Verräter sprechen. Ich glaube, er besitzt etwas, das Eurer Rute mehr Durchschlagskraft verleihen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13991] = { id = 13991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gestohlene Lohnliste", description = "Und, {name}. Ich gebe zu, dass Ihr gut in meine geliebte Horde passen würdet. Ihr habt Stärke, List und Einsatz bewiesen... Sogar Thork erwähnte Euch kürzlich namentlich, und weder er noch ich sind leicht zu beeindrucken. Gute Arbeit.\n\nJetzt wird es Zeit, dass Ihr Euch weiter in die Riemen legt. Die wöchentliche Lohnliste für die Wachen des Wegekreuzes ist verloren gegangen. Gazrog in Ratschet führt eine Untersuchung an. Sprecht mit ihm!\n\nFolgt einfach der Straße von hier Richtung Osten zur Küste.", sourceObjective = "Sprecht mit Gazrog in der Nähe des Eingangs nach Ratschet.", completion = "Ich hatte auf eine Truppe von Grunzern gehofft... Aber wenn Ihr Euch Sergras Anerkennung verdient habt, schätze ich, dass Ihr der Aufgabe mehr als gewachsen seid. Lasst mich erklären, was hier geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13992] = { id = 13992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kleine Ablenkung", description = "Ich wurde hierher geschickt, um die Aktivitäten der Zentauren auszukundschaften. Ich habe all ihre Bewegungen seit Tagen beobachtet! Es wird Zeit für mich, mich wieder davonzuschleichen, aber sie haben diesen Ort umzingelt.\n\nIhr seht aus, als ob Ihr gefährlich seid. Könnt Ihr ein wenig Chaos für mich veranstalten? Sie aufwühlen! Metzelt sie wahllos nieder. Während sie nach Euch suchen, schleiche ich mich davon, um meinen Bericht an Regthar Totenfurt zu überbringen.", sourceObjective = "Tötet 8 Zentauren der Kolkar.", completion = "Oh ho! Das war wunderbar. Ich hätte vermutlich nicht bleiben und zusehen dürfen. Jetzt suchen sie nach Euch. Ich stehle mich im Staub ihres ziellosen Herumgaloppierens heimlich davon.\n\nHaltet an den anderen Teichen nach meinen Kameraden Ausschau. Der Boss hat an jedem seine Leute.", sourceObjectiveStatus = "unverified-source-field" }
quests[13995] = { id = 13995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König vom Berge der Zentauren", description = "Wir wurden hierhergeschickt, um die Bewegungen der Zentauren der Kolkar zu beobachten, aber nachdem wir diesen dreckigen Tieren eine Woche dabei zugesehen haben, wie sie um die Oase galoppieren, juckt es mich, meiner Axt ihre Hälse zu schmecken zu geben. Was sagt Ihr, {class}? Wollt Ihr mit mir ein wenig Chaos verbreiten?\n\nMal sehen, ob wir die Aufmerksamkeit ihres stärksten Kriegers Kurak auf uns lenken können.", sourceObjective = "Sorgt dafür, dass Gorgal Zornesnarbe am Leben bleibt, während er sich mit den Zentauren anlegt und helft ihm, Kurak zu töten.", completion = "Warum musstet Ihr Gorgal denn so verärgern? Das Ergebnis gibt Euch allerdings recht. Wir müssen diese Tiere weiterhin gut beobachten, um zu sehen, was sie tun, jetzt wo Kurak aus dem Weg geräumt ist.\n\nAlso weiter beobachten, abwarten und Tee trinken. Gorgal wird das nicht mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13997] = { id = 13997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Reading This While I'm In Combat..." }
quests[13998] = { id = 13998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Pilzkultur", description = "Wir haben diese ungewöhnlichen Sporen kultiviert, die Ihr ausgegraben habt. Das gelang mir mit einer wundervollen Mischung aus... Reagenzien... auf die ich sehr stolz bin. Ich kann es nicht erwarten, zu sehen, wie meine manipulierten Sporen auf die Gewässer in den Oasen am Wegekreuz reagieren.\n\nDie Brackige Oase im Südosten bietet uns eine unverseuchte Region für unsere Experimente. Sät diese Kulturen in der feuchten Erde irgendwo in der Nähe der Oase für mich aus und dokumentiert die Ergebnisse.\n\nAchtet darauf, dass Ihr Euren Mund bedeckt, {class}.\n\n<Helbrim grinst entwaffnend.>", sourceObjective = "Pflanzt eine Pilzkultur in der Nähe der Brackigen Oase und beobachtet das Ergebnis.", completion = "Explosive Sporenwolken? Was Ihr nicht sagt... Erzählt mir mehr. Erstickung? Stechen? Brennen in den Augen? Hat es gejuckt? Übelkeit? Krankheit? Entzückend, ENTZÜCKEND! Ihr habt Euch Eure Bezahlung redlich verdient, {name}.\n\nUnd Euer Hautausschlag müsste eigentlich in ein oder zwei Tagen wieder weg sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13999] = { id = 13999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat meinen Zauberpilz gegessen?", description = "Stellt Euch mal vor, was wir damit anstellen können, {name}! Schnellwachsende Pilze, die jedes beliebige Gift übertragen können. Meine Gefährten in der Unterstadt wird das sicher interessieren.\n\nHier sind meine Aufzeichnungen und ein paar Proben. Wenn wir schnell sind, erwischen wir das nächste Schiff, das in Richtung der Östlichen Königreiche in See sticht. Nehmt die Straße östlich von hier und folgt ihr zur Goblinstadt Ratschet. Sucht nach der Taverne 'Zum geborstenen Kiel' im Südteil der Stadt und übergebt dies an meinen Mitarbeiter Sashya.", sourceObjective = "Bringt Helbrims Forschungsergebnisse zu Sashya in Ratschet im Nördlichen Brachland.", progress = "Wer seid Ihr? Hat Helbrim Euch gesandt? Verhaltet Euch unauffällig.", completion = "Ruhe! Gebt mir die Aufzeichnungen. Ist Euch jemand gefolgt?", sourceObjectiveStatus = "unverified-source-field" }
quests[14001] = { id = 14001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungskapseln der Goblins", description = "{name}, es tut mir leid. Ich dachte, Ihr wärt tot!\n\nEs ist einfach Irrsinn! Wir sind direkt in einen Kampf zwischen der Allianz und der Horde gesegelt.\n\nWir müssen unsere Brüder und Schwestern retten.\n\n<Er zeigt auf die Rettungskapseln, die um Euch herum im Wasser verstreut sind.>\n\nIch glaube, ich bleibe hier noch ein wenig sitzen und komme zu Atem. Könntet Ihr aufs Meer hinausschwimmen und sie herauslassen? Nehmt meine thermohydraulischen Flossen, damit könnt Ihr Euch schneller fortbewegen.\n\nLasst Sassy wissen, dass ich gleich losschwimme.", sourceObjective = "Rettet 6 überlebende Goblins.", completion = "Oh, dem Himmel sei Dank, dass Ihr überlebt habt, {name}! Ich war mir so sicher, dass Ihr ertrunken seid, nachdem ich Euch über Bord habe gehen sehen.\n\n\n\nSchaut nur, wie viele Leute Ihr gerettet habt!\n\n\n\nDas habe ich ja fast vergessen. Ich habe ein paar Eurer Sachen aufgehoben. Nur für den Fall, dass Ihr es schafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[14003] = { id = 14003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Samophlang repariert", description = "Nun, das lief leider nicht so, wie erwartet. Ich glaube, ich habe es kaputt gemacht.\n\nAber kein Grund zur Panik. Tut mir einen Gefallen und folgt diesem Weg zu Brak hier im Lager. Er dengelt dieses Ding schnell wieder in die richtige Form!", sourceObjective = "Bringt das zerbrochene Samophlang hinüber zu Brak Polterrohr innerhalb des Lagers.", progress = "Sagtet Ihr... Samophlang!?", completion = "Stotterspritter hat uns ein Samophlang beschafft? Lasst mich das Ding mal sehen!\n\nJupp, das kriegen wir wieder hin. Kein Problem. Reicht mir den großen Hammer...", sourceObjectiveStatus = "unverified-source-field" }
quests[14004] = { id = 14004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt das Samophlang zurück", description = "Nun, das hat nicht funktioniert. Ich habe ein paar zusätzliche Anzeigegeräte an dem Samophlang angebracht, die seine strukturelle Integrität messen. Sie zeigen stets einen absoluten Tiefstand an. Ich könnte einige Wählscheiben und vielleicht einen Hebel oder zwei hinzufügen und versuchen, es zu reparieren, aber... Ich glaube, das könnte alles nur noch schlimmer machen.\n\nSeht mal, was ich entdeckt habe, als ich das Ablassventil blockiert habe und die Ummantelung des Differentialgehäuses abgeflogen ist: das persönliche Gravurzeichen von 'Boss Kupferdraht'. Bringt dies zurück zu Stotterspritter und sagt ihm, er soll dieses Genie Kupferdraht auftreiben.", sourceObjective = "Bringt das Wrack des überarbeiteten Samophlangs zurück zu Stotterspritter in Düsentopfs Außenposten. Sprecht mit Wenikee, um direkt dorthin teleportiert zu werden.", progress = "Ist das mein Samophlang? Es ist kaum wiederzuerkennen.", completion = "Was hat Wenikee gesagt? Kupferdraht? BOSS Kupferdraht? Oh je, das könnte sich als kompliziert erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14005] = { id = 14005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Rache", description = "Während Teldrassil sich selbst von der Verderbnis reinigt, welche sein Wachstum all die Jahre entstellt hat, hat sich südlich von hier am Rand des Baumes eine bösartige Wucherung gebildet. Wir haben die Möglichkeit, anzugreifen und die Quelle des Teufelsmooses, das die Knarzklauen, die Bäumlinge und alles andere verdorben hat, zu säubern.\n\nMit dem Wasser, das Ihr in den Mondbrunnen gesammelt habt, und der erneuerten Kraft von Teldrassil selbst kann ich Euch eine kurze Zeit große Macht gewähren. Setzt der Verderbnis ein Ende, {name}.", sourceObjective = "Nutzt die Macht, die Tarindrella Euch gewährt hat, um Euch zum Herz der Verderbnis durchzukämpfen und es zu zerstören.", completion = "Elune sei gepriesen!\n\nAlles, worauf ich gestoßen bin, deutet darauf hin, dass die Verderbnis tief in Teldrassil selbst vergraben liegt... Ich hatte schon befürchtet, wir würden die Quelle niemals angreifen können, ohne den Weltenbaum dabei zu töten. Ich bin so dankbar, dass ich falsch lag!\n\nDiese günstige Wendung des Schicksals haben wir Malfurion zu verdanken. Vielleicht werde ich ihn aufsuchen, bevor ich wieder in die Wildnis aufbreche.\n\nVielen Dank, {name}. Danke für alles, was Ihr getan habt. Sicherlich werdet Ihr eines Tages ein großer Held sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[14006] = { id = 14006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lest das Handbuch", description = "Damals, als ich noch in der Tüftlerverbindung war, war Boss Kupferdraht der beste Ingenieur, den wir hatten. Er wurde abtrünnig und ging zur Venture Company, kurz bevor ich die Tüftlerverbindung verließ, und er nahm seine größten Technologien mit. Er hortete seine Geheimnisse und gab nur hier und da ein Geheimnis an den inneren Kreis seiner Vertrauten weiter.\n\nWenn er das Samophlang gebaut hat, dann besitzt er wahrscheinlich das Handbuch. Das Letzte, was ich von ihm gehört habe, war, dass er hier in der Nähe vor der Felsadermine im Nordosten arbeitet. Besorgt das Handbuch von ihm und sammelt die Seiten ein, die seine Anhänger noch haben.", sourceObjective = "Sammelt die Teile des Samophlanghandbuchs ein.", progress = "Habt Ihr Kupferdraht gefunden?", completion = "Ihr habt es gefunden! Puh, es hat über 600 Seiten, und nur 30 davon wurden absichtlich frei gelassen.\n\nSehen wir uns das mal an. Kapitel drei: Rückspleißung der obenliegenden Kropfachswelle im Schwungrad-Flaschenzug? Interessant. Kapitel Sieben: Ventilsteuerung für die Hochdruck-Expansionskondensatoren!? Was für ein tolles Buch! Und ich weiß immer noch nicht, was dieses Ding macht.\n\nHier, nehmt ein paar meiner alten Werkzeuge. Lassen wir das Ding noch ein letztes Mal an!", sourceObjectiveStatus = "unverified-source-field" }
quests[14007] = { id = 14007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Ich bin Bäm Megabombe, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen und schießt dann dreimal auf eine Trainingsattrappe.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14008] = { id = 14008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Ich bin Zisch Zündel, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen und wendet den Zauber dann zweimal auf eine Trainingsattrappe an.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14009] = { id = 14009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Ich bin Schwester Goldglanz, Eure persönliche Lehrerin, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", sourceObjective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen, und wendet den Zauber dann dreimal auf eine Trainingsattrappe an.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14010] = { id = 14010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Ich bin Slinky Scharfklinge, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", sourceObjective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen, und wendet es dann dreimal auf eine Trainingsattrappe an.", progress = "Wann immer Ihr dazu bereit seid, mein Herr.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14011] = { id = 14011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Ich bin Lawinus Maximus, Euer persönlicher Lehrer, <Sir/Madame>.\n\nIch habe Euren Namen hier schon mehrfach genannt bekommen, ich dachte mir, Ihr könntet vielleicht Ausbildung benötigen. Dann seid Ihr hier an der richtigen Adresse.\n\nWenn Ihr besser werdet in dem, was Ihr tut, wird es möglich sein, vollkommen neue, großartige Dinge zu tun. Vertraut mir, es funktioniert. Ich verdiene mein Geld damit, das den Leuten zu erklären.\n\nJedenfalls, verbessert Eure Fertigkeiten als Schamane und benutzt dann Eure neuen Fähigkeiten an einer der Trainingsattrappen im Südosten.", sourceObjective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen und wendet ihn dann zweimal auf eine Trainingsattrappe an.", progress = "Wann immer Ihr dazu bereit seid, mein Herr.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14012] = { id = 14012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Ich bin Bosa Blick, Euer persönlicher Lehrer, <Sir/Madame>.\n\nMir wurde berichtet, dass Ihr Euch für das Leben als {class} interessiert?\n\nSchaut mal, sammelt einfach ein paar Erfahrungen und dann lernt Ihr auch mehr von dem, was Ihr am besten könnt. Hilfreich, oder?\n\nAlso, geht, sammelt Erfahrungen und wenn Ihr dann etwas Neues erlernt, kommt Ihr zurück und probiert es an einer der Trainingsattrappen hier aus.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen, dann wirkt den Zauber 3-mal auf eine Trainingsattrappe.", completion = "Gern geschehen, Boss!\n\nKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14013] = { id = 14013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmangriff", description = "<Der Kriegomatic NX-01 schaltet sich ein.>\n\nBoss {name} erkannt. Ich bin Kriegomatic NX-01.\n\nWarnung: Unzureichende Erfahrung erkannt! Sammelt bitte mehr Erfahrung, um weitere Fähigkeiten zu erlernen.\n\nDemonstriert neue Fähigkeiten an den Trainingsattrappen in der Nähe anwenden, um die Ausbildung fortzusetzen.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Führt den Angriff dann auf eine Trainingsattrappe aus.", progress = "Kriegomatic NX-01 online und bereit, mein Herr.", completion = "Der Kriegomatic NX-01 ist programmiert, um zu dienen.\n\nKehrt jederzeit zurück, wenn Ihr etwas lernen wollt. Diese Einheit bringt Euch alles bei, was sie weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[14014] = { id = 14014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt unsere Sachen zurück!", description = "Unsere Bomben und Werkzeuge! Diese hinterhältigen Affen aus dem Osten haben sie alle im Schutz der Dunkelheit gestohlen!\n\nKönnt Ihr dorthin gehen und sie für uns zurückholen, {name}? Ohne diese Werkzeuge haben wir keine Chance, von dieser Insel herunterzukommen!", sourceObjective = "Besorgt 8 Werkzeugkisten.", progress = "Bombenwerfende Affen?! Nicht auszudenken!!!", completion = "<Sassy atmet beim Anblick der Werkzeuge und Bomben, die Ihr zurückgeholt habt, erleichtert auf.>\n\nIch dachte, das wäre unser sicherer Untergang. Aber jetzt können wir daran arbeiten, von dieser Insel zu fliehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14016] = { id = 14016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch des Schwarzen Ritters", description = "Ich wollte die Überreste des Schwarzen Ritters nach Eurem Sieg vom Turnierplatz entfernen lassen, aber Argentumbeichtpatin Blondlocke bestand darauf, dass er ein ordentliches Begräbnis erhält. Seither hält sich eine düstere Gegenwart hartnäckig auf dem Friedhof, und niemand wagt sich mehr dorthin, um die Gefallenen zu ehren.\n\nWürdet Ihr dem Friedhof gleich außerhalb des Turnierplatzes im Osten einen Besuch abstatten und sehen, ob Ihr herausfinden könnt, was dort vor sich geht?", sourceObjective = "Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz möchte, dass Ihr das Grab des Schwarzen Ritters untersucht.", completion = "<Kreuzfahrerin Rhydalla runzelt die Stirn.>\n\nGlaubt Ihr, sie haben das geplant? Spielt vermutlich keine Rolle, doch es gefällt mir nicht, dass wir ihnen womöglich genau in die Hände gespielt haben. Was immer auch vor sich geht, wir müssen es vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[14017] = { id = 14017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Schwarzen Ritters", description = "Ihr sagt, dass Kultisten die Leiche entfernt haben? Mir fällt da nur ein Ort ein, zu dem sie sie gebracht haben können: Todessprechers Wacht, das Lager auf der Anhöhe westlich des Turnierplatzes.\n\nWas auch immer die Kultisten vorhaben, man muss sie aufhalten. Die Gerüchte, die ich gehört habe, können also nur wahr sein. Der berüchtigte Doktor Kohler muss unter den Kultisten sein und seine Kunst ausüben. Sucht nach einer Anhöhe oder einem Altar, von dem aus man Sicht auf das Kultistenlager hat. Tötet den Doktor und sucht nach Beweisen über seine Machenschaften. Bremst ihn bei seiner Arbeit, egal wie.", sourceObjective = "Geht nach Todessprechers Wacht, bringt Doktor Kohlers Befehle in Euren Besitz und kehrt dann zu Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr herausgefunden, was sie mit den Überresten des Schwarzen Ritters machen?", completion = "Der Doktor wird keine Zeit haben, sein Werk zu vollenden, aber sein Plan wurde schon ins Rollen gebracht. Laut Euren Berichten haben die Diener des Lichkönigs den Schwarzen Ritter wiederbelebt und mit neuer Kraft erfüllt - niemand kann sagen, was sein Meister im Schilde führt. Diese Verschwörung aufzudecken war gute Arbeit. Ich werde dem Hochmeister Adelard von Euren Funden berichten und gemeinsam werden wir die Teilnehmer des Turniers davor warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14018] = { id = 14018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jener, der nach Vergebung sucht", description = "Die Stimme der Göttin hat am Mondbrunnen zu Euch gesprochen, {name}. Das Heilmittel für Relara liegt im Osten beim Rajenbaumturm, der dem Verderben anheimgefallen ist.\n\nAvrus Böswisper wünscht Vergebung und Erlösung. Es liegt an Euch, ihn zu unterstützen und dabei hoffentlich auch meinem Kind zu helfen.", sourceObjective = "Sprecht mit Avrus Böswisper beim Rajenbaumturm im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[14019] = { id = 14019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affentheater", description = "Wir haben immense Probleme mit den Affen im Dschungel östlich von hier. Sie haben all unseren Sprengstoff gestohlen und jetzt fangen sie an, damit durch die Gegend zu werfen.\n\nUnd manchmal sogar auf uns!\n\nIch habe Zisch Zündel befohlen, etwas von seinem Nitro in diese Bananen zu füllen. Kein Affe kann einer leckeren Banane widerstehen!\n\nIhr müsst sie nur damit füttern.", sourceObjective = "Füttert 10 bombenwerfende Affen, indem Ihr ihnen Nitrokaliumbananen zuwerft.", completion = "Sie sind in die Luft gegangen, als sie die Bananen gegessen haben?! Das ist ja urkomisch!\n\nIch glaube, ich ziehe auch los und füttere ein paar.", sourceObjectiveStatus = "unverified-source-field" }
quests[14021] = { id = 14021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenarbeiter in Not", description = "Kluge Bergbauaffen!\n\nSie sind in der ganzen Höhle verstreut und bauen Erz ab… mit Spitzhacken! Das ist doch nicht normal. Ich bin mir sicher, dass es an dem Kaja'mit liegt.\n\nKeiner meiner Minenarbeiter ist wieder herausgekommen. Und ich habe nicht mehr viele! Ihr könnt also meine Not erkennen, {name}.\n\n<Der Vorarbeiter senkt die Stimme.>\n\nDiese Typen sind nicht mal annähernd so gut wie meine alte Dschungeltrolltruppe. Ah, das waren noch Zeiten!\n\nVielleicht könnt Ihr meinen letzten Minenarbeiter hier durch die Höhle begleiten und ihm die Affen vom Leib halten? Wir brauchen dieses Kaja'mit!", sourceObjective = "Eskortiert den verängstigten Minenarbeiter durch die Kaja'mithöhle.", completion = "Wir haben die Hauptader gefunden!!!\n\nSo, was hat es mit diesem Hexendoktor der Pygmäen auf sich, der die Affen kontrolliert? Wenn er nämlich tot ist, kann ich ganz legal Anspruch geltend machen… Nicht, dass ich das nicht sowieso vorgehabt hätte. Nach Goblinrecht gehört die Kaja'mithöhle uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[14022] = { id = 14022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgerfreuden", description = "Möchtet Ihr nicht vielleicht das Pilgerfreudenfest mit uns feiern, {name}? Dies ist eine Zeit des Besinnens auf Eure Reisen und Euer Glück, eine Zeit des Teilens - von gutem Essen und unterhaltsamen Geschichten!\n\nIhr könnt an den wundervollen Pilgerfreudenfeierlichkeiten in der Nähe der größeren Städte teilhaben, indem Ihr an einer der Festtafeln Platz nehmt und das vorhandene Essen verteilt.\n\nWenn Ihr lernen möchtet, wie man die traditionellen Pilgerfreudenspeisen zubereitet, sucht Gregory Tabor auf. Ihr findet ihn vor den Toren von Sturmwind.", sourceObjective = "Sprecht mit Gregory Tabor außerhalb der Tore Sturmwinds.", completion = "Wenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, kann ich Euch helfen. Falls Ihr noch keine Kochkenntnisse besitzt, braucht ihr nur ein wenig zu üben und im Nu seid Ihr ein richtiger Koch!", sourceObjectiveStatus = "unverified-source-field" }
quests[14023] = { id = 14023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrotfüllung", description = "Unsere Gewürzbrotfüllung ist das Prunkstück der Pilgerfreudentafel. Das Rezept war schon immer besonders beliebt in Sturmwind und hat nun seinen rechtmäßigen Platz im Pilgerfreudenfest-Kochbuch eingenommen.\n\nWenn Ihr in der Kochkunst bereits bewandert seid, könnt Ihr Euer Exemplar des Kochbuchs und alle benötigten Zutaten für ein Festmahl vom Händler des Pilgerfreudenfests erstehen. Und seid Ihr es nicht, so ist jetzt die beste Gelegenheit, dies zu ändern!\n\nHabt Ihr die Gewürzbrotfüllung zubereitet, bringt sie zu Jasper Moore, in der Nähe der Festtafel.", sourceObjective = "Bereitet 5 Portionen Gewürzbrotfüllung zu und bringt sie zu Jasper Moore an die Festtafel außerhalb der Tore Sturmwinds.", progress = "Wir können immer etwas von der köstlichen Gewürzbrotfüllung gebrauchen, sie ist ausgesprochen beliebt.", completion = "Ausgezeichnet. Genau was wir brauchen! Es ist harte Arbeit, dafür zu sorgen, dass die Tische niemals leer werden, doch es lohnt sich!", sourceObjectiveStatus = "unverified-source-field" }
quests[14024] = { id = 14024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbiskuchen", description = "Eure Gewürzbrotfüllung riecht ausgesprochen verlockend, doch keine Pilgerfreudentafel ist ohne einen prächtigen Kürbiskuchen komplett. Dies ist ein weiteres sehr beliebtes Gericht hier in Sturmwind, denn Kürbiskuchen wird aus den reifen Elwynnkürbissen zubereitet, die nur hier gedeihen.\n\nSolltet Ihr nicht wissen, wie man ihn zubereitet, könnt Ihr das Rezept in Eurem Pilgerfreundenfest-Kochbuch finden.\n\nWürde es Euch etwas ausmachen, einige Kuchen zuzubereiten und sie Edward Winslow zu bringen, außerhalb von Eisenschmiede? Sein Vorrat ist sicherlich schon knapp geworden.", sourceObjective = "Bereitet 5 Kürbiskuchen zu und bringt sie Edward Winslow an die Festtafel außerhalb von Eisenschmiede.", progress = "Mehr Kürbiskuchen? Genau rechtzeitig.", completion = "Der Kürbiskuchen ist hier oben ausgesprochen beliebt. Ich habe noch nie zuvor gesehen, dass Zwerge über ein Gemüsegericht so aus dem Häuschen geraten!", sourceObjectiveStatus = "unverified-source-field" }
quests[14028] = { id = 14028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbeerenchutney", description = "Wenn Ihr bislang noch nie Moosbeerenchutney versucht habt, dann entgeht Euch etwas! Es wird aus den frischesten, schmackhaftesten Moosbeeren des ganzen Sumpflands zubereitet. Ersteht einfach welche vom nächsten Händler des Pilgerfreudenfests, wenn Ihr Euch an der Zubereitung versuchen wollt.\n\nDas Rezept findet Ihr in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht in Eile seid, würdet Ihr vielleicht etwas Chutney zubereiten und zu Jasper Moore bringen, außerhalb Sturmwinds? Ich habe ihm versprochen, es gegen den Kuchen einzutauschen, den Ihr mir gebracht habt.", sourceObjective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Jasper Moore an die Festtafel außerhalb Sturmwinds.", progress = "Rieche ich da etwa Moosbeerenchutney?", completion = "Endlich, das versprochene Moosbeerenchutney! Ihr glaubt ja nicht, wie schnell die Feiernden das immer verputzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14030] = { id = 14030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus darbt", description = "Vielen Dank für das Moosbeerenchutney. Es gibt so viel zuzubereiten, ich kann kaum noch einen klaren Gedanken fassen! Und zu all dem kommt nun noch, dass Isaac Allerton in Darnassus mittlerweile praktisch alle Zutaten ausgegangen sind! Ich kann wohl kaum erwarten, dass Ihr so gut wäret, einzuspringen und etwas mehr Gewürzbrotfüllung und Kürbiskuchen zuzubereiten, oder? Der Händler sollte alle Zutaten parat haben, die Ihr benötigen würdet.\n\nIhr könnt ihn in der Nähe der Festtafel finden, auf der Wiese hinter der Terrasse der Krieger in Darnassus.", sourceObjective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Kürbiskuchen zu Isaac Allerton in der Nähe des Eingangs nach Darnassus.", progress = "Seid Ihr gekommen, um am Pilgerfreudenfestmahl teilzunehmen?", completion = "Vielen Dank für alles! Ich hatte schon begonnen, mir Sorgen zu machen. Da Ihr schon mal hier seid, könntet Ihr gleich auch noch Euer Glück mit der Zubereitung kandierter Süßkartoffeln versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14031] = { id = 14031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfasst das Unbekannte", description = "Hey, {name}, da sind Höhlenmalereien und andere Artefakte überall in der Höhle.\n\nKönntet Ihr Eure am Gürtel befestigte HGK Schnappblitz verwenden, um an den markierten Orten Bilder aufzunehmen? Nehmt im hinteren Teil der Höhle ein Bild des Altars auf.\n\nIch bin sicher, Sassy würde diese Informationen gern in die Hände bekommen.", sourceObjective = "Verwendet Eure HGK Schnappblitz, um Bilder an den springenden Kameras der drei Höhlenmalereien und dem Altar der Pygmäen aufzunehmen.", completion = "Was ist das?\n\n<Sassy überprüft die Bilder, während sie Eurer Geschichte über die Kaja'mithöhle lauscht.>\n\nDieser Hexendoktor der Pygmäen muss also aus einem Volk stammen, das wir noch nie gesehen haben. Vielleicht sollten wir sie Kyxillinge nennen?\n\nSie müssen die Höhle bemalt haben. Ich bin mir nicht sicher, ob mir gefällt, was Ihr mir da erzählt.\n\nFür mich klingt das so, als seien das Bilder von uns und ihnen auf einer Insel mit einem explodierenden Vulkan!", sourceObjectiveStatus = "unverified-source-field" }
quests[14032] = { id = 14032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung im Koboldlager", description = "Eure erste Aufgabe ist eine Säuberung, {name}. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", sourceObjective = "Tötet 8 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[14033] = { id = 14033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandierte Süßkartoffeln", description = "Solange Ihr hier seid, solltet Ihr Euch einen Vorrat an Süßkartoffeln von Teldrassil zulegen. Aus ihnen werden die köstlichsten kandierten Süßkartoffeln zubereitet, die Ihr je schmecken werdet!\n\nWenn Ihr mir nicht glaubt, sucht das Rezept aus Eurem Pilgerfreudenfest-Kochbuch heraus und probiert es mal! Und solltet Ihr welche übrig haben, könntet Ihr sie mit Gregory Tabor in der Nähe der Festtafel außerhalb Sturmwinds teilen. Er liebt diese Kartöffelchen! Aber wenn man ihm so zuhört, gewinnt man den Eindruck, er liebt alles, was man essen kann.", sourceObjective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Gregory Tabor außerhalb der Tore Sturmwinds.", progress = "{name}, wie schön, Euch zu sehen.", completion = "Aaah, kandierte Süßkartoffeln! Meine Leibspeise! Hat Isaac Euch davon erzählt?", sourceObjectiveStatus = "unverified-source-field" }
quests[14034] = { id = 14034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foote, der Mann mit dem Plan", description = "Wir haben von den Spannungen zwischen der Allianz und der Horde profitiert, bis Konteradmiral Hartley in MEINEM Hafen angelegt hat und angefangen hat, seine Nase in meine Angelegenheiten zu stecken. Er hat Schiffe gejagt und beschlagnahmt, die unter der Flagge der Horde gesegelt sind, mit dem Ziel, sie davon abzuhalten, einen neutralen Hafen anzulaufen.\n\nIch werde sicher keinem wurstfingrigen Menschen erlauben, meinen Profit zu schmälern! Besorgt mir die Pläne des Flaggschiffs. Hartleys Chefingenieur pichelt sich in der Taverne zum geborstenen Kiel einen an, einfach den Hügel hinauf...", sourceObjective = "Besorgt die Schiffsschemata von Chefingenieur Foote in der Taverne 'Zum geborstenen Kiel' in Ratschet.", progress = "Habt Ihr, was ich brauche?", completion = "Ah, da sind sie – da steht es, genau hier! Sein Flaggschiff heißt also 'Die Kriegsmächtige', wie?\n\nWollen wir mal sehen, was man braucht, um diesen Plagegeist auf den Meeresgrund zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[14035] = { id = 14035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langsam gerösteter Truthahn", description = "Jedes Pilgerfreudenfestmahl benötigt einen Mittelpunkt der Tafel, und damit meine ich kein dekoratives Füllhorn. Nein, die wahre Krönung der Tafel ist ein schmackhafter gerösteter Truthahn.\n\nIhr findet ein fabelhaftes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum erlegt Ihr nicht ein paar wilde Truthähne und bereitet sie selbst zu? Diese Tierchen sind überall im Wald von Elwynn unterwegs, Ihr solltet sie leicht aufspüren können.\n\nKönnt Ihr sie zu Isaac Allerton an die Tore von Darnassus bringen, sobald sie fertig zubereitet sind?", sourceObjective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Isaac Allerton, in der Nähe der Tore von Darnassus.", progress = "Was hat Euch denn wieder nach Darnassus verschlagen, {name}?", completion = "Die sind grandios! Und sie kommen genau rechtzeitig, um hungrige Mäuler zu stopfen. Danke, {name}! Ihr habt wahrlich alle Gänge eines traditionellen Pilgerfestmahls gemeistert.", sourceObjectiveStatus = "unverified-source-field" }
quests[14036] = { id = 14036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgerfreuden", description = "Seid Ihr hier, um mit uns das Pilgerfreudenfest zu feiern? Dies war einst eine Zeit der Einkehr und des Gedenkens an getane Reisen und das Glück, ein gutes Mahl mit Freunden teilen zu können. Noch heute feiern viele das Fest.\n\nIhr könnt an Pilgerfreudenfeierlichkeiten in der Nähe größerer Städte teilnehmen, indem Ihr an einer der Festtafeln Platz nehmt und das dort vorhandene Essen verteilt.\n\nWenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, wendet Euch an Miles Standish im Innenhof über Unterstadt.", sourceObjective = "Sprecht mit Miles Standish im Innenhof über Unterstadt.", completion = "Wenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, kann ich Euch helfen. Falls Ihr noch keine Kochkenntnisse besitzt, braucht ihr nur ein wenig zu üben und im Nu seid Ihr ein richtiger Koch!", sourceObjectiveStatus = "unverified-source-field" }
quests[14037] = { id = 14037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrotfüllung", description = "Unsere Gewürzbrotfüllung ist das A und O der Pilgerfreudentafel. Das Rezept stammt aus besseren Tagen in Lordaeron und hat nun seinen Platz unter den traditionellen Gerichten gefunden.\n\nSeid Ihr bereits in der Kochkunst bewandert, stattet dem Händler des Pilgerfreudenfests einen Besuch ab und Ihr erhaltet Euer eigenes Exemplar des Pilgerfreundenfest-Kochbuchs und alle hiesigen Zutaten, die Ihr benötigt, um ein Festmahl zuzubereiten. Seid Ihr noch unerfahren in der Kunst des Kochens, so ist dies die beste Gelegenheit für Euch, zu beginnen!\n\nSobald Ihr die Füllung zubereitet habt, übergebt sie William Mullins in der Nähe der Festtafel.", sourceObjective = "Bereitet 5 Portionen der Gewürzbrotfüllung zu und bringt sie dann zu William Mullins an die Festtafel im Innenhof über Unterstadt.", progress = "Die Tafel könnte wirklich noch etwas mehr Gewürzbrotfüllung vertragen.", completion = "Dafür zu sorgen, dass die ganze Festtafel immer schön gefüllt bleibt, ist keine einfache Aufgabe. Und wenn man bedenkt, dass wir eigentlich gar nicht mehr zu essen brauchen, kommt es einem besonders eigenartig vor.\n\n<William zuckt mit den Achseln.>\n\nTradition ist Tradition.", sourceObjectiveStatus = "unverified-source-field" }
quests[14038] = { id = 14038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenarbeit", description = "<Gazlowe breitet die Pläne auf dem Tisch aus und tippt mit seinem kleinen Finger auf das Achterdeck eines Schiffes unter der Wasserlinie.>\n\nDa! Dort ist der Rumpf am dünnsten, wo die Kurbelwelle auf das Schaufelrad trifft. Und das ist direkt neben dem Magazin!\n\n{name}, man wird mich doch nicht zur Verantwortung ziehen können, wenn so ein tollkühner {class} der Horde eine Haftmine an dieser Stelle des Rumpfs anbringt. Nicht einmal, wenn ich die Mine zur Verfügung stelle. Und ihn bezahle. Großzügig. Das Schiff liegt südöstlich von hier vor Anker... nichts wie hin!\n\nDann funkt mich über diesen gestohlenen Gnomcorder an.", sourceObjective = "Setzt eine Haftmine an den dünnsten Teil des Rumpfs der Kriegsmächtigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14039] = { id = 14039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimat der Kaldorei", description = "Es war zweifellos eine große Ehre, Euch kennengelernt zu haben. Ihr seid der lebende Beweis dafür, wie nobel Euer Volk ist.\n\nGeht jetzt und beendet diese letzte Aufgabe. Bringt das Wasser zu Tyrande Wisperwind in Darnassus.", sourceObjective = "Bringt das gefüllte Gefäß zu Tyrande Wisperwind in Darnassus.", progress = "Wie ist es Euch ergangen, junger Mann?", completion = "Ah, gesegnetes Wasser aus unseren Mondbrunnen. Ihr seid also Zeuge des Geistes der Kaldorei geworden?\n\nIn letzter Zeit fällt mir immer mehr auf, dass dieser Geist mehr Fragen aufwirft als beantwortet. Aber so ist nun mal die ständige Natur der Entdeckungen, die uns in unseren dunkelsten Stunden umtreibt.\n\nIch werde Euch die einfachsten Antworten geben, die mir zur Verfügung stehen. Malfurion ist zu mir... zu uns... zurückgekehrt, dennoch sind wir schweren Zeiten ausgesetzt. Hirschhaupt ist verschwunden und die Welt windet sich vor Schmerzen - Malfurion muss viel heilen und er wird Hilfe benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14040] = { id = 14040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbiskuchen", description = "Eure Gewürzbrotfüllung ist einfach wunderbar, aber uns fehlt noch der ein oder andere Kürbiskuchen zum Glück. Ein weiteres traditionelles Gericht der Region, denn hierzu werden reife Tirisfalkürbisse verwendet, die nirgends sonst gedeihen. \n\nFalls Ihr nicht wisst, wie man sie zubereitet, findet Ihr das Rezept in Eurem Pilgerfreudenfest-Kochbuch.\n\nMacht es Euch etwas aus, uns ein paar zuzubereiten und sie Francis Eaton außerhalb von Orgrimmar zu bringen? Ich bin sicher, es sind nicht mehr viele übrig.", sourceObjective = "Bereitet 5 Stücke Kürbiskuchen zu und bringt sie zu Francis Eaton an die Festtafel außerhalb von Orgrimmar.", progress = "Wir können immer frischen Kürbiskuchen gebrauchen.", completion = "Der Kuchen geht weg wie warme Semmeln. Ich glaube ja, die Leute halten sich gar nicht erst mit dem Hauptgericht auf, sondern gehen gleich über zum Nachtisch. Habt Ihr den Kuchen denn schon selbst einmal versucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[14041] = { id = 14041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbeerenchutney", description = "Habt Ihr einmal das Moosbeerenchutney versucht? Es wird aus frischen, schmackhaften säuerlichen Moosbeeren vom Südstrom zubereitet. Besorgt Euch einfach welche vom Händler des Pilgerfreudenfests, wenn Ihr Euch mal am Rezept versuchen wollt.\n\nIhr findet es in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht zu viel zu tun habt, könntet Ihr vielleicht etwas Chutney zubereiten und es zu Dokin Grasland am Fuße des Aufzugs bringen, westlich von Donnerfels?", sourceObjective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Dokin Grasland am Fuße des Aufzugs westlich von Donnerfels.", progress = "Wie gefallen Euch die Pilgerfreuden, {class}?", completion = "Ah, endlich, mehr Moosbeerenchutney! Es ist unfassbar, wie schnell die Feiernden es vertilgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14042] = { id = 14042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kabummition", description = "Hartley muss all seine Sprengmittel am Strand entladen haben. Ziehen wir ihm diesen Zahn, {name}!\n\nGeht den Strand entlang und sucht nach seinen Sprengstoffvorräten. Zündet sie an und er sitzt ohne Bewaffnung an Land fest, während die Kriegsmächtige repariert wird.\n\nIch treffe Euch wieder hier in Ratschet.", sourceObjective = "Zerstört 5 Munitions-Vorratslager von Theramore an der Küste.", completion = "Ha! Sehr gut gemacht, {name}. Diese Idioten von der Allianz werden das niemals zu mir zurückverfolgen können. Inzwischen heißt es wieder zurück zur Tagesordnung: Schmuggel, doppelte Spielchen und Wucher... Ich habe viel nachzuholen.\n\nHier habt Ihr einen Anteil von meinen Gewinnen. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[14043] = { id = 14043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandierte Süßkartoffeln", description = "Da Ihr schon mal hier seid, solltet Ihr gleich Euren Vorrat an Süßkartoffeln aus Mulgore aufstocken. Sie werden für die Zubereitung kandierter Süßkartoffeln verwendet, mein absoluter Favorit auf der Festtafel.\n\nWenn Ihr meinem Urteil nicht traut, sucht Euch das Rezept heraus und probiert es einmal! Solltet Ihr unterwegs nach Orgrimmar sein, könnt Ihr sie gleich zu Francis Eaton in der Nähe der Festtafel direkt außerhalb der Stadt bringen. Ich bemühe mich, ihn ausreichend zu versorgen, aber dort geht immer alles so schnell weg!", sourceObjective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Francis Eaton außerhalb der Tore Orgrimmars.", progress = "Willkommen zurück, {name}.", completion = "Dokin hat Euch also dazu überredet, mit den kandierten Süßkartoffeln auszuhelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14044] = { id = 14044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstadt ist unterversorgt", description = "Vielen Dank für die kandierten Süßkartoffeln. Es gibt so viel zu kochen, ich komme kaum hinterher! Und jetzt schickt mir Miles auch noch eine Nachricht, dass ihm Gewürzbrotfüllung und Moosbeerenchutney ausgehen! Ihr hättet nicht zufällig Zeit, mir damit noch etwas unter die Arme zu greifen und ein wenig mehr von beidem zu kochen? Der Händler sollte alle nötigen Zutaten vorrätig haben.\n\nIhr könnt Miles Standish in der Nähe der Festtafel finden, im Innenhof in den Ruinen über Unterstadt.", sourceObjective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Portionen Moosbeerenchutney zu Miles Standish in der Nähe des Eingangs von Unterstadt.", progress = "Wie gut, Euch wiederzusehen, {name}.", completion = "Vielen Dank für alles, was Ihr gebracht habt. Einige der Tische machen schon langsam einen etwas kahlen Eindruck.", sourceObjectiveStatus = "unverified-source-field" }
quests[14045] = { id = 14045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Baron Küstenschipper", description = "Der ruchlose Pirat Baron Küstenschipper war der Schrecken dieser Meere, bevor die Allianz seine Flotte zerstört hat und die Überlebenden gefangen genommen hat. Gefällt mir das? Sehe ich aus, als ob ich vor Freude hüpfe und springe, {name}?\n\nKüstenschipper hat einige meiner wertvollsten Ladungen vor seiner Gefangennahme geraubt. Man sagt, er habe sie vergraben, bevor er gefangen genommen wurde. Ich will meine Waren wieder zurück haben! Findet Küstenschipper im Lager der Allianz südlich von hier und versucht, ihm zu entlocken, wo mein Schatz ist.", sourceObjective = "Findet den berüchtigten Piraten Baron Küstenschipper und sprecht mit ihm.", completion = "Ha ha! Der alte Gazlowe hat seine Schätze also noch nicht abgeschrieben, oder? Nun, es sieht so aus, als ob mir das alte, goldgierige Langohr was zum Verhandeln gegeben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[14046] = { id = 14046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ehemaliger Baron", description = "Ich werd' sicher am Galgen landen, Kamerad. Jetzt nützt mir der Schatz nur noch herzlich wenig...\n\nEs sei denn, ich kann mir damit mein Leben erkaufen. Ich schlag Euch'n Geschäft vor, {race}. Befreit mich von diesen Handschellen und ich sage Euch, wo der Schatz verbuddelt ist.\n\nUnd auf mein Wort ist Verlass. Ich war mal ein richtiger Baron, müsst Ihr wiss'n.", sourceObjective = "Wenn Ihr ihm traut, sprecht mit Baron Küstenschipper, um ihn von seinen Handschellen zu befreien.", completion = "<Der Baron reibt sich seine wunden Handgelenke und bricht in ein bösartiges Grinsen aus.>\n\nOh, ich werde mich noch nicht dünne machen. Ich befreie meine Kameraden und haue und steche mir meinen Weg hier heraus, sobald mir danach ist. Und was Euch angeht – versprochen ist versprochen. Reden wir über diesen Schatz...", sourceObjectiveStatus = "unverified-source-field" }
quests[14047] = { id = 14047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langsam gerösteter Truthahn", description = "Zu jedem Pilgerfreudenfestmahl gehört ein kulinarischer Höhepunkt - für uns ist das ein langsam gerösteter Truthahn. Es gibt nichts besseres, um ein reichhaltiges Mahl angemessen zu krönen!\n\nIhr findet ein gutes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum jagt Ihr nicht ein paar Truthähne und bereitet sie dann zu? Sie sind überall in Tirisfal zu finden.\n\nWenn sie fertig sind, könntet Ihr sie dann zu Francis Eaton außerhalb von Orgrimmar bringen?", sourceObjective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Francis Eaton, in der Nähe der Tore von Orgrimmar.", progress = "Was hat Euch denn wieder nach Orgrimmar verschlagen, {name}?", completion = "Die sehen köstlich aus. Vielen Dank, {name}. Ihr habt wahrlich alle Gänge eines traditionellen Pilgerfestmahls gemeistert.", sourceObjectiveStatus = "unverified-source-field" }
quests[14048] = { id = 14048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich krieg einfach nicht genug ... Truthahn", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall im Wald von Elwynn selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", sourceObjective = "Bringt 20 langsam geröstete Truthähne zu Caitrin Eisenkessel außerhalb von Eisenschmiede.", progress = "Habt Ihr ein paar Truthähne aufgespürt?", completion = "Genau das Richtige, vielen Dank, {name}. Ihr habt es genau getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14049] = { id = 14049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst ungewöhnliche Karte", description = "Also, es ist so, Kamerad: Um meine Schatzkarte zu beschützen, habe ich sie auf die Kopfhaut meines ersten Steuermanns tätowiert.\n\nNatürlich ist er bereits genauso tot wie der Großteil vom Rest meiner Mannschaft. Die Mitglieder der Allianz wissen nicht einmal, was sie da in Händen halten. Sein abgeschlagener Kopf hängt an einem Baum am Eingang zu diesem Lager.\n\nSchnappt Euch den Kopf und bringt ihn zu Gazlowe in Ratschet.", sourceObjective = "Besorgt Euch den tätowierten Piratenkopf vom Eingang des Geländes der Allianz.", progress = "War Baron Küstenschipper noch am Leben? Habt Ihr etwas für mich?", completion = "Was? Was ist das? Ich schicke Euch los, meinen Schatz zu finden und Ihr bringt mir einen verlausten Kopf?", sourceObjectiveStatus = "unverified-source-field" }
quests[14050] = { id = 14050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazlowes Vermögen", description = "Verteufelt noch eins, Ihr hattet recht! Auf die Kopfhaut ist eine Karte tätowiert.\n\nDieser verfluchte Baron! Er hat meinen Schatz direkt unter meiner Nase vergraben. Oder über meinem Kopf. Diese Karte deutet auf einen Ort an den Steilufern über Ratschet im Süden.\n\nFolgt der Straße nach Westen aus der Stadt, begebt Euch auf den Hügel, geht nach Süden, dann lauft zurück zur Küste und sucht nach dem riesigen Baum, von dem aus man die Bucht überblickt. Schnappt Euch meinen Schatz und ich werde ihn mit Euch teilen!", sourceObjective = "Gazlowe will, dass Ihr seinen verscharrten Schatz an den Klippen mit Meerblick ausgrabt.", progress = "Ich schließe jetzt meine Augen, {name}. Und wenn ich sie wieder öffne, erwarte ich, dass dieser Raum randvoll mit Schätzen ist. Einverstanden?", completion = "Gute Arbeit, {name}!\n\nOh, der Baron hat versucht, Euch aufzuhalten, wie? Nun, ich hoffe, Ihr habt's ihm gezeigt.\n\nNun, ich habe Euch einen Anteil an dem Schatz versprochen, den Ihr zurückgebracht habt. Mal sehen... Wie viel ist ein Prozent von einem halben Prozent? Ah, hier bitte schön.", sourceObjectiveStatus = "unverified-source-field" }
quests[14051] = { id = 14051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Füllung ist alles!", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", sourceObjective = "Bringt 20 Portionen Gewürzbrotfüllung zu Caitrin Eisenkessel nahe der Festtafel außerhalb von Eisenschmiede.", progress = "Wie sieht es mit der Füllung aus?", completion = "Ein Glück, Ihr habt es geschafft! Ohne Gewürzbrotfüllung wäre das ganze Festmahl ein einziger Reinfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[14052] = { id = 14052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter vier Augen mit Tony", description = "Die Situation mit den Piraten behindert meine Unternehmungen erheblich. Käpt'n Garvey greift jedes Schiff an, das er erblickt - sogar diejenigen, von deren Besitzern ich mir ein 'Schutz'-Geld erschwindelt habe. Wir müssen diese Piraten auf frischer Tat ertappen und zwar bald!\n\nIch kenne genau den richtigen Gesellen, ein Leutnant von Garvey, der sich auf die Kungeleien vom alten Flunkerblick einlässt. Er hat mir angeboten, für mich eine kleine 'Meuterei' anzuzetteln. Sobald diese Jungs für uns arbeiten, ist das ein Kinderspiel, nicht wahr?\n\nSprecht mit Tony Zweihauer auf Prügeleiland im Süden.", sourceObjective = "Sprecht mit Tony Zweihauer auf Prügeleiland im Nördlichen Brachland.", completion = "Heiho Mann, hat Flunkerblick Euch geschickt? Gut, gut. Habt Ihr das Geld dabei? Nein?...Was ist mit den Gewehren?", sourceObjectiveStatus = "unverified-source-field" }
quests[14053] = { id = 14053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder kein Moosbeerenchutney mehr?", description = "Mein Mann Jasper wollte eigentlich noch mehr Moosbeerenchutney zubereiten, aber wie es scheint, hat er schon genug mit den kandierten Süßkartoffeln für all die Gäste zu tun. Würdet ihr vielleicht aushelfen? Wenn Ihr in der Kochkunst bewandert seid, braucht Ihr nur die säuerlichen Sumpfmoosbeeren, die Ihr beim Händler des Pilgerfreudenfests außerhalb von Eisenschmiede bekommen könnt.\n\nFalls Euch nicht nach Kochen ist, könnt Ihr auch jederzeit jemand anderen um die Zubereitung des Chutneys bitten.", sourceObjective = "Bringt 20 Portionen Moosbeerenchutney zu Ellen Moore an die Festtafel außerhalb Sturmwinds.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Danke. Das sieht wirklich köstlich aus, und Ihr seid ein ganzes Stück schneller als Jasper - aber verratet ihm nicht, dass ich das gesagt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[14054] = { id = 14054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuchen versuchen", description = "Isaac arbeitet hart, um den Feiernden die traditionellen Ursprünge des Pilgerfreudenfests und die Zubereitung aus all den geernteten Zutaten in dieser Jahreszeit näher zu bringen. Ich bemühe mich, die Festtafeln schön gefüllt zu halten, aber Isaacs Leibspeise geht langsam zur Neige - Kürbiskuchen!\n\nKönntet Ihr welchen für uns organisieren? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr reife Elwynnkürbisse vom Händler des Pilgerfreudenfests außerhalb Sturmwinds.", sourceObjective = "Bringt 20 Kürbiskuchen zu Mary Allerton an die Festtafel vor den Toren von Darnassus.", progress = "Wie geht es mit dem Kuchen voran?", completion = "Die sind wunderbar. Isaac wird begeistert sein, und nicht nur er!", sourceObjectiveStatus = "unverified-source-field" }
quests[14055] = { id = 14055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein in die Kartoffeln, raus aus den Kartoffeln", description = "Meine Frau Ellen hat mich damit beauftragt, für gedeckte Tafeln zu sorgen, doch sie ändert ständig ihre Meinung. Zuerst sollte ich Kürbiskuchen zubereiten, nun sind es plötzlich kandierte Süßkartoffeln.\n\nIch habe aber schon mit dem Kuchen angefangen! Vielleicht könntet Ihr mir ja mit den Süßkartoffeln aushelfen? Sie wird sicher angenehm überrascht sein, wenn wir alle ihre Wünsche erfüllen.\n\nSolltet Ihr die Süßkartoffeln selbst kandieren wollen, müsst Ihr sie beim Händler des Pilgerfreudenfests in Darnassus erstehen. Ich danke Euch, {name}.", sourceObjective = "Bringt 20 kandierte Süßkartoffeln zu Jasper Moore an die Festtafel außerhalb von Sturmwind.", progress = "Habt ihr die kandierten Süßkartoffeln dabei?", completion = "Die sind genau richtig! Vielen Dank für Eure Hilfe, {name}. Das Festmahl wird rechtzeitig fertig sein, und Ellen wird sich sicher freuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14056] = { id = 14056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glomp sitzt darauf", description = "Was? Glaubt Flunkerblick etwa, dass eine Meuterei so einfach und so billig ist?\n\nEgal, Mann, das wird schon hinhauen. Zunächst brauchen wir Geld. Käpt'n Garvey hortet gerne die Schätze, die wir erbeutet haben. Mit diesem Geld könnten wir meine handverlesenen Meuterer bezahlen.\n\nDer Schatz befindet sich direkt vor den Baracken hier. Ihr müsst Euch um Käpt'n Garveys 'Schatzmeister' kümmern. Allerdings lässt sich Glomp nicht so einfach herumschubsen. Glaubt mir, ich habe schon mal geschubst, und... Sagen wir, den haut nichts so schnell um.", sourceObjective = "Tötet Glomp und schnappt Euch Glomps Beute.", progress = "Habt Ihr das Gold? Das Geld reicht allemal, um die Köpfe und Herzen der hirnlosen und herzlosen Halsabschneider zu gewinnen.", completion = "Sieh mal. Wir sind steinreich! Für eine Meuterei braucht man zuerst Geld. Wenn man das Geld hat, bekommt man die Macht. Holen wir uns die Macht, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[14057] = { id = 14057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewehre. Wir brauchen Gewehre.", description = "Für jede gute Meuterei braucht man ordentlich Feuerkraft. Käpt'n Garvey beansprucht die besten Schusswaffen für sich: eine ganze Ladung schwerer, zwergischer Steinschlossbüchsen. Er lagert sie bei sich im anderen Gebäude auf der anderen Seite der Insel. Bringt mir sechs dieser Büchsen und ich gebe sie an meine zukünftigen Offiziere weiter...", sourceObjective = "Besorgt 6 schwere, zwergische Gewehre.", progress = "Gewehre, Mann. Habt Ihr sie?", completion = "<Tony schnappt sich eine der Waffen und schaut durch den Lauf.>\n\nOh, sehr schön. Glänzend. Laut. Die können sich sehen lassen.\n\nEs bleibt nicht mehr viel zu tun, bis wir alles soweit haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[14058] = { id = 14058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein in die Kartoffeln, raus aus den Kartoffeln", description = "Roberta Carter hat mich beauftragt, eines der Festtagsgerichte zuzubereiten. Kandierte Süßkartoffeln! Normalerweise würde ich mich darum reißen, aber ich habe der Gastgeberin versprochen, mit ihr auf die Tafeln zu achten.\n\nEs wäre eine große Hilfe, wenn Ihr stattdessen für mich einige kandierte Süßkartoffeln organisieren könntet! Roberta würde mir nie vergeben, wenn ich sie im Stich lasse. \n\nWenn Ihr die Süßkartoffeln selbst kandieren wollt, müsst Ihr zunächst welche vom Händler des Pilgerfreudenfests in Donnerfels erstehen. Ich danke Euch für Eure Hilfe, {name}!", sourceObjective = "Bringt 20 kandierte Süßkartoffeln zu William Mullins an die Festtafel oberhalb von Unterstadt.", progress = "Habt Ihr die kandierten Süßkartoffeln?", completion = "Vielen Dank, {name}. Ich kann der Gastgeberin helfen und brauche Roberta dennoch nicht zu enttäuschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14059] = { id = 14059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder kein Moosbeerenchutney mehr?", description = "Ich wünschte, ich wüsste, warum das Moosbeerenchutney immer so schnell alle ist. Manchmal habe ich das Gefühl, sie verfüttern es heimlich an die Monstrositäten, wenn gerade keiner hinschaut. Würdet Ihr uns helfen, für Nachschub zu sorgen? Wenn Ihr in der Kochkunst bewandert seid, könnt Ihr die benötigten säuerlichen Moosbeeren vom Südstrom vom Händler des Pilgerfreudenfests außerhalb von Orgrimmar bekommen.\n\nSteht Euch nicht der Sinn nach Kochen, könnt Ihr auch jederzeit jemand anderen darum bitten.", sourceObjective = "Bringt 20 Portionen Moosbeerenchutney zu Roberta Carter an die Festtafel in den Innenhof oberhalb von Unterstadt.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Vielen Dank für Eure Hilfe, und gebt mir Bescheid, falls Ihr jemals hinter das Geheimnis des ständig verschwindenden Chutneys kommen solltet!", sourceObjectiveStatus = "unverified-source-field" }
quests[14060] = { id = 14060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuchen versuchen", description = "Dokin und Laha bemühen sich, den Feiernden die Hintergründe des Fests und die Zubereitung der traditionellen Gerichte aus all den frisch geernteten Zutaten nahe zu bringen. Ich versuche, die Tische mit so viel Essen wie nur möglich gefüllt zu halten, aber uns geht langsam der Kürbiskuchen aus.\n\nWürdet Ihr vielleicht welchen für uns besorgen? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr dafür reife Tirisfalkürbisse, die Ihr beim Händler des Pilgerfreudenfests oberhalb von Unterstadt bekommen könnt.", sourceObjective = "Bringt 20 Kürbiskuchen zu Mahara Goldweizen nahe der Festtafel außerhalb von Donnerfels.", progress = "Wie steht es mit dem Kuchen?", completion = "Die sind fantastisch. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14061] = { id = 14061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich krieg einfach nicht genug… Truthahn", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall in Tirisfal selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", sourceObjective = "Bringt 20 langsam geröstete Truthähne zu Ondani Mühlenrad außerhalb von Orgrimmar.", progress = "Wie steht's mit der Truthahnjagd?", completion = "Prächtige Truthähne, genau was ich brauche! Ihr habt mir wirklich aus der Klemme geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14062] = { id = 14062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Füllung ist alles!", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", sourceObjective = "Bringt 20 Portionen Gewürzbrotfüllung zu Ondani Mühlenrad an die Festtafel außerhalb von Orgrimmar.", progress = "Wie sieht es mit der Füllung aus?", completion = "Gerade rechtzeitig! Ich hätte das Festmahl ohne Gewürzbrotfüllung gar nicht auftischen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[14063] = { id = 14063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meuterei, Mann!", description = "Nun zum schönsten Teil einer Meuterei: dem Abmurksen! Piraten interessieren sich nicht so sehr für die Frage, wer das Sagen haben soll, sondern es geht ihnen nur darum, wer das Schiff beherrscht. Im Ostende dieser Insel liegt die 'Dolch der Maid', das alte Flaggschiff von Käpt'n Garvey. Er hat die Aufsicht dem Offizier überlassen, dem er am meisten vertraut: Alicia Cuthbert. Sobald wir sie erledigt haben, gehört das Schiff uns – und damit auch das Meer.\n\nIch gebe meinen Männern den Befehl, in die Boote zu steigen. Ihr müsst an Bord der 'Dolch' gehen und an Deck in dieses Horn tuten. Das wird unser Signal sein, das Schiff zu kapern. Jippieh!", sourceObjective = "Verwendet das Signalhorn der Piraten, um Tony Zweihauer und seine Mannschaft an Bord der 'Dolch der Maid' zu rufen. Helft ihm, Alicia Cuthbert unter Deck zu besiegen.", progress = "Ist das die 'Dolch der Maid', die dort in der Entfernung den Anker lichtet? Habt Ihr etwas damit zu schaffen?", completion = "Schmeißt Tony dort jetzt also den Laden? Gut! Wir brauchen in diesen Gewässern mehr Piraten wie ihn. Er ist ein echter Geschäftsmann.\n\n<Flunkerblick reibt seine Hände gierig aneinander.>\n\nWo wir vom Geschäft reden: ich schätze, ich bin Euch einen Anteil schuldig. Wäret Ihr daran interessiert, einen Teil Eurer Beute zu versichern? Man weiß nie, was in einer Stadt wie dieser geschieht...", sourceObjectiveStatus = "unverified-source-field" }
quests[14064] = { id = 14064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilen an der Festtafel", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, so viel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", sourceObjective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", completion = "Was für ein Festmahl, hm?\n\nEs freut mich, dass Ihr zusammen mit uns die Bedeutung des Pilgerfreudenfests zelebrieren konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14065] = { id = 14065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilen an der Festtafel", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, so viel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", sourceObjective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", completion = "Was für ein Festmahl, hm?\n\nEs freut mich, dass Ihr zusammen mit uns die Bedeutung des Pilgerfreudenfests zelebrieren konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14066] = { id = 14066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Wracks", description = "Vor nicht allzu langer Zeit wurde eine Ladung Silber auf dem Weg von hier zum Wegekreuz gestohlen. Es war als Bezahlung für die Wachen gedacht und wir wollen das Silber zurück haben.\n\nIch habe mich nach Hinweisen umgehört, aber ich will, dass Ihr den Tatort untersucht. Begebt Euch nach Westen und sucht nach einem verunglückten Wagen einer Karawane an der Straße von hier Richtung Norden auf dem Weg zum Wegekreuz. Findet heraus, wer das Silber an sich genommen hat und holt es Euch zurück!", sourceObjective = "Findet den verunglückten Wagen in der Nähe der Straße zwischen Ratschet und dem Wegekreuz, und sucht das Gebiet nach Spuren und Hinweisen ab.", completion = "Dieser Wagen der Horde wurde nicht einfach nur ausgeraubt. Er wurde zerfetzt. Vorratskisten wurden mit scharfen Klauen auseinandergerissen. Der Wagen wurde vollständig zerstört. Die Nahrungsmittel wurden gefressen und das Silber ist weg, und dennoch wurden nützliche Vorräte zurückgelassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14067] = { id = 14067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gestohlene Silber", description = "Offensichtlich haben diese Raptoren alleine gehandelt, als sie das Silber der Horde raubten.\n\nEs wird Zeit, diesen Bestien eine Lektion zu erteilen.", sourceObjective = "Tötet 8 Felshetzer und 4 Sensenklauen der Sonnenschuppen und findet das gestohlene Silber.", progress = "Ihr seht mitgenommen aus, {class}. Habt Ihr Euch mit den Dieben gerangelt?", completion = "<Gazrog öffnet die Schließkassette und zählt das Silber, während Ihr berichtet.>\n\nWas!? Raptoren? Nur die Raptoren? Alleine? Greifen unsere Karawanen an und plündern sie aus? Vielleicht sind sie doch so intelligent, wie die Gerüchte besagen. Als ob wir nicht schon genug Probleme hätten, müssen wir uns jetzt auch noch um diese schlauköpfigen und geldgierigen Echsen kümmern.\n\nHier, {name} – Ihr habt Euch einen Teil des Silbers verdient. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[14068] = { id = 14068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waptorfalle", description = "Waptoren zu fangen, ist ganz schön schwiewig, aber ich habe eine neue Waptorfalle entwickelt, die den Gwoßteil der Wisiken ausschaltet.\n\nStellt die Falle auf dem Boden auf und sie quietscht wie ein Waptor und lockt so einen andewen in die Falle.\n\nWenn ein Waptor in meine Waptorfalle twitt, schwumpft sie ihn zusammen, sodass er nicht mehr so gefährlich ist. Es ist schwecklich einfach! Ich würde es selbst machen, aber ich bin neulich König Schnitterklaue begegnet.", sourceObjective = "Verwendet Kala'mas \"Waptorfalle\", um 5 kleine Waptoren zu fangen.", progress = "Wo sind die kleinen Waptoren?", completion = "Huwwa! Ihr habt die Waptoren gefangen, nach denen ich gesucht habe! Jetzt dwessieren wir sie so, dass Twolle auf ihnen weiten können, um die Allianz zu vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[14069] = { id = 14069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutes Personal ist schwer zu finden", description = "Ich habe versagt! Ich habe alles versucht, um unser Kaja'Cola-Soll zu erreichen, aber Ihr wisst doch, wie das mit den Trollsklaven heutzutage ist. Gutes Personal ist schwer zu finden!\n\nIch glaube, Ihr müsst hier selbst Hand anlegen. Ein kleiner Stromschlag mit der Batterie Eures goblinischen Alles-in-1-zigartigen Gürtels sollte Wunder wirken. Wenn Ihr die Arbeitsmoral von ein paar Trollen da unten anpasst, ziehen die anderen sicher schnell nach.\n\nDie Kaja'Cola-Produktion muss weitergehen, sonst macht uns der Handelsprinz einen Kopf kürzer!", sourceObjective = "Verbessert die Arbeitsmoral von 8 widerspenstigen Trollen.", completion = "Ich hätte es selbst nicht besser machen können. Und das habe ich auch nicht.\n\nIhr seid uns allen eine Inspiration, {name}. Ich bin mir sicher, dass die Großartigkeit, die Macht und, wenn ich hinzufügen darf, der extreme Reichtum des neuen Handelsprinzen {name} bald in aller Munde sein werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14070] = { id = 14070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbst ist der Goblin", description = "Wir müssen gleich mehreren Schuldnern eine Nachricht zukommen lassen. Natürlich versteckt sich dieser Abschaum im Malocherviertel. Ich weiß, wie ungern Ihr in die Slums geht, <Herr/Frau> Boss, aber was soll man schon machen?\n\n<Sassy blättert durch einen Stapel Papiere.>\n\nIch habe alle Namen hier.\n\nDarf ich vielleicht vorschlagen, dass Ihr ihnen einen \"persönlichen Besuch\" abstattet? Ein paar strategisch geplante Schlägereien setzen deutliche Zeichen für die anderen Schuldner UND Eure Konkurrenten.\n\n{name} ist kein Goblin, mit dem man sich anlegen sollte!", sourceObjective = "Verprügelt Bruno Flammhemmer, Frankie Gangschalter, Jack den Hammer und Sudsy Magee.", completion = "Das nenne ich einen absoluten Erfolg, mein Herr! Eure Schuldner werden es sich jetzt sicher zweimal überlegen, bevor sie Euch nicht bezahlen!\n\n<Sassy kaut einen Augenblick gedankenverloren auf ihrem Stift herum.>\n\nVielleicht sollten wir die Verleihzinsen erhöhen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14071] = { id = 14071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruisen", description = "{name}, ich habe gehört, dass Ihr die Mutter aller Firmenpartys ausrichten werdet. Laut meinen Berechnungen sollte Euer Beförderungsquotient raketenhaft in die Höhe schießen und explodieren, wenn man sieht, dass Ihr auf der Party Spaß habt!\n\nDaher schlage ich vor, Ihr unternehmt eine kleine Spritztour mit dem Hot Rod und holt Eure Freunde in der Stadt ab.\n\nVergesst mich nur nicht, wenn alles am Schnürchen läuft und Ihr <der neue Handelsprinz/die neue Handelsprinzessin> werdet, ja?", sourceObjective = "Fahrt mit dem Hot Rod durch die Gegend und holt Eure Freunde Ass, Gobber und Izzy ab.", completion = "Gut gemacht, mein Herr. Der Hot Rod steht Euch wirklich ausgezeichnet. Ihr habt die Bevölkerung sicher schwer beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14072] = { id = 14072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verog aufstöbern", description = "Regthar Totenfurt hat mich hierhergeschickt, um die Aktivitäten der Zentauren zu beobachten, aber der Anführer der Gruppe ist schwer auszumachen. Ich habe herausgefunden, dass er 'Verog der Derwisch' heißt, aber sein Aufenthaltsort bleibt unbekannt.\n\nKönnt Ihr mir ein wenig beim Auskundschaften helfen? Man würde bei den Zentauren eigentlich keine echten 'Geheiminformationen' erwarten, aber häufig befinden sich in ihren Lagern massenhaft wichtige Papiere. Sucht die Zelte der Zentauren um die Brackige Oase ab und bringt mir ein paar Informationen.", sourceObjective = "Sammelt 4 Geheiminformationen der Zentauren aus der Umgebung der Brackigen Oase.", progress = "Durchsucht diese Zelte, {name}. Versucht, den Gestank zu ignorieren.", completion = "Gute Arbeit, {name}! Habt Ihr diese Papiere schon angesehen? Sie sind kaum lesbar und sehen eher wie eine wilde Schmiererei aus als wie Kriegspläne. Hass, Eifersucht, Wut, Zwietracht – es ist ein Wunder, dass Verog diese Zentauren davon abhalten kann, sich gegenseitig zu töten, ganz zu schweigen davon, sie zu einer Armee vereinen.\n\nDas können wir ausnutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14073] = { id = 14073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Totenfurt", description = "{name}! Euer Ruf für die Horde wächst. Mir sind Berichte von den Vergessenen Teichen und der Brackigen Oase zu Ohren gekommen, dass Ihr unseren Zentauren-Feinden großen Schaden zugefügt habt. Gute Arbeit, in der Tat.\n\nRegthar Totenfurt leitet die Einsätze gegen die Zentauren im gesamten Nördlichen Brachland. Er könnte jemanden wie Euch zur Unterstützung seiner Streitkräfte gut gebrauchen. Meldet Euch bei ihm in seinem Vorposten an der Straße in Richtung Westen und lasst ihm jede Hilfe zukommen, die in Eurer Macht steht.", sourceObjective = "Meldet Euch bei Regthar Totenfurt an seinem Vorposten westlich vom Wegekreuz im Nördlichen Brachland.", completion = "Ah, ich habe schon von Eurer Arbeit gehört, {class}. Ihr habt den Zeitpunkt Eures Eintreffens gut gewählt. Ich arbeite derzeit an einer Großoffensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[14074] = { id = 14074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt mal ein Bein zu", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", sourceObjective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Narasi Schneedämmerung auf dem Argentumturnierplatz.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden glücklich sein, dass etwas von der Ladung gerettet werden konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14075] = { id = 14075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in den Minen", description = "Wir haben schon wieder Ärger in der Kaja'mine, Boss. Die Tunnelwürmer sind zurück und fressen wortwörtlich den gesamten Profit der Handelsgesellschaft von Kajaro auf!\n\nWir können kein Kaja'mit abbauen, was die Produktion von Kaja'Cola schwer beeinträchtigt!\n\nIch habe schon versucht, den Kammerjäger zu rufen, aber er hat sich mit unserer letzten Zahlung aus dem Staub gemacht.\n\nMeint Ihr, Ihr könntet selbst in die drei Minen gehen und Euch darum kümmern? Ich würde Euch ja helfen, aber ich habe noch nicht am vom Kartell vorgeschriebenen Nahkampftraining teilgenommen.", sourceObjective = "Tötet 6 Tunnelwürmer.", completion = "Auf Nimmerwiedersehen, Ungeziefer!", sourceObjectiveStatus = "unverified-source-field" }
quests[14076] = { id = 14076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühstück der Champions", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Scheucht die Tiefenjormungar auf, tötet sie und sammelt ihre Eiersäcke ein.", sourceObjective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", progress = "Habt Ihr die Eier besorgen können? Diese Würmer werden anfangen, ihre Tierführer zu fressen, wenn sie nicht schon bald gefüttert werden.", completion = "Gut gemacht, {name}. Ich werde diese hier umgehend zu den Tierführern des Argentumkreuzzugs bringen. Sie werden keine andere Wahl haben und anerkennen müssen, dass wir um einiges mehr leisten als die Sonnenhäscher, wenn es darum geht, für den reibungslosen Ablauf im Kolosseum zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14077] = { id = 14077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barmherzigkeit des Lichts", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Es genügt nicht, einfach nur an der Seite der Kreuzfahrer zu kämpfen, wir müssen uns ihre Mission zu Eigen machen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", sourceObjective = "Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "<Narasi nimmt das Gebetbuch von Euch entgegen.>\n\nIch danke Euch. Dieses Buch war ein Geschenk der Beichtpatin Blondlocke selbst. Sie wäre sicher hocherfreut, dass Ihr es eingesetzt habt, um das Leid der erschlagenen Seelen zu lindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[14078] = { id = 14078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeriegelt!", description = "Was tut Ihr noch hier, <Bürger/Bürgerin>? Habt Ihr nicht gehört? Über die Stadt wurde eine vollständige Ausgangssperre verhängt.\n\nSprecht mit Leutnant Walden und befolgt seine Evakuierungsanweisungen.", sourceObjective = "Findet Leutnant Walden am nordwestlichen Ende des Händlerplatzes.", completion = "Die Leiche des Mannes ist von tiefen Klauenspuren gezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14079] = { id = 14079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen im Wald von Elwynn", description = "Dieser Handzettel bewirbt das bei Randal Weidmann erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nRandal Weidmann befindet sich im Holzfällerlager des Osttals im Wald von Elwynn, von Sturmwind aus östlich die Straße entlang.", sourceObjective = "Bringt diesen Handzettel zu Randal Weidmann beim Holzfällerlager des Osttals im Wald von Elwynn.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14080] = { id = 14080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhalt den Aggressoren", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", sourceObjective = "Narasi Schneedämmerung auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", completion = "Eure Taten haben bewiesen, dass wir Schulter an Schulter mit dem Argentumkreuzzug stehen, während die Sonnenhäscher zu viel Zeit mit Herumstolzieren verschwenden, um noch zu den Waffen greifen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[14081] = { id = 14081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen im Immersangwald", description = "Dieser Handzettel bewirbt das bei Perascamin erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nPerascamin befindet sich bei Thurons Aufzucht, südöstlich des Hirtentors außerhalb von Silbermond.", sourceObjective = "Bringt diesen Handzettel zu Perascamin bei Turons Aufzucht in Silbermond.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14082] = { id = 14082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in der Exodar", description = "Dieser Handzettel bewirbt das bei Aalun erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nAalun befindet sich am Eingang zur Exodar auf der Azurmythosinsel.", sourceObjective = "Bringt diesen Handzettel zu Aalun außerhalb der Exodar auf der Azurmythosinsel.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14083] = { id = 14083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Dun Morogh", description = "Dieser Handzettel bewirbt das bei Ultham Eisenhorn erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nUltham Eisenhorn befindet sich im Gehöft Bernruh in Dun Morogh, von Eisenschmiede aus östlich die Straße entlang.", sourceObjective = "Bringt diesen Handzettel zu Ultham Eisenhorn beim Gehöft Bernruh in Dun Morogh.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14084] = { id = 14084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Dun Morogh", description = "Dieser Handzettel bewirbt das bei Binjy Federpfiff erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nBinjy Federpfiff befindet sich bei Stahlrosts Depot, direkt nordöstlich von Kharanos in Dun Morogh.", sourceObjective = "Bringt diesen Handzettel zu Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14085] = { id = 14085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Darnassus", description = "Dieser Handzettel bewirbt das bei Jartsam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nJartsam befindet sich in der Enklave des Cenarius in Darnassus.", sourceObjective = "Bringt diesen Handzettel zu Jartsam bei der Enklave des Cenarius in Darnassus.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14086] = { id = 14086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Orgrimmar", description = "Dieser Handzettel bewirbt das bei Kildar erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKildar befindet sich im Tal der Ehre in Orgrimmar.", sourceObjective = "Bringt diesen Handzettel zu Kildar im Tal der Ehre in Orgrimmar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14087] = { id = 14087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Mulgore", description = "Dieser Handzettel bewirbt das bei Kar Sturmsang erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKar Sturmsang befindet sich im Dorf der Bluthufe in Mulgore.", sourceObjective = "Bringt diesen Handzettel zu Kar Sturmsang beim Dorf der Bluthufe in Mulgore.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14088] = { id = 14088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Durotar", description = "Dieser Handzettel bewirbt das bei Xar'Ti erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nXar'Ti befindet sich in Sen'jin in Durotar.", sourceObjective = "Bringt diesen Handzettel zu Xar'Ti in Sen'jin im südlichen Durotar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14089] = { id = 14089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Tirisfal", description = "Dieser Handzettel bewirbt das bei Velma Warnam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nVelma Warnam befindet sich in Brill in Tirisfal.", sourceObjective = "Bringt diesen Handzettel zu Velma Warnam in Brill in Tirisfal.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14090] = { id = 14090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok will seine Schneebolde", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", sourceObjective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte den Sonnenhäschern die Aufsicht über diese Kreatur gegeben. Sie sind sich so ähnlich, dass sie sich eigentlich verstehen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14091] = { id = 14091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da stimmt was nicht", description = "Der Leutnant scheint seinen schweren Wunden erlegen zu sein. Der Prinz wird die Neuigkeiten bestimmt hören wollen.\n\nIhr hört Kampfgeräusche, die aus der Richtung des Marktes kommen.", sourceObjective = "Kehrt zu Prinz Liam Graumähne auf dem Händlerplatz zurück.", completion = "Ihr seid es wieder. Sieht aus, als ob Ihr niemand wärt, der im Angesicht der Gefahr den Schwanz einziehen würde. Nun dann.", sourceObjectiveStatus = "unverified-source-field" }
quests[14092] = { id = 14092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühstück der Champions", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Ihr Ton wird die Tiefenjormungar aufscheuchen. Tötet sie, sammelt ihre Eiersäcke ein und bringt sie zurück zum Turnierplatz.", sourceObjective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", progress = "Habt Ihr die Eier besorgen können? Die Jormungar werden unausstehlich, wenn man sie nicht füttert.", completion = "Ich werde die Kreuzfahrer wissen lassen, dass Ihr gerade eine Ladung frisches Futter zurückgebracht habt, während der Silberbund faul herumsitzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14093] = { id = 14093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hölle bricht los", description = "Worgen! Mein Vater hat mich gewarnt, dass die Schöpfungen des Erzmagiers Arugal irgendwann Amok laufen würden.\n\nAber woher kommen sie?\n\nVermutlich macht es keinen Unterschied. Helft uns, kurzen Prozess mit ihnen zu machen. Wir werden ihnen zeigen, aus welchem Holz die Bewohner von Gilneas geschnitzt sind.", sourceObjective = "Prinz Liam Graumähne wünscht, dass Ihr 6 tobende Worgen tötet.", progress = "Habt Ihr Euch um die {race} gekümmert?", completion = "Es hat keinen Zweck, {name}! Sie lassen nicht nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[14094] = { id = 14094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Vorräte", description = "Hört zu, {name}. Wir können nicht zulassen, dass unser Proviant zerstört wird.\n\nDa Gilneas von der Außenwelt abgeschottet ist, werden wir den Winter nicht überleben, wenn wir noch mehr von unseren Vorräten verlieren.\n\nBitte helft mir dabei, zu retten, was zu retten ist.", sourceObjective = "Bergt 4 Vorratskisten.", progress = "Habt Ihr die Vorräte geborgen, {name}?", completion = "Hervorragend! Ich werde sicherstellen, dass sie an einen sicheren Ort gebracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14095] = { id = 14095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste identifizieren", description = "Ein ganzer Zahn eines toten Kraken ist in der Tat ein seltener Fund. Kreuzfahrer Silberdämmerung wird das sehen wollen.", sourceObjective = "Bringt den Krakenzahn zum Beweis Eures Sieges zu Kreuzfahrer Silberdämmerung.", progress = "Was habt Ihr gefunden, Champion?", completion = "Ich wusste, dass die Krake jemandem wie Euch nicht gewachsen sein würde. Nun, da die Boote nicht mehr von ihr belästigt werden, bleibt den Kvaldir keine andere Wahl, als sich zurückzuziehen. Gute Arbeit, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[14096] = { id = 14096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nOhne Verstärkung wurden Kul und seine Gefolgschaft schnell gefangen genommen. Ich habe keine Zweifel, dass der Kult die Gefangenen opfern wird - es sei denn, wir können einen Rettungseinsatz in Gang bringen. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", sourceObjective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", completion = "Dank Euch haben Kul und die Streiter überlebt, um weiterhin die Geißel zu bekämpfen. Das ist bei Weitem nicht das erste Mal, dass jemand Kul vor sich selbst retten musste. Ich hoffe nur, dass die Kreuzfahrer ein besseres Ventil für seinen Enthusiasmus finden, als ihm weiter zu gestatten, seine schlechten Angewohnheiten an junge und noch beeindruckbare Streiter weiterzugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14098] = { id = 14098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuiert den Händlerplatz", description = "Die Zivilisten sind hier nicht mehr sicher. Nicht mal mehr in ihren Häusern.\n\nWir tun, was wir können, um die Worgen davon abzuhalten, in die Häuser zu gelangen, aber es sind einfach zu viele.\n\nHelft uns dabei, die Häuser der Zivilisten zu evakuieren. Die Armee meines Vaters im Gefängnisviertel wird sie besser schützen können.", sourceObjective = "Evakuiert 3 Zivilistenhäuser.", completion = "Gute Arbeit, {name}. Dank Euch werden viele Bürger Gilneas' den morgigen Tag erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14099] = { id = 14099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königlicher Befehl", description = "Es ist Zeit für Euch, uns zu verlassen, {name}. Geht mit den anderen Zivilisten ins Militärviertel.\n\nMeldet Euch bei Gwen Armstead, wenn Ihr die Brücke im Südosten überquert ... seht nach, ob es allen gut geht.\n\nIch werde mit den Wachen hierbleiben und den Rückzug der Zivilisten decken.\n\nGeht nun. Das ist ein Befehl!", sourceObjective = "Sprecht mit Gwen Armstead im Militärviertel im Südosten.", completion = "Es geht uns allen gut. Wir sind ein wenig mitgenommen, aber ... wir leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14100] = { id = 14100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Irdenen Rings", description = "Ihr seid weit in Eurem Training vorangekommen, {name}. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Gotura Vierwind im Tal der Weisheit in Orgrimmar und feilt an Eurer Beherrschung der Elemente.", sourceObjective = "Bringt Eure vier Totems nach Orgrimmar zu Gotura Vierwind.", progress = "Hmmm, was verleitet Euch, die Hilfe des Irdenen Rings zu suchen?", completion = "Ah, Ihr beherrscht nun die vier Totems. Ihr solltet stolz auf das sein, was Ihr bisher erreicht habt, junger {race}, aber das ist lediglich der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nFührt Euer Training weiter. Diese Welt hat noch Schlimmes vor sich - ich kann es im Wind hören und fühle es im Rumpeln der Erde. Wir müssen auf das Schlimmste vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14101] = { id = 14101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drottinn Hrothgar", description = "Die Kvaldir, seefahrende Vrykul, die Schiffe und Küstensiedlungen überfallen, haben eine Tuskarrinsel auf der anderen Seite der Meerenge gen Norden überrannt. Ihr Anführer ist ein altgedienter Plünderer namens Drottinn Hrothgar, der die Kontrolle über diesen Teil der See erlangen möchte.\n\nMit ihm an der Macht werden unsere Lieferungen und Truppentransporte niemals sicher sein. Wir werden hier gestrandet und dem Lichkönig auf Gedeih und Verderb ausgeliefert sein.\n\nHier, bringt dieses erbeutete Kriegshorn der Kvaldir zum Tuskarrstatuenkreis im nordöstlichen Teil von Hrothgars Landestelle und verwendet es, um den Anführer der Kvaldir herauszufordern.", sourceObjective = "Hochmeister Adelard auf dem Argentumturniergelände möchte, dass Ihr Drottinn Hrothgar besiegt.", completion = "Die Niederlage von Drottinn Hrothgar wird die Kvaldir gegeneinander aufhetzen, was uns genug Zeit verschafft, unseren Vorteil zu nutzen. Der Kreuzzug und das Turnier stehen in unserer Schuld, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[14102] = { id = 14102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelrufer Yngvar", description = "Die Kvaldir sind zur Küste von Nordend zurückgekehrt und wenn sich niemand um sie kümmert, werden sie verhindern, dass Vorräte und Verstärkung hier ankommen. Einer von ihnen, bekannt als Nebelrufer Yngvar, hat sich in einer Höhle auf der Westseite von Hrothgars Landestelle eingenistet. Von dort aus beeinflusst er den Nebel, um die Kvaldir und deren Meeresbestien zu verbergen.\n\nHier, nehmt diesen Glücksbringer und überquert die Meerenge nördlich des Turnierplatzes in Richtung Hrothgars Landestelle. Findet die Höhle des Nebelrufers und bringt ihn mithilfe des Glücksbringers zum Vorschein.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Nebelrufer Yngvar tötet.", completion = "Ihr habt uns kostbare Zeit verschafft, um gegen die Kvaldir vorzurücken und das Meer von diesen Quälgeistern zu befreien. Der Argentumkreuzzug steht einmal mehr in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[14103] = { id = 14103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanstaub", progress = "Hallo, {name}! Habt Ihr was zum Handeln?", completion = "Wunderbar! Noch eine Ladung Pulver!\n\nUnter uns Juwelenschleifern, ich habe bei den Magiern von Dalaran ein Riesengeschäft mit Schmuck aus \"reinem Titanium\" gemacht. Selbst mit ihrem überragenden Verstand sind sie nicht schlau genug, was Ihr Gold angeht. Ich bin hier, falls Ihr noch mehr bekommen solltet." }
quests[14104] = { id = 14104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ornolf der Vernarbte", description = "Ornolf der Vernarbte gilt als angsteinflößender Plünderer und ist unter seinen Kvaldirbrüdern bekannt dafür, Schiffe zu plündern und zu kapern. Vom Schiff Bors Zorn aus greifen seine Mannschaft und er unsere Schiffe an und stehlen unsere Ladung.\n\nOrnolf und seine Männer gehören zu denjenigen, die Mord an den Einwohnern einer Tuskarrinsel begangen haben und diese in Hrothgars Landestelle umbenannten. Sein Schiff liegt am östlichen Ende des Hafens der Insel vor Anker. Nehmt diesen erbeuteten Banner an Euch und stellt ihn auf diesem Schiff auf, um ihn zu provozieren und in den Kampf mit Euch zu locken.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Ornolf den Vernarbten tötet.", completion = "Ornolfs Mannschaft wird Ihren Anführer rächen wollen, aber ohne ihn werden sie einfacher zu besiegen sein. Wir haben unser Leben der Aufgabe geweiht, die Eiskrone von der Geißel und anderem Bösen zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[14105] = { id = 14105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todessprecher Kharos", description = "Der Kult der Verdammten hat seine Anstrengungen verdoppelt, um unsere Vernichtung herbeizuführen. Sie sind mutig geworden und sammeln in Todessprechers Wacht auf dem Gebirgskamm westlich des Turnierplatzes ihre Kräfte.\n\nDer erbarmungslose Todessprecher Kharos hat seinen Männern befohlen, ihre Stellungen zu befestigen, um sich darauf vorzubereiten, alle Waffen des Kults einzusetzen.\n\nMeine Männer bereiten sich und die Recken darauf vor, den Platz zu verteidigen - ich möchte jedoch, dass Champions wie Ihr, {name}, unsere Streitkräfte anführen, um den Angriff abzuschwächen. Findet Todessprecher Kharos und tötet ihn.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Todessprecher Kharos tötet.", completion = "Wahrhaftig, Ihr seid ein Beispiel für alle, die sich unter unserem Banner versammelt haben, {name}. Gemeinsam werden wir der Geißel zeigen, dass wir nicht in die Knie gezwungen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14106] = { id = 14106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na Kada's Questtest" }
quests[14107] = { id = 14107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Gefallenen", description = "Der Argentumkreuzzug ist wohl kaum die erste Streitmacht, die den Lichkönig herausfordert. Unser Feind hetzt die Geister der Gefallenen gegen uns auf.\n\nSie streifen im Tal der Gefallenen Helden südwestlich des Platzes zwischen Aldur'thar und dem Eisenwallbollwerk umher. Die Gegend ist mit weggeworfenen Seelenkristallen, mit denen die Geißel die Geister kontrolliert, übersät. Sammelt diese Seelenkristalle und verwendet sie gemeinsam mit diesem lichtgesegneten Relikt, um den Geistern den Segen des Friedens zu verleihen. Sie haben ihre Ruhe mehr als verdient.", sourceObjective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr dafür sorgt, dass 6 Geister der gefallenen Helden Frieden finden.", completion = "Ihr habt unseren gefallenen Brüdern einen großen Dienst erwiesen und es uns erspart, ihnen erneut auf dem Schlachtfeld begegnen zu müssen. Mit dem Voranschreiten der Kampagne gegen die Geißel ertappe ich mich dabei, über mein eigenes Schicksal nachzusinnen.\n\nSollte ich fallen, {name}, würde ich wollen, dass Ihr dasselbe für mich tätet wie an diesem heutigen Tage für die Geister der Gefallenen. Ich könnte den Gedanken nicht ertragen, meinen eigenen Bruder dazu zu zwingen, mich immer wieder zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14108] = { id = 14108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraken am Haken", description = "Die Sonnenhäscher und der Silberbund haben Schiffe nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle anzugreifen, jedoch wurden sie von einem Seeräuberschiff der Kvaldir abgefangen und anschließend gefangen genommen. Was die Sache noch schlimmer macht, ist, dass die Kvaldir einen Weg gefunden haben, den gefürchteten Kraken aus den Tiefen des Nordmeeres hervorzurufen. Wenn irgendjemand an Bord da lebend herauskommen soll, muss der Kraken weggejagt und das Beschwörungsritual der Kvaldir... unterbrochen werden.\n\nHier <Kreuzfahrer/Kreuzfahrerin>, nehmt diese Speere. Ein Argentumhippogryph wird Euch in die Schlacht tragen.", sourceObjective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr auf einen Argentumhippogryph steigt, 8 flammende Speere auf den Nordmeerkraken werft und 6 Tiefenrufer der Kvaldir ausschaltet.\n\nIhr findet die Argentumhippogryphen gleich außerhalb des Zelts auf dem Argentumturnierplatz.", progress = "Habt Ihr den Kraken schon verjagt? Beeilt Euch, Kreuzfahrer! Es bleibt nicht viel Zeit.", completion = "Kreuzfahrer, Ihr habt den Seemännern womöglich gerade genug Zeit verschafft, um ihre Flucht zu ermöglichen. Vielleicht werden die Leute vom Silberbund und die Sonnenhäscher das nächste Mal hinhören, bevor sie sich Hals über Kopf auf den Feind stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14109] = { id = 14109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz neues Ihr", description = "Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.\n\nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!", sourceObjective = "Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.", progress = "Hast du alles beisammen, {name}? Ich kann es kaum erwarten, die neuen Sachen an dir zu sehen.\n\nDu hast doch keinen Ramsch gekauft, oder?", completion = "Oh, du wirst so toll aussehen! Allerdings nicht so toll wie ich. Bei deinem Tempo wirst du den Handelsprinzen im Handumdrehen vom Thron stoßen!\n\nIch kann es kaum abwarten, endlich nicht mehr arbeiten zu müssen! Du kaufst mir doch alles, was ich will, oder, Liebling?\n\nLass mich dir die ganzen Sachen abnehmen. Kurz bevor die Party losgeht werde ich dir beim Styling helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14110] = { id = 14110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz neues Ihr", description = "Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.\n\nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!", sourceObjective = "Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.", progress = "Hast du alles beisammen, {name}? Ich kann es kaum erwarten, die neuen Sachen an dir zu sehen.\n\nMmm hmm!", completion = "Oh, du wirst so scharf aussehen! Bei deinem Tempo wirst du den Handelsprinzen im Handumdrehen vom Thron stoßen!\n\nIch kann es kaum abwarten, endlich ein gemachter Mann zu sein!\n\nLass mich dir die ganzen Sachen abnehmen. Kurz bevor die Party losgeht, werde ich dir beim Styling helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14111] = { id = 14111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Irdenen Rings", description = "Ihr seid weit in Eurem Training vorangekommen, {name}. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Weitseher Eannu in der Nähe der Großen Schmiede in Eisenschmiede. Er wird Euch dabei helfen, Eure Beherrschung der Elemente zu verfeinern.", sourceObjective = "Bringt Eure vier Totems nach Eisenschmiede zu Weitseher Eannu.", progress = "In Euch regen sich die Geister. Was bringt Euch dazu, die Hilfe des Irdenen Rings zu suchen?", completion = "Wie ich sehe, beherrscht Ihr nun den Gebrauch der vier Totems. Ihr seid auf dem Weg, eins mit den elementaren Geistern zu werden - aber dies ist erst der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nEuer Training muss weitergehen! Ich spüre, dass diese Welt sehr viele Prüfungen erwarten, und wir werden die Macht der Elemente hinter uns wissen müssen, wenn wir die Oberhand gewinnen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14112] = { id = 14112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was fressen eigentlich Yetis?", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, der Bestie überschüssige Sonnenhäscher zum Fressen zu geben. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zur Silberklinge hinunterfliegt, die in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", sourceObjective = "Savinia Lehrensang auf dem Argentumturnierplatz möchte, dass Ihr ihr 3 Stück Fleisch eines Nordmeerhais bringt.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Sonnenhäscher in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht von den Sonnenhäschern behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14113] = { id = 14113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mittelpunkt der Party", description = "Oh, meine Güte, Baby! Alle sind gekommen! Wen interessiert da schon irgendein blöder Drache?\n\nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Du wirst so toll aussehen!\n\nWarum gehst Du nicht schon einmal rüber zum Pool und unterhältst die Leute? Ich bin in einer Minute bei Dir... Ich will nur kurz in etwas Aufregenderes schlüpfen.", sourceObjective = "Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.", completion = "Sehr gut, mein Herr. Die Party war anscheinend ein voller Erfolg!\n\nÄh… was ist das denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[14115] = { id = 14115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Piraten", description = "Oh je! Piraten!\n\n{name}, da sind ungeladene Südmeerpiraten auf Eurer Party!\n\nIhr müsst sofort etwas dagegen unternehmen oder Eure Karriere und jede Hoffnung, <der nächste Handelsprinz/die nächste Handelsprinzessin> zu werden, sind dahin.", sourceObjective = "Tötet 12 ungeladene Piraten, um Eure Karriere zu retten.", completion = "Puh, das war knapp, Boss. Und leider habe ich noch mehr schlechte Nachrichten.\n\nBitte, erschießt mich nicht…", sourceObjectiveStatus = "unverified-source-field" }
quests[14116] = { id = 14116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ungeladene Gast", description = "Während Ihr Euch um die Piraten gekümmert habt, habe ich bemerkt, wie der Handelsprinz sich nach oben geschlichen hat. Er ist auf dem Balkon oben an der Treppe.\n\n{name}, ich glaube, er hat die Piraten geschickt.\n\n<Sassy erschaudert.>\n\nIhr solltet lieber so schnell wie möglich nach oben gehen. Lasst ihn nicht warten!", sourceObjective = "Sprecht mit Handelsprinz Gallywix oben im Hauptgebäude des Hauptgeschäftssitzes der HGK auf Kezan.", completion = "So, so, so, wenn das nicht mein abtrünniger Schützling Herr {name} ist.\n\nIch bin tief verletzt und enttäuscht. Ihr habt mich nicht zu Eurer kleinen Party da draußen eingeladen. Tut mir leid wegen der ungebetenen Gäste… Ihr wisst ja, wie Piraten sein können.\n\nAlso, kommen wir zum Geschäft?", sourceObjectiveStatus = "unverified-source-field" }
quests[14117] = { id = 14117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Eschental", description = "Unsere Feinde sind in der Überzahl, {class}, sogar direkt hier an unserer Türschwelle. Die Nachtelfen haben die Talrendisspitze verstärkt, weil sie unser Vordringen im Eschental unterbinden wollten. In diesem Augenblick patrouillieren ihre Späher in den nahegelegenen Hügeln und berichten über jedes Ein- und Ausgehen an diesen Toren.\n\nWir müssen Eschental diese Augen herausreißen.\n\nGeht. Eure Beute schleicht um diese Tore herum, insbesondere im Osten. Vernichtet die Späher, die uns beschatten!", sourceObjective = "Tötet 8 Späher der Talendrisspitze.", completion = "Ausgezeichnet. Wenn ihre Späher ihnen nicht länger berichten, wird die Talendrisspitze selbst die Furcht zu spüren bekommen, die sie uns einflößen wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14118] = { id = 14118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildbret für die Truppen", description = "Während wir die Ressourcen dieses Landes für unsere Kriegsmaschinerie aufbrauchen, berauben wir die einheimischen Tiere ihrer Heimat. Wenn sie ohnehin sterben müssen, sollte ihr Fleisch aber dennoch nicht verschwendet werden. Nicht wenn die Schlünde von Orgrimmar weit geöffnet und hungrig sind.\n\nTötet die geschwächten Mooshufhirsche, die sich noch in diesem Gebiet aufhalten, und bringt ihr Fleisch unseren Peons und Grunzern mit.", sourceObjective = "Sammelt 15 Scheiben Wildbret von geschwächten Mooshufhirschen.", progress = "Ihr riecht nach frisch getötetem Wild, {class}.", completion = "Wild – und zwar reichlich! Gute Arbeit. Das wird unsere Mägen füllen, während wir unser Arsenal bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14120] = { id = 14120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bazillion Moneten?!", description = "Ihr seid ein sehr ehrgeiziger junger Goblin, {name}. Vielleicht ein wenig ehrgeiziger, als es für Euch gut wäre. Ich erkenne mich selbst in Euch, als ich noch jung war.\n\nIch habe einen Vorschlag. Vielleicht ist Euch ja schon aufgefallen, dass der Kajaro explodiert. Alle auf Kezan werden sterben!\n\nAber, wenn Ihr mir eine Bazillion Moneten bringt, bevor meine Yacht die Insel verlässt, werde ich dafür sorgen, dass Ihr unter den wenigen Glücklichen seid, die entkommen.\n\nWenn Ihr also leben wollt, solltet Ihr Euch lieber schnell überlegen, wo Ihr so viel Knete für mich auftreibt!", sourceObjective = "Sprecht mit Sassy Hartzang im Hauptgeschäftssitz der HGK auf Kezan.", completion = "Eine Bazillion Moneten?!? Wo sollen wir denn so viel Knete her bekommen?\n\n<Sassy überlegt einen Augenblick.>\n\nÄh… hat der Handelsprinz erwähnt, ob ich mit Euch zusammen auf seiner Yacht fliehen darf?", sourceObjectiveStatus = "unverified-source-field" }
quests[14121] = { id = 14121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündert die Plünderer", description = "Wir werden alle sterben!!!\n\n<Ihr gebt Megs eine Ohrfeige, damit sie sich beruhigt.>\n\nTut mir leid, <Herr/Frau> {name}! Es wird nicht mehr vorkommen. Wir müssen einen Weg finden, ganz schnell ganz viel Knete zu scheffeln.\n\nEs gibt bereits Berichte, dass der Handelsprinz angeheuerte Plünderer auf die Straßen des Bilgepiers geschickt hat.\n\nNehmt den Hot Rod, fahrt sie über den Haufen und nehmt Euch die Beute, die sie sich unrechtmäßig angeeignet haben. Daran wäre doch nichts Falsches, oder?\n\nSchließlich ist es für eine gute Sache!", sourceObjective = "Benutzt den Hot Rod, um 12 angeheuerte Plünderer umzufahren, und sammelt dabei 12 Einheiten gestohlene Beute.", progress = "Konntet Ihr etwas von der gestohlenen Beute zurückstehlen?", completion = "Ihr habt es wirklich geschafft?! Na, ich schätze, das haben sie verdient.\n\nDas ist aber ganz schön viel Beute. Meint Ihr, es reicht, um Euch einen Platz auf der Yacht des Handelsprinzen zu erkaufen?\n\nKönnt Ihr jemanden mitnehmen? Ich habe im Marketing gerade nicht allzu viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[14122] = { id = 14122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Banküberfall", description = "All Eure Besitztümer wurden eingefroren und die Erste Bank von Kezan hat geschlossen!\n\nIhr braucht wirklich einen Haufen Knete, Boss. Ich fürchte, Ihr müsst Euer eigenes Geld aus der Bank rauben! Mit den verschiedenen Apparaten in Eurem goblinischen Alles-in-1-zigartigen Gürtel solltet Ihr alles dabei haben, was Ihr braucht, um den Tresor zu knacken.\n\nIch hoffe nur, dass Ihr etwas für schlechte Zeiten gespart habt, wie ich es Euch immer geraten habe. Und falls Ihr es noch nicht gemerkt haben solltet: Die Zeiten sind gerade hundsmiserabel!", sourceObjective = "Knackt den Tresor der Ersten Bank von Kezan, um an Eure privaten Reichtümer zu gelangen.", progress = "Habt Ihr sie? Habt Ihr den Tresor geknackt und Eure privaten Reichtümer aus der Bank geholt?", completion = "He, Ihr habt ja gespart! Ich bin so stolz auf Euch!\n\n<Sassy zählt all Eure Moneten.>\n\nÄh, Boss… Das reicht nicht einmal ansatzweise.", sourceObjectiveStatus = "unverified-source-field" }
quests[14123] = { id = 14123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach hereinspaziert", description = "Ich habe von unseren Geldproblemen gehört. Es gibt nur einen Weg, wie wir eine Bazillion Moneten zusammenkriegen können: Wir stehlen es von den Reichen!\n\nDieser Schleimer, der Handelsprinz, hat alle möglichen Antiquitäten und wertvolle Kunstgegenstände gestohlen. Es ist an der Zeit, es ihm zu nehmen und den Bedürftigen zu geben... natürlich vor allem uns!\n\nHobart hat eine Kappe zurückgelassen, an der er gearbeitet hat - eine Verkleidung, mit der Ihr genauso ausseht, wie einer von Gallywix' Schergen. Ihr müsst einfach nur in seine Villa spazieren und diese Gegenstände \"sicherstellen\".\n\nPasst aber auf seine Schweine auf. Sie werden Euren Geruch hinter der Verkleidung erkennen!", sourceObjective = "Beschafft Euch Maltes Falken, die Mona Goblisa und die ultimative Bombe.", progress = "Habt Ihr die Waren, Boss?", completion = "Oh, toll! Dieser Kram ist ein Vermögen wert!\n\n<Slinky prüft alles mit geschulten, gierigen Augen.>\n\nIch hoffe nur, dass der Handelsprinz die Sachen nicht bemerkt, wenn Ihr sie ihm mit dem Rest Eures Reichtums übergebt…", sourceObjectiveStatus = "unverified-source-field" }
quests[14124] = { id = 14124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappt Euch das Kaja'mit", description = "<Mein Herr/Meine Dame>, wir brauchen einen Haufen Knete, um den Handelsprinzen zu bezahlen und von Kezan weg zu kommen! Und dieser Haufen liegt genau da unten und wartet darauf, mitgenommen zu werden.\n\nDies sind die letzten bekannten Kaja'mitvorkommen. Das ist der Rohstoff, der uns zu den genialen Tüftlern und Alchemisten gemacht hat, die wir heute sind. Wenn das keine Bazillion Moneten wert ist, dann weiß ich auch nicht!\n\nNehmt ein paar meiner Kabummbomben und jagt die Vorkommen in die Luft. Sammelt danach die Kaja'mitbrocken auf.\n\nAber gebt auf die rebellischen Trolle Acht!", sourceObjective = "Sammelt 12 Kaja'mitbrocken.", progress = "Wie viel Kaja'mit habt Ihr?", completion = "Gute Arbeit, mein Herr, wirklich gute Arbeit! Da habt Ihr ein echtes Vermögen in Euren Taschen.\n\nDamit lässt uns der Handelsprinz sicher auf seine Yacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[14125] = { id = 14125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versicherungsbetrug", description = "Wir kommen der Sache näher, aber wir haben immer noch nicht genug Moneten. Zu Eurem Glück, Boss, habe ich das vorausgesehen und einen Plan entwickelt. Wir werden die Versicherung des Hauptquartiers einstreichen!\n\nIch habe mir die Freiheit genommen, das übriggebliebene Feuerwerk von Eurer Party an diesem Ort zu verteilen. Alles, was Ihr tun müsst, ist dorthin zu gehen und ein wenig Sabotage zu betreiben.\n\nDarf ich vielleicht den defekten Generator, den undichten Ofen und das leicht entzündliche Bett vorschlagen? Danach geht Ihr wieder nach draußen und schickt einen Gasbot hinein.\n\nEin narrensicherer Plan!", sourceObjective = "Überlastet den defekten Generator, macht den undichten Ofen an und lasst eine Zigarre auf das leicht entzündliche Bett fallen. Benutzt dann den Gasbot, um den Hauptgeschäftssitz der HGK in Brand zu setzen!", completion = "Das ist noch gar nichts. Ihr solltet den Bilgepier mal sehen… Dort steht alles in Flammen!\n\nGut, gut, ich habe keine Zeit, den Ort unter die Lupe zu nehmen. Hier ist die Knete aus der Versicherung des Bilgewasserkartells.\n\nIch muss einen Weg von der Insel herunter finden. Viel Glück, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14126] = { id = 14126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensersparnisse", description = "Wir haben die ganze Knete zusammen. Jetzt müssen wir nur noch eines tun, Boss: Euch zur Yacht des Handelsprinzen schaffen. Sie legt bald ab!\n\nWir müssen uns beeilen. Springt rein! Ich fahre!", sourceObjective = "Übergebt Handelsprinz Gallywix auf Gallywix' Yacht auf Kezan Eure Lebensersparnisse.", progress = "Oh, {name}, Ihr seid es. Welch unerwartete Überraschung.", completion = "Glückwunsch, Ihr habt es gerade noch geschafft. Wie ich sehe, habt Ihr mir alles gebracht, worum ich Euch gebeten habe, sogar den Hot Rod.\n\n<Ein bösartiges Grinsen huscht über das Gesicht des Handelsprinzen.>\n\nEine Bazillion Moneten war sicher nicht leicht zu beschaffen. Jetzt bin ich der reichste und mächtigste {race} in ganz Azeroth.\n\nZU DUMM, DASS ICH DIE BEDINGUNGEN UNSERER VEREINBARUNG JETZT ÄNDERE!\n\nIhr seid ab sofort mein Sklave. Geht unter Deck und leistet Euren Beitrag beim Kohleschaufeln. Nächster Halt: Azshara!\n\nMuhahahahahahaha!", sourceObjectiveStatus = "unverified-source-field" }
quests[14127] = { id = 14127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr der Hochgeborenen?", description = "Das Wachssiegel auf diesen Befehlen wurde erst vom Kurzen aufgebrochen. Ihr könnt die sorgfältig ausgeführte Elfenschrift nicht lesen, aber eine kleine handgemalte Karte deutet auf die nahegelegenen Ruinen. Unter der Karte stehen in einer gänzlich anderen Schrift eine Reihe von Runen in einer metallisch schimmernden Tinte.\n\nAg'tor wird diese wichtige Geheiminformation zweifelsohne sehen wollen.", sourceObjective = "Bringt die Befehle des Spähers zu Ag'tor Blutfaust am Hinteren Tor von Orgrimmar.", progress = "Ihr habt bei einer der Leichen etwas gefunden, sagt Ihr? Gebt es mir!", completion = "<Ag'tor hält das Pergament gegen das Licht und begutachtet es.>\n\nNein, ich kann dies ebenfalls nicht entziffern, aber was ich sehe, gefällt mir nicht. Sind das arkane Runen?\n\nIhr müsst dies einem Experten vorlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14128] = { id = 14128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr der Hochgeborenen?", description = "Unsere Verbündeten, die Blutelfen, haben die Runen auf dieser Karte untersucht und sie können die rätselhafte Schrift vermutlich entziffern. Sucht nach Malynea Himmelshäscher. Sie leitet ihre Untersuchungen vom Umschlagplatz der Raketenbahn von Orgrimmar nördlich von hier. Es ist ein Teil des neuen Transitsystems der Goblins, das sich durch dieses Land zieht. Rasch, jetzt!", sourceObjective = "Bringt die Befehle des Spähers zu Malynea Himmelshäscher am Umschlagplatz der Raketenbahn von Orgrimmar.", progress = "Ich nehme an, bei dieser Unterbrechung handelt es sich um etwas Wichtiges?", completion = "Was? Her damit, sofort! Ag'tor hat Recht. Das sind arkane Runen. Sie erkunden magische Stätten? Experimentieren mit arkanen Künsten? Das ist ein erstaunlicher Bruch mit Jahrtausende alten Traditionen der Nachtelfen.\n\nHmph! Die Vorstellung, dass sie in diesem Bereich irgendwelche Fähigkeiten erlangen, ist absurd. Sogar für diejenigen, die sich selbst einst zu den Hochgeborenen zählten.\n\n<Malynea wirft die Schriftrolle verächtlich beiseite, aber auf ihrer Stirn bilden sich Sorgenfalten.>", sourceObjectiveStatus = "unverified-source-field" }
quests[14129] = { id = 14129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredder außer Rand und Band", description = "Ich habe versucht, unsere neuen Verbündeten der Horde mit der legendären Effizienz der Goblins zu beindrucken, aber im Nachhinein war die Automatisierung der Schredder eine schlechte Idee. Jetzt sind es Tötungsmaschinen, die wahllos durch unsere Ländereien pflügen. Versteht mich nicht falsch, diese Geräte haben ihren Sinn und Zweck, aber jetzt käme <ein mutiger/eine mutige:c> {class} gerade recht, <der/die:c> mir hilft, diese Dinger unter Kontrolle zu bekommen.\n\nEs ist ganz einfach. Automatisierte Schredder müssen, wie alle Maschinen, geprügelt werden, bis sie sich unterwerfen. Danach übernehmt Ihr die Steuerung und ich funke Euch weitere Anweisungen zu.", sourceObjective = "Greift einen der entlaufenen Schredder in der Nähe der Tore von Orgrimmar an. Dann setzt Euch hinein, nachdem Ihr ihm erheblichen Schaden zugefügt habt.", completion = "<Arbeitsaufseher Grabbits Stimme knistert über das Funkgerät.>\n\nHallo, {name}! Hört Ihr mich?\n\nEs ist kinderleicht, die Teufelskiste zu fahren. Für die Pedalsteuerung tretet die Pedale und, ähm, bewegt die Hebel für die Hebelsteuerung. Verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[14130] = { id = 14130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundschaft kennt keine Farbe", description = "Mein Bruder und ich werden gejagt.\n\nUnser Vatertier wurde kürzlich getötet und der schwarze Drachenschwarm hetzt diejenigen von uns, die noch am Leben sind. Ich bin hier, weil ich Azuregos finden und in Sicherheit bringen will, aber er macht es mir nicht leicht.\n\nAzuregos hat nicht viele Freunde und sein diesbezüglicher Geschmack ist ein wenig... ungewöhnlich. Der Einzige, den ich hier in der Gegend kenne, ist ein Murloc mit Namen Ergll. Ihr solltet ihn an der Küste nordöstlich von hier finden.\n\nTut, was immer vonnöten ist, um Azuregos zu finden, und schickt ihn zu mir.\n\nBitte beeilt Euch.", sourceObjective = "Findet Ergll an der Küste der Ruinen von Arkkoran.", completion = "Heda! Ein neuer Freund! Bin sehr erfreut, Euch kennenzulernen. Mein Name ist Ergll. Das 'g' wird nicht gesprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14131] = { id = 14131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bohnensammler", description = "Azuregos... Azuregos... Azi? Der Großdrache? Wir sind Freunde, zweifellos! Er brachte mir das Sprechen bei. Er sagte, er mag meinen Farbton... ein Freund von Farben, oder?\n\nKann mich nicht erinnern, wo er hingegangen ist. Hmm... Vielleicht habt Ihr etwas, das meinem Gedächtnis auf die Sprünge hilft?\n\nIch ziehe hier am Strand Kahpheepflanzen. Sie mögen Sand. Ziemlich verrückt.\n\nKönntet Ihr mir ein paar ernten?", sourceObjective = "Pflückt 10 Kahpheebohnen von den Pflanzen in den Ruinen von Arkkoran.", progress = "Bin müde, so schwer sich zu konzentrieren.", completion = "Schöne Bohnen! Sie riechen absolut köstlich, oder etwa nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[14132] = { id = 14132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was für eine Frechheit!", description = "Ich würde sie mit ihnen teilen, wenn sie fragen würden. Sie fallen einfach über meine Kahpheepflanzen her. Das ist nicht nett! Ihr könntet ihnen eine Lektion erteilen.\n\nDiese blöden Makrinnis.", sourceObjective = "Tötet 10 Makrinnis in den Ruinen von Arkkoran.", completion = "Zu gemein? Nein, nicht zu gemein. Sie haben es verdient.\n\nIch zerstöre ihre Pflanzen doch auch nicht. Hab ich noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[14134] = { id = 14134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz vor der Hütte", description = "Jetzt, wo Ihr das Ding unter Kontrolle habt, sammeln wir das Holz ein, das ich mitbringen sollte. Sonst bauen diese Orcs das nächste Katapult aus MIR!\n\nFrisches Holz sollte bereits aufgestapelt in der Gegend sein. Verwendet den Schredder und sammelt so viel auf, wie Ihr könnt.", sourceObjective = "Verwendet den umprogrammierten Schredder, um 6 Haufen azsharisches Holz zu sammeln. Falls Ihr Euren Schredder verliert, kann ein weiterer angegriffen und umprogrammiert werden.", progress = "Wie läuft die Holzverarbeitung? Ihr solltet sehen, was diese Dinger mit Broccoli anstellen!", completion = "Fantastisch! Ihr habt den Schredder voll beladen. Ihr habt das Ding schon ziemlich gut unter Kontrolle...", sourceObjectiveStatus = "unverified-source-field" }
quests[14135] = { id = 14135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Baum", description = "Haltet kurz still, ich mache die Steuerung für die Hauptmotorsäge betriebsbereit.\n\nHeckenschützen der Nachtelfen von der Talrendisspitze verstecken sich in den Bäumen und greifen meine Arbeiter an. Ich will, dass Ihr diese Heckenschützen erledigt... indem Ihr Euch zunächst um diese Bäume kümmert. Sucht nach azsharischen Schösslingen östlich des Haupttores. Euer Schredder wird wissen, was zu tun ist. Schreddert los!", sourceObjective = "Verwendet die Motorsäge des Schredders, um die azsharischen Schösslinge niederzumähen, und tötet 9 Heckenschützen von der Talrendisspitze, sobald sie auftauchen.", completion = "Gute Arbeit, {name}! So haben wir solche Angelegenheiten damals in Kezan geregelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14136] = { id = 14136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungseinsatz auf See", description = "Die Kvaldir haben auf Hrothgars Landestelle, der kleinen Insel im Norden, ihr Lager aufgeschlagen. Wir haben Kapitän Aerthas Feuerfalke in die Gegend geschickt, aber er und seine Mannschaft sind auf eine Seeräuberbande der Kvaldir gestoßen, die in Richtung Turnierplatz unterwegs war! Nun wird die Feuerfalke von den Seeräubern angegriffen und ihre Mannschaft ist weit in der Unterzahl. Geht dort hinaus und zeigt diesen Kvaldir, weshalb es keine gute Idee ist, die Sonnenhäscher anzugreifen.\n\nDie Feuerfalke befindet sich zwischen Hrothgars Landestelle im Norden und dem Turnierplatz, auf der westlichen Seite der Straße der Meerhäscher.", sourceObjective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 8 Berserker der Kvaldir und 3 Harpunierer der Kvaldir an Bord der Feuerfalke tötet.", completion = "Gute Arbeit, Champion. Der Kampf geht weiter, aber nun wissen die Kvaldir, dass wir solche Angriffe nicht dulden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14138] = { id = 14138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst ist Dienst und Cola ist Cola", description = "Wir haben so viele Probleme unten in der Kaja'mine, dass Vorarbeiter Feuchtlunte bald schon Purzelbäume schlägt, so verzweifelt wie er nach Euch sucht. Er murmelte etwas von 'widerspenstigen Trollen'.\n\nDas Kaja'mit, das unsere Trolle abbauen, ist ein wesentlicher Bestandteil unserer Kaja'Cola. Dieses blubberige Zeug bringt uns ein Vermögen und Euch sicher die Beförderung <zum Handelsprinzen/zur Handelsprinzessin> ein!\n\nAber zunächst muss die Produktion wieder ins Rollen kommen. Ihr findet den Vorarbeiter im Osten. Hier, gebt ihm das als Motivation, damit er sich wieder zusammenreißt.", sourceObjective = "Bringt Sassys Motivation zu Vorarbeiter Feuchtlunte im Hauptgeschäftssitz der HGK auf Kezan.", progress = "Äh… alles läuft super. Ja.\n\nWas ist das?", completion = "Ein Geschenk von Sassy? Ich hoffe, es ist ein Bonus!", sourceObjectiveStatus = "unverified-source-field" }
quests[14140] = { id = 14140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhalt den Aggressoren", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", sourceObjective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", completion = "Eure Taten haben bewiesen, dass wir Sonnenhäscher dem Argentumkreuzzug um einiges bessere Verbündete sind als der Silberbund, und dass wir es sein werden, die am Ende triumphieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[14141] = { id = 14141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok will seine Schneebolde", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", sourceObjective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte dem Silberbund die Aufsicht über diese Kreatur gegeben. Die werden sich die Hände schmutzig machen müssen, wenn die Schlacht um die Zitadelle beginnt, und ich habe das Gefühl, dass sie sich als schwache und zimperliche Verbündete erweisen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14142] = { id = 14142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nSie wurden mit Leichtigkeit gefangen genommen und nun schmachtet Kul in einem Käfig auf der Plattform im Lager. Ich bin mir sicher, dass der Kult die Gefangenen opfern wird - es sei denn, wir können sie retten. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", sourceObjective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", completion = "Kul wird weiterleben und sich wieder lächerlich machen. Und es ist keinesfalls das erste Mal, dass jemand Kul vor sich selbst retten musste. Es sind solche Beispiele, bei denen es einen nicht wundert, dass die meisten Streiter die Gewohnheiten des Silberbunds annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14143] = { id = 14143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt mal ein Bein zu", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", sourceObjective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Girana der Blutgezeichneten auf dem Argentumturnierplatz.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden es gerne hören, dass wir ein wenig Erfolg hatten. Vielleicht können wir die leicht vergammelten Stücke dem Silberbund geben. Das würde mir den Tag versüßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14144] = { id = 14144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barmherzigkeit des Lichts", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Zwar kämpfen wir Seite an Seite mit den Kreuzfahrern, aber wir könnten auch von ihnen lernen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", sourceObjective = "Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "<Girana nimmt das Gebetbuch von Euch entgegen.>\n\nIch danke Euch. Wir sind vielleicht nicht immer einer Meinung mit den Kreuzfahrern, aber ich habe in meiner Zeit hier viel von Beichtpatin Blondlocke gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14145] = { id = 14145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was fressen eigentlich Yetis?", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, ein paar Mitglieder des Silberbunds an die Bestie zu verfüttern. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zum Schiff \"Scharlachroter Morgen\" hinunterfliegt, das in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", sourceObjective = "Tylos Dämmerflucht auf dem Argentumturnierplatz möchte, dass Ihr ihm 3 Stück Fleisch eines Nordmeerhais bringt.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Mitglieder des Silberbunds in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht vom Silberbund behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14146] = { id = 14146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt die Tore!", description = "Du meine Güte – was ist hier los?\n\n<Schreie, Rufe und Schlachtgetöse dröhnen über Funk.>\n\n{name}! Kommt sofort hierher zurück. Eilt zurück zu den Toren. Wir werden angegriffen!\n\nHelft uns, die Eindringlinge abzuwehren. Ich lade Euren Granatenwerfer!!", sourceObjective = "Arbeitsaufseher Grabbit will, dass Ihr zurück zum Hinteren Tor von Orgrimmar eilt und dort 20 Räuber der Nachtelfen tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14151] = { id = 14151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kardinalsrubin", description = "Man sagt, dass der Kardinalsrubin der feinste Edelstein in ganz Nordend ist. Er funkelt wie eine Kristallrose in der Sonne.\n\nBevor ich Euch die Herstellung beibringe, bitte ich Euch, fünf Transmutationen epischer Edelsteine durchzuführen, um auf diese Weise Euren Geist vorzubereiten. Welche Transmutationen Ihr wählt, das liegt bei Euch. Ihr könnt auch mehrmals dieselbe durchführen.\n\nKehrt zu mir zurück, wenn Ihr wirklich bereit seid.", sourceObjective = "Linzy Schwarzbolz in Dalaran möchte, dass Ihr 5 erfolgreiche Transmutationen epischer Edelsteine mithilfe Eurer Alchemiefertigkeit durchführt. Für die Transmutation akzeptable Edelsteine sind Ametrine, Augen von Zul, Schreckenssteine, Königsbernsteine und Fürstenzirkone.", completion = "Sehr gut, {name}.\n\nDer Trick bei der Sache ist nun, die Ausrichtung der Facetten gerade richtig hinzubekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14152] = { id = 14152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungseinsatz auf See", description = "Champion, Kapitänin Schaumkrone und ihr Schiff wurden nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle zu behelligen, als sie von einer Seeräuberbande der Kvaldir abgefangen wurden, die in Richtung Turnierplatz unterwegs war! Unglücklicherweise sind die Kvaldir der Mannschaft an Bord zahlenmäßig um einiges überlegen und gerade dabei, das Schiff zu übernehmen.\n\nIhr müsst Euch auf nach Norden zur Schaumkrone machen, die sich in der Straße der Meerhäscher zwischen dem Turnierplatz und Hrothgars Landestelle befindet, und der Mannschaft helfen, den Angriff abzuwehren. Das Schiff sollte sich auf der Ostseite der Meeresenge befinden.", sourceObjective = "Begebt Euch in Richtung des Nordmeers und tötet unter den Angreifern der Schaumkrone 8 Berserker der Vrykul und 3 Harpunierer der Vrykul.", completion = "Es scheint, als wären die Dinge schlimmer, wie anfangs gedacht. Ihr habt noch immer Tapferkeit gezeigt und dabei viele Besatzungsmitglieder der Schaumkrone gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14153] = { id = 14153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mittelpunkt der Party", description = "Oh, wow, Baby! Alle sind gekommen! Wen interessiert da schon so ein blöder Drache?\n\nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Ihr werdet so toll aussehen!\n\nWarum geht Ihr nicht schon einmal rüber zum Pool und unterhaltet die Leute? Ich bin in einer Minute bei Euch... Ich muss nur noch meine Sachen holen.", sourceObjective = "Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.", completion = "Sehr gut, meine Dame. Die Party war anscheinend ein voller Erfolg!\n\nÄh… was ist das denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[14154] = { id = 14154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit knapper Not", description = "Eine dieser räudigen Flohschleudern hat Dempsey ordentlich erwischt. Wir können ihn nicht fortbringen, bevor seine Blutungen nicht gestoppt sind.\n\nMacht Euch nützlich und haltet diese Bastarde zurück. Ein paar Minuten reichen uns schon, <Bruder/Schwester>!", sourceObjective = "Haltet die Worgen im oberen Bereich des Stadtgefängnisses von Gilneas 2 Minuten lang auf.", progress = "Wir haben's gleich! Vorsichtig, oder wir verlieren ihn!", completion = "Wir haben's geschafft, {name}. Dank Euch hat ein guter Mann überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14155] = { id = 14155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arborzid", description = "Wie steht es um den Schredder? Ich glaube, ich kann Eure Notfallenergievorräte einsatzbereit machen. Das wird Euch wiederaufladen, wenn Ihr beschädigt seid.\n\nHört gut zu. Diese Nachtelfen werden von einem Urtum des Krieges unterstützt, das sich westlich des Tores verwurzelt hat. Es ist ein gigantischer Baumriese. Ihr wisst, was zu tun ist! Legt ihn um!\n\nDafür seid Ihr wie geschaffen!!", sourceObjective = "Verwendet den Schredder, um das Urtum von der Talrendisspitze zu vernichten. Notfallersatzschredder stehen am Hinteren Tor von Orgrimmar zur Verfügung, wenn Ihr Euren verliert.", completion = "Ihr habt es geschafft, {name}! Die Eindringlinge haben sich zurückgezogen. Sie haben mir gesagt, ich sei verrückt, dass ich einen Granatenwerfer auf einem Schredder montiere...\n\nIhr habt mit dem Gerät gute Arbeit geleistet. Mit einer derartig beeindruckenden Darbietung direkt vor der Haustür des Kriegshäuptlings wird die Horde nicht mehr an den Möglichkeiten der Goblintechnologie zweifeln. Ich bin Euch zu großem Dank verpflichtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[14157] = { id = 14157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Differenzen", description = "Lord Darius Crowley ist schon viele Dinge genannt worden. Rebell. Verräter. Terrorist.\n\nVor dem Bürgerkrieg nannte ich ihn einen ... Freund.\n\nIch habe ihn nie dafür verurteilt, einen Aufstand gegen mich angeführt zu haben. Sein Land und seine Bevölkerung waren durch eine zehn Meter hohe Mauer von Gilneas abgeschnitten ... Aber wir hatten keine Wahl.\n\nWie auch immer ... Crowley ist genau die Person, die wir jetzt brauchen.\n\nBetretet das Steinwallgefängnis und fragt Hauptmann Broderick, wo Crowley zu finden ist. Ich würde ja meine eigenen Männer schicken, aber es existiert immer noch böses Blut zwischen uns.", sourceObjective = "Sprecht mit Hauptmann Broderick im Steinwallgefängnis in Gilneas.", completion = "Graumähne will Crowley retten? Hat er den Verstand verloren?", sourceObjectiveStatus = "unverified-source-field" }
quests[14159] = { id = 14159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Arsenal des Rebellenlords", description = "Das Arsenal, von dem Crowley spricht, befindet sich in einem Keller westlich von hier.\n\nEs gefällt mir zwar nicht, dass meine Gegner Artillerie in die Stadt geschmuggelt haben, aber sie könnte dabei helfen, gilnearische Leben zu retten.\n\nFindet Josiah Avery und requiriert die Rebellenartillerie. Wir müssen diese Waffen sinnvoll einsetzen.", sourceObjective = "Sprecht mit Josiah Avery im Militärdistrikt in Gilneas.", completion = "Seht mich nicht an! Lasst mich in Ruhe!", sourceObjectiveStatus = "unverified-source-field" }
quests[14160] = { id = 14160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leistungsurkunde", description = "Auf diesem feinen Pergament befindet sich eine Liste mit einer großen Anzahl an Leistungen, die {name} in der Tradition der Juwelierskunst errungen hat.\n\nBringt diese Urkunde zu Jonas Timotheus nach Dalaran zurück, um eine angemessene Belohnung zu erhalten.", sourceObjective = "Liefert die Leistungsurkunde bei Jonas Timotheus in Dalaran ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[14161] = { id = 14161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisken klatschen", description = "Wir haben diesen ganzen Berg abgetragen, um die Mineralien aus der Mine darunter abzubauen. Aber wir haben nicht bedacht, dass die Basilisken, die dort unterirdisch hausten, nun, also, oberirdisch hausen. Ihr seht so unternehmungslustig aus. Geht dorthin und tötet ein paar dieser Plagegeister und ich greife für Euch einmal tief in unsere Geldvorräte.", sourceObjective = "Tötet 10 Grausteinbasilisken im Tagebau am Gebirgsfuß.", completion = "Gut, gut. Eine Sorge weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[14162] = { id = 14162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Horzak", description = "Ihr habt wirklich gute Arbeit geleistet, als Ihr unsere Holzfällerei zum Laufen gebracht habt. Aber ich habe gehört, dass wir langsam zu wenig Stein haben. Man sollte meinen, wenn wir Berge versetzen können, könnten wir dabei auch ein paar Steine aufsammeln...\n\nNun, das ist nicht mein Problem, aber vielleicht könnt Ihr es zu Eurem machen. Meldet Euch bei Horzak Zignibbel oben am Umschlagplatz der Raketenbahn von Orgrimmar. Findet heraus, ob Ihr ihm dabei helfen könnt, diese Operation in den Griff zu bekommen. Folgt der Straße Richtung Nordosten und Ihr findet ihn im Turm der Raketenbahn.", sourceObjective = "Findet Horzak Zignibbel am Umschlagplatz der Raketenbahn von Orgrimmar in Azshara.", completion = "Seid Ihr hier, um zu helfen? Ausgezeichnet! Hier, unterzeichnet diesen Abfindungsverzicht. Und hier die Wettbewerbsklausel. Fangen wir an!", sourceObjectiveStatus = "unverified-source-field" }
quests[14163] = { id = 14163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen: Insel der Eroberung", description = "Da wir dem Sieg in Eiskrone immer näher kommen, ist es deutlicher geworden, dass sich unsere Armeen mit der Horde auseinandersetzen müssen, bevor sie sich um den Lichkönig kümmern können.\n\nSie haben die Elitewache bekannt als die Kor'kron eingesetzt, um unseren Vormarsch auf der Insel der Eroberung aufzuhalten. Die Insel ist von äußerst wichtiger strategischer Bedeutung, {name}. Seht zu, dass unsere Jungs gewinnen!", sourceObjective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Brigadegeneral der Allianz in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", completion = "Die Horde wird es mit unseren Streitkräften nie aufnehmen können, so lange wir Leute wie Euch auf unserer Seite haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14164] = { id = 14164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen: Insel der Eroberung", description = "Der Sieg in Nordend wird bald unser sein... doch nicht bevor wir in Eiskrone Fuß gefasst haben, um für den Transport und die Versorgung unserer Truppen zu sorgen.\n\nDie Insel der Eroberung ist ein idealer Ort. Sie ist einfach zu verteidigen und reich an Ressourcen. Die Allianz ist zu demselben Schluss gelangt und hat die 7. Legion ausgesandt, um unseren Streitkräften die Kontrolle zu entreißen.\n\nGeht, {name}, und sorgt dafür, dass die Horde um jeden Preis die Oberhand gewinnt!", sourceObjective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Kriegshetzer der Horde in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", completion = "Nichts wird sich zwischen uns und den endgültigen Sieg stellen. Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[14165] = { id = 14165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalt wie Stein", description = "Die Arbeiter tun fast so, als bestünde Ihre Hauptaufgabe darin, sich zu beschweren. Wenn es nicht die harte Knochenarbeit, die Überstunden oder die geringe Bezahlung sind, ist es die Tatsache, dass sie von den Basilisken in Stein verwandelt werden. Irgendwas ist immer!\n\nAber ich glaube inzwischen, dass dieses ganze Arbeiter-in-Stein-Verwandeln ein echtes Geschäft für mich werden könnte. Was ist, wenn diese Leute jetzt hochwertiges Gestein sind? Meine jammernden Beschäftigten könnten für mich als Luxusbaumaterial mehr wert sein als als Arbeiter! Schnappt Euch einen versteinerten Bergfußminenarbeiter und schleppt ihn zu mir.", sourceObjective = "Holt einen versteinerten Bergfußminenarbeiter aus dem Tagebau am Gebirgsfuß und bringt ihn zurück zu Horzak Zignibbel am Umschlagplatz der Raketenbahn von Orgrimmar.", completion = "Gut, gut, nun sehen wir uns mal an, was wir hier haben...\n\n<Horzak untersucht die zerschmetterten Überreste des armen versteinerten Minenarbeiters.>\n\nPah! Bröckelig! Unbrauchbar. Der gäbe nicht einmal eine gute Arbeitsplatte ab. Meine Bergarbeiter sind vielleicht mittelmäßige Arbeiter, aber sie geben lausige Steine ab.\n\n<Seufz.> Nun, ich nehme an, wir sollten diesen Arbeiter wieder verfleischlichen, sodass ich einen Teil meiner Investition zurückbekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[14166] = { id = 14166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Geist aus Dalaran auf dem Friedhof von Dalaran.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", progress = "Ihr habt keine Totenspeise, oder?", completion = "Oh, noch mehr köstliche Totenspeise, vielen Dank!\n\nHier, bitte, nehmt dies als Gegenleistung... eine kleine amüsante Aufmerksamkeit für die Feiertage.", sourceObjectiveStatus = "unverified-source-field" }
quests[14167] = { id = 14167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Zwergengeist auf dem Friedhof von Eisenschmiede.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
