quests[14176] = { id = 14176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Taurengeist auf dem Friedhof von Donnerfels.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14177] = { id = 14177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Trollgeist auf dem Friedhof von Orgrimmar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14178] = { id = 14178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Die Realität eines Kampfes an mehreren Fronten ist, dass wir unsere Streitkräfte nicht zu dünn verteilen dürfen, sonst riskieren wir nämlich alles zu verlieren!\n\nVon Tag zu Tag sind äußerst wichtige Truppeneinsätze vonnöten. Heute sind es unsere Streitkräfte in der Schlacht im Arathibecken, die umgehend Verstärkung benötigen.\n\nBringt mir die Siegesnachricht, {name}. Wir können dem Abschaum der Horde nicht erlauben, jene Ressourcen zu sichern, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14179] = { id = 14179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Der Kampf gegen die Horde kennt keine Grenzen, {name}. Selbst in der Scherbenwelt reichen territoriale Zwistigkeiten und alte Feindschaften aus, um das Gleichgewicht zu stören und Krieg hervorzurufen.\n\nBegebt Euch ins Auge des Sturms und stellt sicher, dass die Allianz in der Scherbenwelt die Oberhand gewinnt, genauso wie sie es in Azeroth getan hat.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Wir sind dem endgültigen Sieg über die Horde wieder einen Schritt näher gekommen. Niemals dürfen wir zulassen, dass der Feind sich einen Brückenkopf in dieser oder in irgendeiner anderen Welt sichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[14180] = { id = 14180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwache der Silberschwingen kämpfen in der Kriegshymnenschlucht zum Schutze des Waldes. Wir unterstützen sie nicht deswegen, weil wir eine Liebe für Bäume haben, sondern weil der Wald dem Territorium der Allianz als natürliche Schutzbarriere dient.\n\nIhre Not ist heute größer als je zuvor. Wir müssen umgehend Verstärkung einsetzen, wenn wir nicht dabei zusehen wollen, wie das Eschental an das Brachland angegliedert wird!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Hervorragende Arbeit, {name}. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14181] = { id = 14181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", progress = "Ihr seid schon zurück? Bringt Ihr Siegesnachrichten?", completion = "Ihr habt der Horde heute ehrenvoll gedient, {name}. Der heutige Sieg sichert uns tausend weitere Siege!", sourceObjectiveStatus = "unverified-source-field" }
quests[14182] = { id = 14182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Wir werden den Feind bekämpfen und vernichten, wo auch immer wir ihn finden. Azeroth, die Scherbenwelt - der Ort spielt keine Rolle.\n\nWir können der Allianz nicht erlauben, im Auge des Sturms die Übermacht zu gewinnen. Tragt noch heute die Schlacht zu ihnen... Morgen könnte es schon zu spät sein!", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Ihr ehrt uns alle, {name}. Wir müssen dem Feind zeigen, dass wir ihn immer und überall bekämpfen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[14183] = { id = 14183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Feind, {name}. Sie behaupten, die Wälder des Eschentals zu verteidigen, um ihre Aggressionsakte gegen unsere Territorien im Brachland zu rechtfertigen.\n\nHeute haben wir die Möglichkeit, den Feind ein für alle Mal von unserem Land zu verjagen. Geht in die Kriegshymnenschlucht und holt zurück, was rechtmäßig uns gehört!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Die Horde steht in Eurer Schuld, {name}. Euer Mut und Einsatz während der Verteidigung unseres Landes macht uns alle stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[14184] = { id = 14184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Zeit ist um", description = "<Furien winkt Euch mit einer schwachen Geste zu sich heran. Er hat Schwierigkeiten, zu sprechen.>\n\nLeichtsinnig... Ich wurde von der Allianz niedergeschossen...\n\nIhr müsst... meiner Schwester Bescheid geben.\n\nNehmt mein Reittier, {race}... Es bringt Euch zu ihr...\n\n<Furien stirbt.>", sourceObjective = "Furien in Tethris Aran will, dass Ihr auf seinem Drachenfalken zu Furiens Posten reitet und seine Schwester Cerelia über seinen Tod unterrichtet.", completion = "Was!?\n\nFurien!! Mein Bruder lebt nicht mehr?\n\nSie werden dafür bezahlen! Allesamt!", sourceObjectiveStatus = "unverified-source-field" }
quests[14188] = { id = 14188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rächt Furien!", description = "Das darf nicht sein!\n\nMein geliebter Bruder – vernichtet vom Abschaum der Allianz!\n\nSie sollen Leiden, {race}! Findet eine Möglichkeit, ihnen Schmerzen zu bereiten! Ich werde nicht ruhen, bis das erledigt ist...\n\nFurien hat vor seinem Tod uralte Artefakte in den östlichen Regionen untersucht. Sprecht mit Sorrem. Vielleicht kann er Euch die Spuren meines Bruders weisen.", sourceObjective = "Cerelia will, dass Ihr mit Sorrem in Furions Posten sprecht.", completion = "Furiens Dahinscheiden ist... bedauerlich.\n\nIch werde alles tun, was ich kann, um Euch bei dabei zu helfen, seinen Tod zu rächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14189] = { id = 14189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung", description = "Es stimmt, dass Furien seine letzten Tage einem besonderen Forschungsprojekt gewidmet hat. Worum es dabei genau ging, wollte er mir nicht sagen.\n\nGlücklicherweise war ich in der Lage, sein Tagebuch in meinen Besitz zu bringen, aber es ist in einem Code geschrieben, den ich nicht entschlüsseln kann.\n\nVielleicht gibt es einen Dekodierungsschlüssel für seine Übersetzung in der Region im Osten, wo er viel Zeit verbracht hat.\n\nNehmt das Tagebuch, {class}, und sprecht mit Narimar, wenn Ihr bereit seid, dieses Geheimnis zu untersuchen.", sourceObjective = "Sorrem will, dass Ihr die uralten Schrifttafeln findet.\n\nSprecht mit Narimar in Furions Posten, um dorthin zu reiten, wo Furien seine Nachforschungen betrieben hat.\n\nBereitgestellter Gegenstand:", completion = "Beim Vergleich der Buchstaben der uralten Schrifttafel mit denen in Furiens Tagebuch fällt auf, dass es deutliche Entsprechungen gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14190] = { id = 14190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Prisma", description = "Es muss eine Möglichkeit geben, die Versteinerung durch die Basilisken wieder rückgängig zu machen. Diese lästigen Saboteure der Nachtelfen, die schon länger um meine Mine schleichen, müssen etwas wissen, was uns entgeht. Sie scheinen gegen den Blick der Bestien immun zu sein!\n\nIch will, dass Ihr ihr Geheimnis herausfindet, {name}. Greift Euch ein paar der Saboteure der Talrendisspitze, die im hinteren Teil des Tagebaus herumschleichen, und holt Euch eine Probe des Zaubers oder Schnickschnacks oder was auch immer ihnen ihre Immunität verleiht. Funkt mich vom Hauptgebäude der Schmiede aus an, sobald Ihr Erfolg hattet.", sourceObjective = "Gelangt in den Besitz eines Kristallanhängers von einem Saboteur der Talrendisspitze im Tagebau am Gebirgsfuß.", progress = "<Skurrile Goblinlautsprecher rauschen und knacksen.>", completion = "<Zignibbles Stimme quäkt über die Lautsprecher.>\n\n{name}, seid Ihr das? Seid Ihr noch am Leben? Ihr vergeudet doch nicht meine Sprengstoffvorräte, oder?\n\nHmmm... Ihr sagt, ihr hättet einen Kristallanhänger gefunden. Das ergibt Sinn. Ein perfektes Prisma würde den Blick des Basilisken brechen. Vielleicht können wir das zu unserem Vorteil ausnutzen. Zeit für ein wenig Wissenschaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[14191] = { id = 14191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Furiens Spuren", description = "Ihr könnt die Einzelteile des Textes entschlüsseln, aber es wird ausführlicher Studien bedürfen, bevor Furiens Arbeit einen Sinn ergeben wird.\n\nJetzt seht Ihr in den Nordosten und glaubt, dass Ihr ein paar Ruinen ausmachen könnt, die in dem Tagebuch abgebildet sind.\n\nSofern Ihr das beurteilen könnt, scheinen diese Ruinen für Furiens Forschungen eine Rolle gespielt zu haben.", sourceObjective = "Die uralten Schrifttafeln am Schrein von Elune haben Euch den Weg zu dreien der markanten Ruinen in Sargeron gewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14192] = { id = 14192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausche Linse gegen Prisma", description = "Wenn Euer Prisma darauf eingestellt ist, den Blick des Basilisken zu brechen, können wir die Eigenschaften des Kristalls dazu verwenden, den Verwandlungsprozess umzukehren. Alles was wir brauchen, ist eine Energiequelle.\n\nIn der Waffenkiste zu Eurer Rechten findet Ihr den Prototyp eines Laser-Bergbaubohrers. Ich liebe das Teil, aber es wurden fast täglich Leute damit zerstückelt. Das fing irgendwann an zu nerven. Schnappt Euch den Laserbohrer und tauscht seine Linse gegen Euren Kristall aus...", sourceObjective = "Bringt den Kristallanhänger zur Waffenkiste im Hauptquartier des Tagebaus am Gebirgsfuß.", progress = "<Der Waffenschrank ist vollgestopft mit grässlichen und kaputten Experimentalgeräten. An einigen von ihnen hängen noch Gliedmaßen von Goblins. Ihr entdeckt den Laserbohrer, der liebevoll in einen samtgefütterten Holzkasten gebettet wurde.>", completion = "<Ihr löst das Linsenelement und lasst den Kristall an seinen Platz rutschen. Die Waffe summt unheilvoll.>", sourceObjectiveStatus = "unverified-source-field" }
quests[14193] = { id = 14193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts, was ein paar Melonen nicht richten können", description = "Die Markierungen auf den Ruinen hier machen eine Sache deutlich: Mit dem uralten Brunnen im Heiligtum von Elune scheint es etwas Besonderes auf sich zu haben.\n\nEs scheint, dass er demjenigen besondere Kräfte verleiht, der sein Gesicht in seinem Wasser wäscht. Als erstes muss es im uralten Brunnen natürlich etwas geben, mit dem man sich waschen kann.\n\nWährend Ihr über dieses Problem nachdenkt, bemerkt Ihr eine Melone an den Wurzeln eines Baumes...", sourceObjective = "Sammelt 8 Melonenfrüchte", sourceObjectiveStatus = "unverified-source-field" }
quests[14194] = { id = 14194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverfleischlichung", description = "<Das nahegelegene Funkgerät ruft Euch etwas zu.>\n\nHey {name}, habt Ihr den Laser? Gut! Schaut niemals direkt hinein.\n\nZielt mit dem Schätzchen auf meine versteinerten Arbeiter und das gebrochene Licht sollte den Versteinerungsprozess umkehren. Oder er schmilzt sie. Auch egal. Sorgt dafür, dass meine Arbeiter mir wieder Profit bringen! Und falls der Wiederverfleischlichungsprozess dafür sorgt, dass sie irre werden, solltet Ihr sie töten. Wegen der Versicherung. Horzak ENDE!", sourceObjective = "Verwendet den Wiederverfleischlicher, um acht Bergfußminenarbeiter im Tagebau am Gebirgsfuß wieder zu entsteinern.", progress = "Na sieh mal einer an. Alle Eure Gliedmaßen sind in Ordnung.", completion = "Ah, gut. Jetzt können sich diese Faulpelze wieder an die Arbeit machen. Ihr habt Euch einen Teil des Gewinns verdient – abzüglich der üblichen Gebühren für die Gesellschaft. Wählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[14195] = { id = 14195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schleier lichtet sich", description = "Irgendetwas ist anders... Vielleicht eine Nebenwirkung von Elunes Reinigungsrituals.\n\nWährend Ihr noch weit davon entfernt seid, die uralte Sprache perfekt zu verstehen, haben sich Eure Kenntnisse jedoch deutlich verbessert.\n\nFuriens Enthusiasmus scheint sich vor allem auf die Ruinen in den nördlichen Bergen von Sargeron zu beziehen. Er hatte das Gefühl, dort sei irgendetwas, das ihm helfen würde, die Allianz aus dieser Region zu vertreiben.\n\nIhr klappt das Tagebuch zu und seid fest entschlossen, diese Ruinen zu finden und ihnen ihre Geheimnisse zu entlocken.", sourceObjective = "Furiens Tagebuch hat Euch angewiesen, die Ruinen des Palastes von Elune im Norden Sargeron zu suchen.", completion = "Nun ist es Euch klar, warum Ihr hierher geführt wurdet.\n\nIhr erkennt diesen uralten Runenstein aus Furiens letztem Tagebucheintrag: \n\n\"Die Uralten verehrten die Edelsteine, die von diesem mystischen Objekt erschaffen wurden und sie behaupteten, dass es Geschenke der Göttin selbst seien. Sie glaubten, es handele sich um Waffen, die in der Lage sind, sie von jedem Feind zu erlösen.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[14196] = { id = 14196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerteufel", description = "Ihr seid nun in der Lage den Text aus dem Tagebuch zu verstehen.\n\nAuf den Runensteinen steht geschrieben, dass den Edelsteinen des Monuments die Macht innewohnt, einen Feuersturm zu entfesseln.\n\nDer Sturm könnte zu einer mächtigen Waffe werden, indem Elune ausdauernd gehuldigt würde oder indem man ihn mit der spirituellen Energie der Gefallenen auflädt.\n\nIhr betrachtet die kürzlich aufgetauchten Geister von Elunes Anhängern und kommt zu dem Schluss, dass Ihr weder die Zeit noch die Neigung dazu habt, der Göttin Eures Feindes zu huldigen...", sourceObjective = "Ihr müsst einen tobenden Vortex erzeugen, indem Ihr 7 Anhänger von Elune mit Eurem Feuersturm vernichtet.\n\nSolltet Ihr Euren Vortexedelstein verlieren, erhaltet Ihr einen weiteren aus dem uralten Vortexrunenstein.", completion = "Es ist vollbracht! Furiens ausdauernde Forschung war nicht vergebens.\n\nDer tobende Vortex steht endlich bereit und kann auf Eure Feinde losgelassen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14197] = { id = 14197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zu erfüllendes Pensum", description = "Gebirgsfußeisen ist eine spröde Legierung, aber es erfüllt die Sicherheitsstandards der Goblins – wenn man die richtigen Leute schmiert. Zignibbel hat Schwierigkeiten bei der Produktion, aber das ändert nichts an meinen Fristen. Ich habe ein Pensum zu erfüllen!\n\nBegebt Euch in den Tagebau am Gebirgsfuß und sammelt so viel Barren Gebirgsfußeisen, wie Ihr finden könnt. Sie sollten dort stapelweise herumliegen und bereit zum Transport sein.", sourceObjective = "Sammelt 20 Barren Gebirgsfußeisen aus dem Tagebau am Gebirgsfuß in Azshara.", progress = "Habt Ihr die Lieferung?", completion = "Gute Arbeit! Wenn es um Eisen geht, ist mir die Quantität immer wichtiger als die Qualität.", sourceObjectiveStatus = "unverified-source-field" }
quests[14198] = { id = 14198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex der Vergeltung", description = "Ihr könnt Euch eines Anflugs von Stolz nicht erwehren, dass Ihr dieses lang verlorene Geheimnis der uralten Verehrer von Elune aufgedeckt habt.\n\nIhr besitzt nun die Macht, Eurem Feind großen Schaden zuzufügen.\n\nDa nur Furiens unermüdliche Arbeit dies ermöglicht hat, scheint es nur gerecht, dass diese Waffe auf diejenigen losgelassen werden sollte, die für seinen Tod verantwortlich sind.\n\nDer Abschaum der Allianz auf der Nijelspitze soll für den Angriff auf die Horde bezahlen!", sourceObjective = "Setzt den Edelstein des tobenden Vortexes gegen die Ruine der Nijelspitze ein. Während ihr den Feuersturm befehligt, tötet 40 Verteidiger der Nijelspitze und verbrennt 15 Händler der Nijelspitze.\n\nSolltet Ihr Euren Vortexedelstein verlieren, erhaltet Ihr einen weiteren aus dem uralten Vortexrunenstein.", completion = "Äußerst beeindruckend, {class}.\n\nIhr habt Furiens Arbeit abgeschlossen und Rache auf seine Mörder herabregnen lassen.\n\nIhr habt der Seele meines Bruders Frieden gebracht und meinem Geist ebenfalls. Bitte nehmt dieses Geschenk zum Dank für Euren Einsatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[14199] = { id = 14199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Der Schwarze Ritter", description = "Mein Berufsgenosse, Erzmagier Timear hat mich gebeten, Euch vor etwas Schrecklichem zu warnen. Bald werdet Ihr an der Prüfung der Champions im Argentumkolosseum in Eiskrone teilnehmen. Nehmt Euch in Acht, denn es wird sich jemand einmischen, den sie den Schwarzen Ritter nennen.\n\nBringt mir ein Fragment seiner Seele, damit die Kirin Tor wissen, dass er erledigt ist. Mir wurde gesagt, dass, solltet Ihr versagen, dies Euer eigenes Verderben sei.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein Seelenfragment des Schwarzen Ritters bringt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \"Heroisch\" abgeschlossen werden.", progress = "Ist es so, wie Timear es vorhergesehen hat? Ist der Schwarze Ritter unerwartet aufgetaucht?", completion = "Es ist gut zu sehen, dass Ihr siegreich aus der Prüfung hervorgegangen seid. Wahrlich, Ihr seid ein Champion - und zwar nicht nur für den Argentumkreuzzug, sondern in der Tat auch für die Kirin Tor.\n\nMan kann nur hoffen, dass Ihr dem dunklen Bösewicht den letzten Stoß verpasst habt und es das Letzte sein wird, das wir von ihm gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14201] = { id = 14201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausende Geschichten im Sand", description = "Die Ruinen um den Mennarsee im Osten erzählen eine Geschichte. Die niedrigeren Völker – wie diese plumpen Zwerge – würden mit Hacken und Schaufeln nach der Wahrheit suchen. <Malynea rümpft ihre Nase.> Wir werden ein wenig elegantere Verfahren einsetzen.\n\nMeine Wahrsagemagie ist ein wenig eingerostet, aber mit dem richtigen Schmuckstück sollte ich in der Lage sein, durch den Vorhang der Zeit zu sehen. Die Gebeine meiner Vorväter sind längst zu Staub zerfallen, aber ein paar ihrer persönlichen Schätze könnten noch existieren. Bringt sie mir.", sourceObjective = "Sammelt 5 geborgene Artefakte aus den Ruinen um den Mennarsee in Azshara.", progress = "Habt Ihr Euch für mich die Hände schmutzig gemacht?", completion = "<Malynea zieht die Augenbrauen zusammen und besieht die Artefakte, die Ihr ihr gebracht habt.>\n\nDie Geister der Toten gehen also noch immer in diesen alten Gemäuern um, wie? Nun, {name}, ich zähle auf ihre Hilfe. Hören wir uns an, was die Toten zu sagen haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[14202] = { id = 14202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiziert das Seeufer", description = "All diese verflixten uralten Ruinen müssen dem Erdboden gleichgemacht werden, wenn wir jemals Azsharas ganzes Potenzial sehen wollen. Werft einen Blick auf meine Karte hier. Seht Ihr den Mennarsee im Osten? Ich kann Euch sagen, was ich dort sehe: ein zukünftiges Lager für Raketentreibstoff!\n\nAber der Boden muss eine ganz besondere Beschaffenheit haben, bevor wir ihn abmähen, planieren, aufschütten und den See ebnen können. Meine Landvermesser wurden bisher alle von dem gespenstischen Spuk in der Region vergrault. Begleitet einen meiner Nachwuchsfeldmesser in das Gebiet und sorgt dafür, dass er die Ergebnisse der Messausrüstung ablesen kann, die dort aufgestellt wurden.", sourceObjective = "Begleitet den Goblinfeldmesser zu den drei Feldmessgeräten, die um den Mennarsee herum aufgestellt sind. Verteidigt ihn, während er die Geräte abliest. Ein weiterer Feldmesser kann stets über das Feldmesssignal herbeigerufen werden.", progress = "Ein Rudel toter Elfen kann den Fortschritt doch nicht aufhalten. Nicht solange ich noch was zu sagen habe!", completion = "Wundervolle Arbeit! Jetzt, wo wir die Region besser kennen, können wir uns des Sees annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14203] = { id = 14203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässtes Rezept", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...", sourceObjective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[14204] = { id = 14204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Schatten", description = "Er hat sich in einen von ihnen verwandelt ... nicht wahr? Wie sollen wir uns nur gegen einen Gegner behaupten, der etwas Derartiges anrichten kann?\n\nDas Arsenal meines Vaters ist bestimmt ein guter Anfang, denke ich.\n\nWorgen verbergen sich in den umliegenden Gassen. Nehmt einen meiner Mastiffs mit, um sie leichter finden zu können.\n\nWir müssen den Weg freiräumen, wenn wir diese Kanonen über Land bewegen wollen.", sourceObjective = "Besiegt 6 Blutfanglauerer.", progress = "Ist die Aufgabe erledigt, {name}?", completion = "Hervorragend. Ich werde ein paar Leute zusammentrommeln, um diese Kanonen in Position zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14209] = { id = 14209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motorschaden", description = "Diese uralten Ruinen haben zehntausend Jahre Wind und Wetter überstanden. Also habe ich meine größte und beste Planierraupe dorthin geschickt, um sie dem Erdboden gleichzumachen. Ich nenne sie 'Margene'.\n\nAber meine Raupe lässt mich neuerdings im Stich, {name}. In dem Augenblick, als ich mit ihr in diese verwunschenen Wälder gefahren bin, hat Ihr Motor mit einem markerschütternden Heulen den Geist aufgegeben. Jetzt sagen mir meine Ingenieure, dass irgendetwas ihre Ventile verstopft. Geht dorthin und untersucht Margenes Motorblock und bringt mir eine Probe von dem, was auch immer ihn blockiert.", sourceObjective = "Untersucht Clubniks Planierraupe und sammelt eine Probe des Ektospritzers ein, der den Motor verklebt.", progress = "Margene ist eine Höllenmaschine, nicht wahr?", completion = "Ich glaub, mein Kugellager knirscht! Seht Euch dieses Zeug an – igitt, RIECHT mal an diesem Zeug – meine arme, arme Raupe!\n\n{name}, ich halte mich selbst für einen Klebstoffspezialisten. Ich sage, dieses Klebzeug ist nicht natürlichen Ursprungs. Es ist übernatürlich. Das ist Geisterklebstoff. Dafür brauchen wir mehr als nur einen Mechaniker...", sourceObjectiveStatus = "unverified-source-field" }
quests[14212] = { id = 14212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufopferung", description = "Ihr müsst das nicht tun, {name}. Ihr habt bereits mehr als genug getan.\n\nAber wenn Ihr Euch entschließen solltet, zu bleiben ... Ich wäre ein Narr, Euch abzuweisen.\n\nMeine Mannen haben ihre Position in der Kathedrale befestigt und sind bereit für alles, was da kommen mag.\n\nIch werde mich nun auch dorthin aufmachen und so viele von diesen flohzersetzten Teufeln mit mir nehmen, wie ich nur kann. Seid willkommen, wenn Ihr mich zu diesem Tanz begleiten wollt.", sourceObjective = "Reitet mit Lord Darius Crowley und treibt 30 Blutfangpirscher zusammen.", completion = "Macht Euch bereit, {name}.\n\nHier kommen sie!", sourceObjectiveStatus = "unverified-source-field" }
quests[14213] = { id = 14213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Pfund Fleisch", description = "Furiens Tagebuch nach zu urteilen, wurde dieses uralte Kohlenbecken hier aufgestellt, um Opferrituale durchzuführen.\n\nSoweit Ihr das vom Eingang aus erkennen könnt, wird derjenige gesegnet, der das Fleisch von Elunes Feinden auf die brennenden Glutspäne im Kohlenbecken legt.\n\nIhr seht Euch um und beschließt, dass die Satyrn, welche die Region derzeit beherrschen, sicherlich als Feinde bezeichnet werden könnten.", sourceObjective = "Ihr müsst 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron beschaffen und sie in Elunes Kohlenbecken legen.", progress = "Das Becken erwartet still eine Opfergabe.", completion = "Das göttliche Becken versieht Euch unhinterfragt mit einem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14214] = { id = 14214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Graumähne", description = "Es ist soweit, {name}. Ab hier übernehmen wir.\n\nSagt König Graumähne, dass er über das Arsenal meines Vaters verfügen kann. Es beherbergt ausreichend Feuerkraft, die Worgen von hier bis zum Nordmeer zu schießen.", sourceObjective = "Sprecht mit König Graumähne im Militärviertel.", completion = "Ich wusste, dass Crowley uns helfen würde. Seine Waffen werden uns äußerst nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14215] = { id = 14215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erinnerung der Toten", description = "Die Runen auf diesem Ring, den Ihr gefunden habt, sind noch immer lesbar. Er wurde einer 'Kalytha' überreicht, als sie in die Akademie aufgenommen wurde. Mit ein oder zwei richtigen Zaubersprüchen ist dies das Tor zu Ihrer Seele.\n\nBringt den Ring zurück zum Mennarsee. Kalythas Geist sollte jetzt für Euch sichtbar sein, wenn ihr am Ufer des Sees steht. Berührt sie und der Ring wird es Euch ermöglichen, die Welt so zu sehen, wie sie ihr erscheint, und ihr könnt ihre letzten Stunden miterleben. Durchforstet ihren Geist, {name}! Sprecht mit den anderen und löst das Geheimnis des Mennarsees...", sourceObjective = "Bringt Kalythas Ring zum Ufer des Mennarsees. Berührt den Geist von Kalytha, um ihre Erinnerungen noch einmal zu erleben. Sprecht mit den anderen Geistern, bis Ihr das Geheimnis des Mennarsees gelüftet habt.", sourceObjectiveStatus = "unverified-source-field" }
